window.CASES_DATA = {
  vanstone: {
    id:'vanstone', name:'Vanstone v Clark', cite:'[2005] FCAFC 189; (2005) 224 ALR 232', icon:'⚖', color:'c-blue',
    topic:'W1', category:'Case',
    en:{ rule:'Delegated legislation must be reasonably proportionate to the purpose for which the power to make it was conferred. Power is not given "in gross" — the breadth of the regulation must match the purpose of the empowering Act. A definition that catches conduct far beyond what the Act\'s purpose justifies is ultra vires the empowering provision.',
         principle:'Vanstone is the leading Australian authority on proportionality review of delegated legislation. The test focuses on the fit between the regulation and the empowering Act\'s purpose; gross over-reach is invalid.',
         when:'Use Vanstone when a regulation, by-law or determination is alleged to sweep more broadly than the empowering Act\'s purpose can justify.',
         howApply:[
           'Identify the empowering provision and its purpose (read text + context).',
           'Compare the regulation\'s reach to that purpose — is the breadth reasonably proportionate, or grossly over-inclusive?',
           'If grossly over-inclusive, the regulation is invalid as ultra vires the empowering Act.'
         ],
         issue:'Whether the Minister\'s ATSIC Determination, by defining "misbehaviour" to include conviction of any imprisonable offence, exceeded the delegated authority.',
         conclusion:'Invalid — the definition lacked reasonable proportionality to the empowering Act\'s purpose.',
         keywords:['proportionality','delegated legislation','ATSIC','in gross'],
         facts:'A Ministerial Determination under the ATSIC Act provided that conviction of any imprisonable offence constituted "misbehaviour" warranting suspension or removal of an ATSIC commissioner.'},
    kr:{ rule:'위임입법은 권한이 부여된 목적에 합리적으로 비례해야 한다. 권한은 "in gross"로 부여되지 않으며, 규정의 포섭 범위는 수권법의 목적과 맞아야 한다. 그 법의 목적이 정당화할 수 있는 범위를 한참 넘어 행위를 잡는 정의는 수권 조항을 초과한 ultra vires이다.',
         principle:'Vanstone은 위임입법의 비례성 심사에 관한 호주의 선도 판례다. 규정과 수권법 목적의 맞춤을 본다 — 큰 폭의 과잉 포섭은 무효.',
         when:'규정·조례·결정이 수권법의 목적이 정당화할 수 있는 범위보다 넓게 휩쓴다고 다툴 때 인용한다.',
         howApply:[
           '수권 조항과 그 목적을 식별한다(문언 + 맥락).',
           '규정의 포섭 범위를 그 목적과 비교한다 — 합리적으로 비례하는가, 아니면 큰 폭으로 과잉 포섭인가.',
           '과잉 포섭이라면, 규정은 수권법을 초과해 무효(ultra vires).'
         ],
         issue:'장관의 ATSIC Determination이 "비위(misbehaviour)"를 징역 가능한 모든 범죄의 유죄로 정의한 것이 위임 권한을 초과했는가.',
         conclusion:'무효 — 정의가 수권법의 목적에 합리적으로 비례하지 않는다.',
         keywords:['비례성','위임입법','ATSIC','in gross'],
         facts:'ATSIC Act 아래 장관이 제정한 Determination이 징역 가능한 모든 범죄의 유죄판결을 "비위"로 규정해 ATSIC 위원의 정직·해임 사유로 삼았다.'}},
  evans: {
    id:'evans', name:'Evans v New South Wales', cite:'[2008] FCAFC 130; (2008) 168 FCR 576', icon:'✦', color:'c-coral',
    topic:'W1', category:'Case',
    en:{ rule:'Delegated legislation cannot impermissibly burden the implied freedom of political communication or other fundamental rights/freedoms; the principle of legality applies — express words are required to authorise such interference. A regulation that uses vague language ("annoyance", "inconvenience") to criminalise expression in a designated area exceeds power.',
         principle:'Evans applies the legality principle (Coco) to delegated legislation. Subordinate instruments cannot do what the empowering Act has not clearly authorised them to do, especially where fundamental rights are at stake.',
         when:'Use when a regulation, by-law or determination restricts speech, assembly, religion, or other recognised fundamental rights/freedoms without clear empowering words.',
         howApply:[
           'Identify the regulation and the right or freedom it restricts.',
           'Read the empowering Act for clear and unambiguous authorisation of that restriction (Coco / Saeed).',
           'If no clear words, the regulation is invalid as exceeding the delegated power.'
         ],
         issue:'Whether cl 7 of the World Youth Day Regulation — making it an offence to cause "annoyance or inconvenience" to participants in declared areas — was a valid exercise of delegated power.',
         conclusion:'Invalid — cl 7 exceeded the empowering Act and impermissibly burdened protected expression.',
         keywords:['World Youth Day','freedom of expression','legality principle','delegated leg'],
         facts:'NSW made the WYD Regulation in advance of World Youth Day 2008. Cl 7 made it an offence to cause "annoyance or inconvenience" to participants in declared areas.'},
    kr:{ rule:'위임입법은 정치적 표현의 묵시적 자유 같은 기본권·자유를 부당하게 제한할 수 없다. 합법성 원칙이 적용된다 — 그런 침해를 수권하려면 명시적 문언이 필요하다. 지정 구역에서의 표현을 모호한 단어("성가심", "불편")로 범죄화하는 규정은 권한을 초과한다.',
         principle:'Evans는 합법성 원칙(Coco)을 위임입법에 적용한다. 하위 수단은 수권법이 분명하게 수권하지 않은 일을 할 수 없으며, 특히 기본권이 걸린 자리에서는 더더욱 그렇다.',
         when:'규정·조례·결정이 표현·집회·종교 등 인정되는 기본권·자유를 분명한 수권 문언 없이 제한할 때 인용한다.',
         howApply:[
           '문제된 규정과 그것이 제한하는 권리·자유를 식별한다.',
           '수권법에서 그 제한을 분명하고 모호하지 않게 수권하는 문언을 찾는다(Coco / Saeed).',
           '분명한 문언이 없다면 그 규정은 위임 권한을 초과해 무효.'
         ],
         issue:'World Youth Day Regulation cl 7 — 지정 구역에서 참가자에게 "성가심 또는 불편"을 야기하는 행위를 범죄화한 조항 — 이 위임 권한의 적법한 행사였는가.',
         conclusion:'무효 — cl 7은 수권법을 초과하고 보호되는 표현을 부당히 제한했다.',
         keywords:['World Youth Day','표현의 자유','합법성 원칙','위임입법'],
         facts:'NSW가 2008 World Youth Day를 앞두고 WYD Regulation을 제정했다. cl 7은 지정 구역 내 참가자에게 "성가심 또는 불편"을 야기하는 행위를 범죄로 규정했다.'}},
  toohey: {
    id:'toohey', name:'R v Toohey; Ex parte Northern Land Council', cite:'[1981] HCA 74; (1981) 151 CLR 170', icon:'☷', color:'c-forest',
    topic:'W1', category:'Case',
    en:{ rule:'A statutory power is not normally conferred without purpose or criteria — courts construe empowering statutes purposively, and a power must be exercised consistently with the purposes of the Act that conferred it. A power apparently exercised to defeat the purposes of the empowering scheme is outside power.',
         principle:'Toohey is an early statement of the purposive limit on apparently broad statutory powers. Even a power expressed in unqualified terms is impliedly bounded by the purposes of the empowering Act.',
         when:'Use when arguing that an apparently broad or unqualified statutory power has implied purposive limits — particularly where the impugned exercise looks designed to defeat or evade the empowering scheme.',
         howApply:[
           'Identify the empowering Act and its purposes (text, scheme, context).',
           'Show how the impugned exercise is inconsistent with — or defeats — those purposes.',
           'Argue that purposive limits are implied; an exercise outside those limits is ultra vires.'
         ],
         issue:'Whether the Administrator\'s power to declare the boundaries of Darwin had implied purposive limits, given the apparent purpose of defeating an Aboriginal land claim.',
         conclusion:'Power must be exercised consistently with the purposes of the Act; an exercise apparently designed to defeat the Aboriginal Land Rights (NT) Act fell outside those implied limits.',
         keywords:['empowering Act','statutory construction','purposive','implied limits'],
         facts:'The NT Administrator declared the boundaries of Darwin in a way alleged to be designed to defeat an Aboriginal land claim under the Aboriginal Land Rights (NT) Act 1976.'},
    kr:{ rule:'법령상 권한은 통상 목적이나 기준 없이 부여되지 않는다 — 법원은 수권법을 목적론적으로 해석하고, 권한은 그것을 부여한 법의 목적에 부합되게 행사되어야 한다. 수권 체계의 목적을 무력화하기 위해 외관상 행사된 권한은 권한 밖이다.',
         principle:'Toohey는 외관상 광범한 법령상 권한에도 목적론적 한계가 있다는 점을 일찍이 정리한 판례다. 무조건 문언으로 표현된 권한이라도 수권법의 목적에 묵시적으로 묶인다.',
         when:'외관상 광범하거나 무조건적인 법령상 권한에 묵시적 목적 한계가 있다고 주장할 때 — 특히 다투어진 행사가 수권 체계를 무력화·회피하려는 의도로 보일 때 — 인용한다.',
         howApply:[
           '수권법과 그 목적을 식별한다(문언, 체계, 맥락).',
           '다투어진 행사가 그 목적과 어떻게 모순되는지(또는 무력화하는지) 보인다.',
           '목적적 한계가 묵시되어 있고, 그 한계 밖의 행사는 ultra vires임을 주장한다.'
         ],
         issue:'Aboriginal 토지 청구를 무력화하려는 목적이 외관상 보였을 때, NT 행정관의 다윈 경계 선언 권한에 묵시적 목적 한계가 있는가.',
         conclusion:'권한은 그 법의 목적에 부합되게 행사되어야 한다. Aboriginal Land Rights (NT) Act를 무력화하려는 외관상 의도의 행사는 그 묵시적 한계 밖이다.',
         keywords:['수권법','법령 해석','목적론적','묵시적 한계'],
         facts:'NT 행정관이 Aboriginal Land Rights (NT) Act 1976 아래의 Aboriginal 토지 청구를 무력화하기 위한 것으로 주장된 방식으로 다윈 경계를 선언했다.'}},
  coco: {
    id:'coco', name:'Coco v The Queen', cite:'[1994] HCA 15; (1994) 179 CLR 427', icon:'🛡', color:'c-ochre',
    topic:'W1', category:'Common Law Principle',
    en:{ rule:'Statutes are presumed not to abrogate fundamental rights, freedoms or immunities in the absence of unmistakable and unambiguous statutory language. Even broad general words will not be read as authorising interference with a recognised common-law right unless that interference is the necessary or only available reading. This is the principle of legality.',
         principle:'Coco is the leading Australian articulation of the principle of legality. It is a presumption of statutory interpretation, not a constitutional rule — Parliament can override fundamental rights, but must do so explicitly. Saeed extended the principle to procedural fairness; Evans applied it to delegated legislation burdening freedoms.',
         when:'Cite Coco whenever a statute or delegated instrument is said to authorise interference with a recognised fundamental right, freedom or immunity (property, liberty, free expression, common-law privileges, etc.).',
         howApply:[
           'Identify the fundamental right, freedom or immunity at stake.',
           'Read the statute / instrument for unmistakable and unambiguous language authorising the interference.',
           'If the language is general or ambiguous, read it down — Parliament is presumed not to have intended the interference.'
         ],
         issue:'Whether a statutory authorisation for police to install a listening device permitted them to trespass on private property to do so, in the absence of express words authorising trespass.',
         conclusion:'Trespass not authorised — clear words required to abrogate the property right against trespass.',
         keywords:['legality principle','fundamental rights','unmistakable language','presumption'],
         facts:'Police installed a listening device on private property under a statutory authorisation. The question was whether the authorisation impliedly permitted trespass to install it.'},
    kr:{ rule:'법률은 분명하고 모호하지 않은 법령 문언이 없는 한 기본권·자유·면제를 폐지하는 것으로 추정되지 않는다. 광범한 일반 문언이라도, 그 침해가 필연적이거나 유일하게 가능한 해석이 아니라면, 인정된 보통법상 권리에 대한 침해를 수권하는 것으로 읽지 않는다. 이게 합법성 원칙(principle of legality).',
         principle:'Coco는 호주에서 합법성 원칙을 가장 또렷이 정리한 판결이다. 헌법 규칙이 아니라 법령 해석 추정 — 의회는 기본권을 무효화할 수 있지만 명시적으로 해야 한다. Saeed는 이 원칙을 절차적 공정에 확장했고, Evans는 자유를 제한하는 위임입법에 적용했다.',
         when:'법령이나 위임 수단이 인정된 기본권·자유·면제(재산, 자유, 표현, 보통법상 특권 등)에 대한 침해를 수권한다고 할 때 인용한다.',
         howApply:[
           '걸린 기본권·자유·면제를 식별한다.',
           '법령·수단이 그 침해를 분명하고 모호하지 않게 수권하는 문언을 가지고 있는지 본다.',
           '문언이 일반적이거나 모호하다면 좁게 읽는다 — 의회는 그 침해를 의도하지 않은 것으로 추정된다.'
         ],
         issue:'경찰이 청취기 설치를 수권받은 법령이 명시적 문언 없이 사유지 침입까지 수권하는가.',
         conclusion:'침입은 수권되지 않았다 — 침입에 대한 재산권을 폐지하려면 분명한 문언이 필요하다.',
         keywords:['합법성 원칙','기본권','분명한 언어','해석 추정'],
         facts:'경찰이 법령상 수권에 따라 사유지에 청취기를 설치한 사건. 그 수권이 설치를 위한 침입까지 묵시적으로 허용하는지가 쟁점이었다.'}},
  kruse: {
    id:'kruse', name:'Kruse v Johnson', cite:'[1898] 2 QB 91', icon:'∥', color:'c-gray',
    topic:'W1', category:'Case',
    en:{ rule:'Local by-laws are to be benevolently construed and presumed valid; they are invalid only where so unreasonable that no reasonable authority could have made them. The unreasonableness threshold is high — mere disagreement with the by-law\'s policy is not enough.',
         principle:'Kruse is the historical anchor for unreasonableness review of subordinate legislation. The "no reasonable authority could have made" formulation prefigured Wednesbury\'s extreme test, later softened by Li for substantive decisions but still a useful baseline for delegated legislation.',
         when:'Use as the historical/baseline citation for unreasonableness review of by-laws or other subordinate legislation.',
         howApply:[
           'Identify the by-law or subordinate instrument and start with the benevolent-construction presumption.',
           'Apply the high unreasonableness threshold — invalid only where no reasonable authority could have made it.',
           'For modern substantive decisions, run Li\'s "evident and intelligible justification" test instead; for delegated legislation Kruse\'s baseline still applies.'
         ],
         issue:'Whether a by-law making it an offence to sing in the streets within 50 yards of a dwelling, after request to desist, was so unreasonable as to be invalid.',
         conclusion:'Upheld — the by-law was not so unreasonable that no reasonable authority could have made it.',
         keywords:['Wednesbury','benevolent construction','by-laws','baseline'],
         facts:'Kruse was charged under a by-law prohibiting singing in streets within 50 yards of a dwelling after a request to desist had been made.'},
    kr:{ rule:'지방 조례는 호의적으로 해석되고 유효한 것으로 추정된다. 합리적 당국이라면 결코 만들지 않았을 정도로 비합리적인 경우에만 무효이다. 비합리성 문턱이 높다 — 조례 정책에 대한 단순한 이견으로는 부족하다.',
         principle:'Kruse는 위임입법에 대한 비합리성 심사의 역사적 기준점이다. "합리적 당국이라면 만들지 않았을" 정식은 Wednesbury의 극단 기준을 예고했고, 실체적 결정에는 Li가 이를 완화했지만 위임입법에 대한 기본선으로는 여전히 유용하다.',
         when:'조례나 다른 위임입법의 비합리성 심사의 역사적·기본선 인용으로 사용한다.',
         howApply:[
           '조례나 위임 수단을 식별하고 호의적 해석 추정에서 출발한다.',
           '높은 비합리성 문턱을 적용한다 — 합리적 당국이라면 만들지 않았을 경우에만 무효.',
           '현대 실체적 결정에는 Li의 "evident and intelligible justification" 기준을 대신 돌리고, 위임입법에는 Kruse의 기본선이 여전히 적용된다.'
         ],
         issue:'주거지 50야드 내에서, 중지 요청 후에도 거리에서 노래하는 것을 범죄화한 조례가 무효라고 할 만큼 비합리적인가.',
         conclusion:'유효 — 합리적 당국이라면 결코 만들지 않았을 정도로 비합리적이지는 않다.',
         keywords:['Wednesbury','호의적 해석','조례','기본선'],
         facts:'Kruse가 주거지 50야드 내에서 중지 요청을 받은 뒤에도 노래한 혐의로, 그 행위를 금지하는 조례 위반으로 기소된 사건.'}},
  pbs: {
    id:'pbs', name:'Project Blue Sky Inc v Australian Broadcasting Authority', cite:'[1998] HCA 28; (1998) 194 CLR 355', icon:'◰', color:'c-blue',
    topic:'W2', category:'Case',
    en:{ rule:'Whether the breach of a statutory condition invalidates a decision turns on Parliament\'s intention as to the consequences of breach — to be ascertained from the text, context, scope and purpose of the empowering Act, not from a label. The old "mandatory / directory" dichotomy states a conclusion, not a test.',
         principle:'Project Blue Sky put statutory interpretation at the centre of validity. Instead of asking "is this provision mandatory or directory?" — a labelling exercise — the court asks what consequence Parliament actually intended for breach of this particular condition. This is now Stage 2 of the Hossain framework: once you have identified the condition, PBS tells you whether breach goes to validity. The case also matters institutionally — it confirmed that the ordinary tools of statutory construction (scheme, purpose, surrounding provisions) do the work, not freestanding common-law presumptions.',
         when:'Apply PBS at Hossain Stage 2 — once you have identified the statutory condition, before you reach for materiality. Use it whenever the question is whether a particular breach of a particular condition was intended to invalidate the decision.',
         howApply:[
           'Identify the specific condition that has been breached and quote it from the empowering Act.',
           'Read the condition in its full statutory context — scheme, surrounding provisions, purpose.',
           'Ask: did Parliament intend breach of this condition to invalidate the decision? Look at how essential the condition is to the statutory scheme, the consequences of treating breach as invalidating, and any explicit consequence in the Act.',
           'Resist the labels "mandatory" and "directory" — they describe the answer, not the inquiry.',
           'If breach is intended to invalidate, the condition is a validity condition → proceed to materiality (Hossain Stage 3). If not, the breach does not produce JE.'
         ],
         issue:'Whether breach of s 160 of the Broadcasting Services Act 1992 (Cth) — which required the ABA to perform its functions consistently with Australia\'s international obligations — invalidated a content standard the ABA made.',
         conclusion:'The standard was not invalid. Construing s 160 in context, Parliament did not intend breach to vitiate the validity of standards otherwise made under power.',
         keywords:['validity','mandatory directory','Parliament intent','statutory construction'],
         facts:'The ABA made a Television Program Standard that was inconsistent with the Australia–New Zealand Closer Economic Relations agreement, which Australia was bound to honour under s 160 of the Broadcasting Services Act. Project Blue Sky challenged the standard\'s validity.'},
    kr:{ rule:'법령상 조건의 위반이 결정을 무효로 만드는지는 의회가 그 위반의 결과를 어떻게 의도했는지에 달려 있다 — 그 의도는 라벨이 아니라 수권법의 조문·맥락·범위·목적에서 읽어 낸다. 옛 "mandatory / directory" 구분은 결론에 붙이는 라벨일 뿐, 분석의 도구가 아니다.',
         principle:'Project Blue Sky는 유효성 판단의 중심을 법령 해석으로 옮긴 판결이다. "이 조항이 강행인가 훈시인가"라는 라벨 붙이기가 아니라, "의회가 이 특정 조건의 위반에 어떤 결과를 의도했는가"를 묻는 식으로 바뀌었다. 이게 곧 Hossain framework의 2단계 — 조건을 식별한 다음, PBS가 그 위반이 유효성에 가는지 알려 주는 자리야. 보통의 법령 해석 도구(체계·목적·인접 조항)가 일을 한다는 점, 별도의 보통법 추정에 기댈 일이 아니라는 점도 이 판결이 정리했다.',
         when:'Hossain 2단계에서, 조건을 식별한 다음 materiality로 넘어가기 전에 적용한다. "이 조건의 이 위반이 결정을 무효로 만들도록 의도됐는가"가 쟁점일 때 꺼낸다.',
         howApply:[
           '위반된 특정 조건을 짚어 내고 수권법에서 직접 인용한다.',
           '그 조건을 법령 체계·인접 조항·목적까지 함께 본다.',
           '의회가 이 조건의 위반을 결정 무효로 의도했는지 묻는다 — 조건이 법령 체계에서 얼마나 본질적인지, 무효로 보았을 때의 결과, 법령에 명시된 결과 조항이 있는지 등을 본다.',
           '"강행/훈시" 라벨에 의존하지 않는다 — 그 라벨들은 답을 묘사할 뿐, 분석의 도구가 아니다.',
           '위반이 무효를 의도했다면 그 조건은 유효성 조건 → Hossain 3단계(materiality)로 진행. 의도되지 않았다면 그 위반은 JE를 일으키지 않는다.'
         ],
         issue:'Broadcasting Services Act 1992 (Cth) s 160 — ABA가 호주의 국제의무와 부합되게 직무를 수행하도록 요구한 조항 — 의 위반이 ABA가 만든 콘텐츠 표준의 유효성을 무효로 만드는가.',
         conclusion:'표준은 무효가 아니다. s 160을 맥락 속에서 해석하면, 의회는 이 위반이 권한 내에서 만들어진 표준의 유효성을 침해하도록 의도하지 않았다.',
         keywords:['유효성','mandatory directory','의회 의도','법령 해석'],
         facts:'ABA가 만든 텔레비전 프로그램 표준이, 호주가 s 160에 따라 준수해야 했던 호주-뉴질랜드 경제관계강화협정과 부합하지 않았다. Project Blue Sky가 그 표준의 유효성을 다툰 사건.'}},
  quin: {
    id:'quin', name:'Attorney-General (NSW) v Quin', cite:'[1990] HCA 21; (1990) 170 CLR 1', icon:'⊝', color:'c-ink',
    topic:'W2', category:'Case',
    en:{ rule:'Judicial review polices the legality of administrative decisions, not their merits. The court asks whether the decision-maker stayed within the powers and conditions Parliament conferred — it does not ask whether the decision was wise, fair on the merits, or the decision the court would have made. Brennan J: review is "concerned with the legality, not the merits" of administrative action.',
         principle:'Quin is the canonical statement of the legality / merits divide in Australian administrative law. The principle is structural: courts cannot re-weigh the considerations or substitute their own preferred outcome, because doing so would collapse the separation between the executive\'s power to decide and the court\'s power to supervise legality. Every JR answer should hold this line — when an applicant\'s real complaint is "the decision was wrong on the merits", the right pathway is merits review (W11 ART), not JR. Quin also clipped the legitimate-expectation doctrine, which was later all but buried by Lam.',
         when:'Cite Quin whenever you need to anchor the boundary — for instance, when an unreasonableness or considerations argument is starting to look like reweighting, or when explaining why the court will not substitute its own view of the right outcome.',
         howApply:[
           'Frame the inquiry as a legality question, not an outcome question — "did the decision-maker exceed power, breach a condition, fail to take into account a mandatory consideration?" rather than "was the decision right?".',
           'If the applicant\'s real complaint is that the decision was wrong on the facts or wrong on the merits, redirect them to merits review (ART) rather than JR.',
           'For unreasonableness arguments, remind yourself that Li does not collapse the divide — the court still does not reweigh, it asks whether the result lacks evident and intelligible justification.',
           'Avoid "legitimate expectation" framings — Quin trimmed the doctrine and Lam reframed PF around practical injustice instead.'
         ],
         issue:'Whether the NSW Attorney-General\'s decision not to reappoint certain stipendiary magistrates after restructuring the magistracy was reviewable on legitimate-expectation grounds.',
         conclusion:'No reviewable error — the AG was not bound to reappoint, and any expectation of reappointment did not constrain a legitimate exercise of executive power. The legality / merits boundary was preserved.',
         keywords:['legality vs merits','judicial review limits','Brennan J','legitimate expectation'],
         facts:'The NSW Government restructured the magistracy, abolishing the office of stipendiary magistrate and creating new positions. Some sitting magistrates were not reappointed and challenged the decision, arguing they had a legitimate expectation of being reappointed.'},
    kr:{ rule:'사법심사는 행정결정의 적법성을 단속하지, 본안의 옳고 그름을 단속하지 않는다. 법원은 결정자가 의회가 부여한 권한과 조건 안에 머물렀는지를 묻고, 결정이 현명했는지·본안에서 공정했는지·법원이라면 어떤 결정을 했을지는 묻지 않는다. Brennan J: 사법심사는 행정작용의 "본안이 아니라 적법성"을 다룬다.',
         principle:'Quin은 호주 행정법의 적법성·본안 구분을 가장 또렷이 정리한 판결이다. 이 원칙은 구조적이야 — 법원이 고려사항을 다시 가중치 매기거나 자기 선호 결과로 대체한다면, 결정 권한(행정)과 적법성 감독 권한(법원) 사이의 분리가 무너진다. 모든 JR 답안은 이 선을 유지해야 한다. 신청인의 진짜 불만이 "본안에서 틀렸다"라면 맞는 통로는 실체심사(W11 ART)지 JR이 아니다. Quin은 정당한 기대(legitimate expectation) 법리도 좁혔는데, 이 법리는 이후 Lam에서 사실상 묻혔다.',
         when:'경계선을 정초할 때 인용한다 — 예컨대 비합리성·관련 고려사항 주장이 점점 가중치 재매김처럼 보이기 시작할 때, 또는 법원이 "옳은 결과"를 대신 정해 주지 않는 이유를 설명할 때.',
         howApply:[
           '쟁점을 결과 질문이 아니라 적법성 질문으로 짠다 — "결정자가 권한을 넘었는가, 조건을 위반했는가, 강행 고려사항을 누락했는가"이지 "결정이 옳았는가"가 아니다.',
           '신청인의 진짜 불만이 사실판단이나 본안의 잘못이라면 JR이 아니라 실체심사(ART)로 돌려야 한다.',
           '비합리성 주장에서도 Li가 이 구분을 무너뜨리지 않는다는 점을 잊지 않는다 — 법원은 여전히 가중치를 다시 매기지 않고, 결과에 evident and intelligible justification이 있는지만 묻는다.',
           '"정당한 기대" framing은 피한다 — Quin이 법리를 좁혔고, Lam이 PF 분석을 "실질적 부정의" 축으로 다시 짰다.'
         ],
         issue:'NSW 법무장관이 치안판사단 재편 후 특정 치안판사들을 재임명하지 않은 결정을, 정당한 기대를 근거로 사법심사할 수 있는가.',
         conclusion:'사법심사 대상의 오류 없음 — 법무장관에게 재임명 의무는 없었고, 재임명 기대가 적법한 행정권 행사를 구속하지 않는다. 적법성·본안 경계가 유지됐다.',
         keywords:['합법성 vs 본안','사법심사의 한계','Brennan J','정당한 기대'],
         facts:'NSW 정부가 치안판사단을 재편하면서 stipendiary magistrate 직을 폐지하고 새 직을 만들었다. 재임명되지 못한 일부 치안판사들이 정당한 기대를 근거로 결정을 다툰 사건.'}},
  bond: {
    id:'bond', name:'Australian Broadcasting Tribunal v Bond', cite:'[1990] HCA 33; (1990) 170 CLR 321', icon:'◉', color:'c-blue',
    topic:'W2', category:'Case',
    en:{ rule:'A "decision" for the purposes of s 5 of the ADJR Act is a substantive determination that is final, operative and determinative — usually the ultimate or operative outcome of the statutory process. Preliminary or intermediate steps in the reasoning chain are normally "conduct" reviewable under s 6, not "decisions" reviewable under s 5.',
         principle:'Bond drew the s 5 / s 6 line that controls ADJR jurisdiction. The functional consequence: clients cannot run to the Federal Court to challenge every interim finding along the way to a decision; they generally have to wait for the substantive operative outcome (s 5) or use the narrower s 6 conduct-review path. The case also matters because it highlighted ADJR\'s structural narrowness — when a "decision" is held not to exist, the applicant must pivot to s 75(v) (the constitutional writ jurisdiction) or s 39B(1) (Cth officers) under Plaintiff S157, which cannot be ousted by privative clause.',
         when:'Bond is the threshold filter for ADJR jurisdiction. Reach for it whenever the respondent argues that what the applicant is challenging is not a "decision" — typical contexts: interim findings, recommendations, internal investigative steps, advisory determinations.',
         howApply:[
           'Identify with precision what the applicant says is the "decision" being challenged.',
           'Ask whether it is final, operative and determinative on the relevant question — i.e., does it itself produce the legal effect, or is it a step toward producing one?',
           'If it is preliminary or intermediate, consider whether s 6 ADJR conduct review (or non-statutory review) is available instead.',
           'If ADJR is unavailable because the act is not a "decision", pivot to s 75(v) / s 39B(1) under Plaintiff S157 — JR for jurisdictional error is constitutionally entrenched and cannot be ousted.'
         ],
         issue:'Whether the Australian Broadcasting Tribunal\'s interim findings about Alan Bond\'s fitness to hold broadcasting licences — made before the Tribunal\'s final orders — were "decisions" reviewable under s 5 of the ADJR Act.',
         conclusion:'No — the interim findings were preliminary steps in the reasoning, not "decisions" under s 5. They could, however, be reviewable as "conduct" preparatory to the making of a decision under s 6.',
         keywords:['Bond test','decision','ADJR','final operative determinative'],
         facts:'The ABT inquired into whether Alan Bond was fit to hold his broadcasting licences. Before reaching its final orders, it made interim findings adverse to Bond. The challenge was whether those interim findings could be attacked as "decisions" under ADJR s 5.'},
    kr:{ rule:'ADJR Act s 5의 "결정"은 최종적·실효적·결정적인 실체 판단이다 — 보통 법령 절차의 종국적 또는 실효적 결과를 가리킨다. 그 결과에 이르는 추론의 예비적·중간적 단계는 통상 s 5의 "결정"이 아니라 s 6의 "행위(conduct)"로 다루어진다.',
         principle:'Bond는 ADJR 관할을 가르는 s 5 / s 6 경계선을 그은 판결이다. 실무적 효과는 — 결정에 이르는 모든 잠정 판단을 들고 연방법원으로 달려갈 수 없고, 통상은 실체적 실효적 결과(s 5)를 기다리거나 좁은 s 6 행위 심사로 가야 한다. 이 판결은 ADJR의 구조적 좁음도 드러낸다 — "결정"이 없다고 인정되면 Plaintiff S157에 따라 s 75(v)(헌법상 writ 관할)나 s 39B(1)(연방 공무원)로 갈아타야 한다. 관할권적 오류에 대한 사법심사는 헌법적으로 보호되어 배제조항으로 봉쇄되지 않는다.',
         when:'ADJR 관할의 관문 필터로 쓴다. 피고측이 "이건 결정이 아니다"라고 다툴 때 — 잠정 인정, 권고, 내부 조사 단계, 자문 판단 등의 전형적 맥락에서 — 가장 먼저 떠올린다.',
         howApply:[
           '신청인이 다투려는 "결정"이 정확히 무엇인지 짚는다.',
           '그것이 해당 문제에 대해 최종·실효·결정적인지 묻는다 — 그 자체가 법적 효과를 만들어 내는가, 아니면 효과를 만들기 위한 한 단계인가?',
           '예비적·중간적 단계라면 s 6 ADJR 행위 심사(또는 비-법정 심사)가 가능한지 검토한다.',
           '"결정"이 아니어서 ADJR이 막히면 Plaintiff S157에 따라 s 75(v) / s 39B(1)로 갈아탄다 — 관할권적 오류에 대한 JR은 헌법적으로 보호된다.'
         ],
         issue:'호주방송심판소(ABT)가 최종 명령 전에 Alan Bond의 방송면허 적격성에 대해 한 잠정 인정이 ADJR s 5의 "결정"으로 사법심사 대상인가.',
         conclusion:'아니다 — 잠정 인정은 추론 과정의 예비 단계이지 s 5의 "결정"이 아니다. 다만 결정 준비 행위로서 s 6 심사 대상은 될 수 있다.',
         keywords:['Bond 테스트','결정','ADJR','최종·실효·결정적'],
         facts:'ABT가 Alan Bond의 방송면허 적격성을 심사하면서, 최종 명령 전에 Bond에게 불리한 잠정 인정을 했다. 그 잠정 인정을 ADJR s 5의 "결정"으로 다툴 수 있는지가 쟁점이었다.'}},
  tang: {
    id:'tang', name:'Griffith University v Tang', cite:'[2005] HCA 7; (2005) 221 CLR 99', icon:'⛓', color:'c-blue',
    topic:'W3', category:'Case',
    en:{ rule:'A decision is "made under an enactment" for ADJR purposes only if two limbs are satisfied:\n(1) the decision is one for which provision is made by, or under, the enactment (it is expressly or impliedly authorised or required by the statute); AND\n(2) the decision itself confers, alters or otherwise affects legal rights or obligations — and does so by reason of the statute, not by some independent source such as contract or internal rules.',
         principle:'Tang tightened the gateway to ADJR. A statutory body acting under its own internal rules does not necessarily make a "decision under an enactment" — the test asks whether the legal effect on rights flows from the statute itself, or from a separate, non-statutory source. The case is the modern lodestar for cases at the ADJR boundary: universities, professional bodies, regulators making decisions under internal codes. When Tang excludes ADJR, the applicant\'s pivot is usually to s 75(v) or s 39B(1) (officers of the Commonwealth) under Plaintiff S157, or to State supervisory jurisdiction under Kirk.',
         when:'Apply Tang whenever a decision-maker is a body created or empowered by statute, but the impugned decision was made under internal rules, codes of practice, contracts, or other sub-statutory instruments. The question is always: where does the legal effect on the applicant\'s rights actually come from?',
         howApply:[
           'Identify the empowering statute and the source of the impugned decision (statutory rule? internal regulation? contract? policy?).',
           'Test limb 1: is the decision one for which provision is made by or under the Act? If the source is purely contractual or internal, limb 1 may fail.',
           'Test limb 2: does the decision itself alter legal rights or obligations? If yes, ask whether that alteration flows from the statute or from a separate source. The latter falls outside ADJR.',
           'If ADJR fails on Tang, pivot — s 75(v) for constitutional writs against Cth officers, s 39B(1) under S157 framing, or State Supreme Court supervisory jurisdiction (Kirk).'
         ],
         issue:'Whether Griffith University\'s decision to exclude a PhD candidate for research misconduct, made under the University\'s internal academic misconduct policy, was a decision "under an enactment" reviewable under ADJR.',
         conclusion:'No — although the University was created by statute, the exclusion was made under internal rules, not under the empowering Act. The legal effect (such as it was) did not flow from a statute. ADJR did not apply.',
         keywords:['under enactment','two limbs','statutory force','ADJR gateway'],
         facts:'A PhD candidate at Griffith University was excluded from her course after the University found research misconduct under its internal academic misconduct policy. She sought ADJR review, arguing the decision was "under the enactment" that established the University.'},
    kr:{ rule:'어떤 결정이 ADJR상 "수권법에 따른(under an enactment)" 결정이려면 두 단계를 모두 충족해야 한다.\n(1) 그 결정이 법령에 의해 또는 법령 아래에서 마련된 것 — 즉 명시적·묵시적으로 법령이 수권하거나 요구하는 결정일 것;\n그리고\n(2) 그 결정 자체가 법적 권리·의무를 부여·변경하거나 영향을 줄 것 — 그것도 법령 자체의 효력에 의해서지, 계약이나 내부 규정 같은 독립된 원천에 의해서가 아니다.',
         principle:'Tang은 ADJR의 관문을 좁힌 판결이다. 법령으로 설립된 기관이 내부 규정에 따라 행동했다고 해서 자동으로 "수권법에 따른 결정"이 되지는 않는다 — 핵심은 권리에 미치는 법적 효과가 법령 자체에서 흘러나오는가, 아니면 별도의 비-법령 원천에서 나오는가이다. 대학·전문직 단체·내부 규정에 따라 결정하는 규제기관처럼 ADJR 경계에 있는 사건의 현대적 등대다. Tang으로 ADJR이 막히면 보통 Plaintiff S157 framing의 s 75(v)나 s 39B(1)(영연방 공무원), 또는 Kirk의 주(州) 감독관할로 갈아탄다.',
         when:'결정자가 법령으로 설립·수권된 기관이지만, 다투어진 결정이 내부 규정·실무규약·계약·기타 하위 도구에 따라 내려진 경우에 적용한다. 질문은 항상 동일하다: 신청인의 권리에 대한 법적 효과는 어디에서 나오는가?',
         howApply:[
           '수권법과 다투어진 결정의 근거 원천을 식별한다(법정 규정인가, 내부 규정인가, 계약인가, 정책인가).',
           '1단계 검증: 그 결정이 그 법령에 의해 또는 법령 아래에서 마련된 결정인가? 근거가 순전히 계약적이거나 내부적이라면 1단계가 안 넘어갈 수 있다.',
           '2단계 검증: 그 결정 자체가 법적 권리·의무를 변경하는가? 그렇다면, 그 변경이 법령에서 나오는가 아니면 별도 원천에서 나오는가? 후자라면 ADJR 밖이다.',
           'Tang으로 ADJR이 막히면 갈아탄다 — 영연방 공무원에 대한 헌법적 writ는 s 75(v), Plaintiff S157 framing은 s 39B(1), 주 결정은 주 대법원 감독관할(Kirk).'
         ],
         issue:'Griffith University가 내부 학술 부정행위 정책에 따라 박사과정생을 제명한 결정이 ADJR상 "수권법에 따른" 결정인가.',
         conclusion:'아니다 — 대학이 법령으로 설립됐다 하더라도, 제명은 수권법이 아니라 내부 규정에 따른 것이었다. 법적 효과(있다면)도 법령에서 흘러나오지 않았다. ADJR이 적용되지 않는다.',
         keywords:['수권법에 따른','2단계','법적 효력','ADJR 관문'],
         facts:'Griffith University의 박사과정생이 대학의 내부 학술 부정행위 정책에 따른 조사 후 제명됐다. 그녀는 그 결정이 대학을 설립한 "수권법에 따른" 것이라며 ADJR 심사를 구했다.'}},
  argos: {
    id:'argos', name:'Argos Pty Ltd v Corbell', cite:'[2014] HCA 50; (2014) 254 CLR 394', icon:'⌅', color:'c-teal',
    topic:'W9', category:'Case',
    en:{ rule:'A third party who suffers economic detriment as a foreseeable, direct consequence of a statutory decision can have their interests affected "through statutory force" for ADJR purposes — and is therefore a "person aggrieved" with standing. The harm need not be a strict legal right; commercial detriment from a planning approval that authorises a competing use is enough.',
         principle:'Argos extended ADJR\'s "person aggrieved" / Tang-second-limb analysis to commercial competitors. The case rejected a narrow reading of "rights affected through statutory force" — the relevant question is whether the impugned decision, by force of the empowering Act, brings about a real economic consequence for the applicant. Argos also pulled back against an attempt to read Right to Life through a "statutory context" lens that would have constrained standing to interests the statute itself recognises; the proper question is the substance of the consequence, not the statute\'s thematic focus. The case sits alongside Bateman\'s Bay (commercial position) and ACF (the baseline) in defining standing\'s outer reach.',
         when:'Cite Argos in two contexts:\n(1) when a commercial competitor wants to challenge a planning, licensing or regulatory approval that lets a rival operate\n(2) when defending standing against a "your interest is not statutorily recognised" argument.',
         howApply:[
           'Identify the impugned decision and the statutory power that produces it.',
           'Trace the economic or competitive consequence the applicant suffers as a direct, foreseeable result of the decision (loss of trade, exclusion from market, devaluation of position).',
           'Argue that this consequence flows "through statutory force" — by virtue of the Act, not merely through ordinary commercial competition.',
           'Resist any argument that standing requires the interest to be one the statute itself names — Argos rejected that constraint.',
           'For ADJR specifically, frame the applicant as a "person aggrieved" by the decision; for general standing, run ACF / Bateman\'s Bay alongside.'
         ],
         issue:'Whether a supermarket operator and an adjacent landowner had standing to challenge an ACT planning approval that authorised a competing supermarket development nearby.',
         conclusion:'Yes — both had standing as "persons aggrieved". The economic detriment from the competing development was a foreseeable, direct consequence of the planning decision, taking effect through statutory force.',
         keywords:['third party','planning','aggrieved','commercial competitor'],
         facts:'Argos and an adjacent landowner challenged the ACT Minister\'s planning approval for a competing supermarket development at Macgregor in the ACT, arguing they were "persons aggrieved" with standing under ADJR.'},
    kr:{ rule:'법령상 결정의 예측 가능한 직접적 결과로 경제적 불이익을 입은 제3자는, ADJR 목적상 "법령의 효력을 통해" 자신의 이해가 영향을 받는 것이며 따라서 "person aggrieved"로서 원고적격을 가질 수 있다. 그 손해가 엄격한 법적 권리일 필요는 없다 — 경쟁 사용을 허가하는 계획 승인으로 인한 상업적 불이익으로 충분하다.',
         principle:'Argos는 ADJR의 "person aggrieved" / Tang 2단계 분석을 상업적 경쟁자에게까지 확장한 판결이다. "법령의 효력을 통한 권리 영향"을 좁게 읽으려는 시도를 거부했고, 핵심 질문은 다투어진 결정이 수권법의 효력으로 신청인에게 실제 경제적 결과를 불러오는가라는 점을 분명히 했다. Argos는 또 Right to Life를 "법령상 맥락"의 렌즈로 읽어 그 법령이 인정하는 이해에만 standing을 한정하려던 시도도 물리쳤다 — 적절한 질문은 결과의 실체이지 법령의 주제적 초점이 아니다. 이 판결은 Bateman\'s Bay(상업적 지위), ACF(기본선)와 함께 standing의 외연을 정의하는 자리에 선다.',
         when:'두 맥락에서 인용한다:\n(1) 상업적 경쟁자가 경쟁사의 영업을 허가하는 계획·면허·규제 승인을 다투려 할 때\n(2) "당신의 이해는 법령이 인정한 것이 아니다"라는 standing 공격을 방어할 때.',
         howApply:[
           '다투어진 결정과 그것을 산출하는 법령상 권한을 식별한다.',
           '신청인이 그 결정의 직접적·예측 가능한 결과로 입는 경제적·경쟁적 결과를 추적한다(영업 손실, 시장 배제, 지위 가치 하락 등).',
           '그 결과가 "법령의 효력을 통해" — 단순한 통상의 상업 경쟁이 아니라 그 법령으로 인해 — 발생함을 주장한다.',
           '"이해가 법령이 명시 인정한 것이어야 한다"는 주장에 저항한다 — Argos가 그 제약을 거부했다.',
           'ADJR 맥락에서는 신청인을 "person aggrieved"로 framing하고, 일반 standing에서는 ACF/Bateman\'s Bay와 나란히 돌린다.'
         ],
         issue:'마트 운영자와 인접 토지 소유자가 ACT의 인근 경쟁 마트 개발 계획 승인을 다툴 standing을 갖는가.',
         conclusion:'그렇다 — 둘 다 "person aggrieved"로서 standing이 있다. 경쟁 개발로 인한 경제적 불이익은 계획 결정의 예측 가능한 직접적 결과이며, 법령의 효력을 통해 발생했다.',
         keywords:['제3자','계획','aggrieved','상업적 경쟁자'],
         facts:'Argos와 인접 토지 소유자가 ACT Macgregor의 경쟁 마트 개발에 대한 ACT 장관의 계획 승인을 다툰 사건. ADJR상 "person aggrieved"로서 standing이 있다고 주장했다.'}},
  m61: {
    id:'m61', name:'Plaintiff M61/2010E v Commonwealth', cite:'[2010] HCA 41; (2010) 243 CLR 319', icon:'⚓', color:'c-ochre',
    topic:'W3', category:'Case',
    en:{ rule:'Where a non-statutory or contracted-out process is integrated into a Commonwealth statutory scheme — and provides a step that the Minister actually relies on in exercising statutory power — that process is reviewable on the same grounds as the statutory exercise itself. Outsourcing the input does not insulate the output. Procedural fairness applies to the integrated step because it bears on a person\'s legal status under the empowering Act.',
         principle:'M61 closed an "outsourcing" loophole that had emerged in offshore processing. The Commonwealth had set up a scheme where private contractors made Refugee Status Assessments and Independent Merits Reviews, formally non-statutory, to feed into the Minister\'s s 46A "lift the bar" discretion. The High Court treated those processes as an integral part of the statutory power exercise — not freestanding advice — and held them reviewable, including for PF. The case also matters as a remedies precedent: declaration was the operative remedy, fixing the legal state of play (Plaintiff M61 is the case that confirms declaration\'s reach in Cth admin law). Together with M68, it forms the spine of the modern "outsourcing does not strip JR" doctrine.',
         when:'Use M61 whenever the respondent argues that an upstream step (assessment, review, recommendation) is non-statutory or outsourced and therefore beyond JR. It is also useful for arguing that PF attaches to advisory processes that bear on legal status.',
         howApply:[
           'Identify the statutory power that ultimately produced the legal effect (e.g. Minister\'s s 46A discretion).',
           'Trace the upstream step (private contractor assessment, advisory body recommendation) that the decision-maker actually relied on.',
           'Argue that the upstream step is integrated into the statutory scheme and bears on the person\'s legal status — making it reviewable.',
           'PF attaches at the integrated step (disclose adverse material, give opportunity to respond), not just at the final Ministerial decision.',
           'Pair with M68 if formal arrangements with foreign States or contractors are in play; with Ainsworth on remedies if certiorari is doubtful and declaration is the better fit.'
         ],
         issue:'Whether non-statutory Refugee Status Assessments and Independent Merits Reviews — conducted by private contractors and used to inform the Minister\'s s 46A discretion — were reviewable, and whether PF applied.',
         conclusion:'Yes — the assessments were an integral step in the exercise of statutory power and were reviewable on common-law grounds, including PF. Declaration was issued.',
         keywords:['offshore processing','outsourcing','private contractor','declaration'],
         facts:'Sri Lankan asylum seekers were detained on Christmas Island. Their refugee status assessments and merits reviews were carried out by private contractors under arrangements that were said to be non-statutory, then used to inform the Minister\'s s 46A "lift the bar" discretion.'},
    kr:{ rule:'비-법정 또는 외주 절차가 영연방 법체계에 편입되어 — 장관이 법령상 권한을 행사할 때 실제로 의존하는 단계를 제공한다면 — 그 절차는 법령상 행위 자체와 같은 사유로 심사 대상이 된다. 입력을 외주화한다고 출력이 차단되지 않는다. 그 편입된 단계는 사람의 법적 지위에 영향을 미치므로 PF가 적용된다.',
         principle:'M61은 역외 처리에서 나타나던 "외주" 우회로를 봉한 판결이다. 영연방은 민간 계약자가 형식상 비-법정인 RSA(Refugee Status Assessment)와 IMR(Independent Merits Review)을 수행해서 장관의 s 46A "bar 풀기" 재량에 투입하는 체계를 짰다. High Court는 그 절차들을 법령상 권한 행사의 일부로 — 독립적인 자문이 아니라 — 다루었고, PF를 포함한 사유로 심사 대상이라고 판시했다. 구제 측면에서도 의미가 크다: 운영적 구제는 declaration이었다(Plaintiff M61은 영연방 행정법에서 declaration의 도달 범위를 확인한 판례). M68과 함께 "외주화로 JR이 차단되지 않는다"는 현대 법리의 척추를 이룬다.',
         when:'피고 측이 "상위 단계(평가·심사·권고)가 비-법정이거나 외주되어 JR 밖"이라고 다툴 때 인용한다. 자문 절차가 법적 지위에 영향을 미치므로 PF가 적용된다고 주장할 때도 유용하다.',
         howApply:[
           '궁극적으로 법적 효과를 산출한 법령상 권한을 식별한다(예: 장관의 s 46A 재량).',
           '결정자가 실제 의존한 상위 단계(민간 계약자 평가, 자문기관 권고)를 추적한다.',
           '그 상위 단계가 법령 체계에 편입돼 있고 사람의 법적 지위에 영향을 미친다고 주장한다 — 그러면 심사 대상이다.',
           'PF는 그 편입된 단계에서도 적용된다(불리한 자료 공개, 답변 기회 부여) — 최종 장관 결정에만 붙는 것이 아니다.',
           '외국 정부·계약자와의 형식적 협정이 있다면 M68과 짝짓고, certiorari가 의문스럽고 declaration이 더 맞다면 Ainsworth와 짝지어 구제를 정한다.'
         ],
         issue:'민간 계약자가 수행한 비-법정 RSA·IMR 절차 — 장관의 s 46A 재량에 투입된 — 가 심사 대상이며, PF가 적용되는가.',
         conclusion:'그렇다 — 그 평가들은 법령상 권한 행사의 편입된 단계이며, PF를 포함한 보통법 사유로 심사 대상이다. Declaration이 발부됐다.',
         keywords:['역외 처리','외주화','사적 계약자','declaration'],
         facts:'크리스마스 섬에 구금된 스리랑카 망명 신청자들의 난민 지위 평가와 실체심사가 형식상 비-법정인 협정 아래 민간 계약자에 의해 수행됐고, 그 결과가 장관의 s 46A "bar 풀기" 재량에 투입된 사건.'}},
  hossain: {
    id:'hossain', name:'Hossain v Minister for Immigration and Border Protection', cite:'[2018] HCA 34; (2018) 264 CLR 123', icon:'✓', color:'c-blue',
    topic:'W4', category:'Case',
    en:{ rule:'Jurisdictional error is analysed in three sequential stages:\n(1) identify the condition the statute attaches to the power;\n(2) ask whether breach of that condition was intended to invalidate (the PBS question — Project Blue Sky);\n(3) if so, ask whether the breach was material — that is, whether there was a realistic possibility that the decision could have been different absent the error.',
         principle:'Hossain locked in the modern three-stage frame and made materiality a default ingredient of jurisdictional error. Before Hossain, breach of a "mandatory" condition was sometimes treated as automatically invalidating; after Hossain, even a real legal error will not produce JE if it could not have changed the outcome (subject to a few "always-JE" exceptions like bias, Kirk-egregious PF, jurisdictional facts, and final-decision unreasonableness).',
         when:'Use Hossain as the spine of any judicial-review answer where a breach of a statutory condition is alleged. It tells you what to do, in what order, before you reach for any sub-ground.',
         howApply:[
           'Stage 1 — pinpoint the condition: quote the empowering provision and isolate each express condition (e.g. "if satisfied that…", time limits) and each implied condition (Coco legality presumption, Kioa PF presumption).',
           'Stage 2 — apply Project Blue Sky: ask what consequence Parliament intended for breach of that particular condition. Look at text, context, purpose, and the scheme of the Act.',
           'Stage 3 — apply materiality (MZAPC / LPDT): infer from the facts whether there was a realistic possibility the outcome could have been different had the error not occurred. The applicant bears the onus, but the bar is low in PF cases (Nathanson).',
           'Flag exceptions: bias (Ebner), Kirk-egregious PF, jurisdictional facts (Enfield), final-decision unreasonableness, and delegated-legislation invalidity bypass the materiality limb.'
         ],
         issue:'Whether errors in the tribunal\'s consideration of public-interest factors in a partner-visa application amounted to jurisdictional error.',
         conclusion:'Errors found, but not material to the outcome → no jurisdictional error. The materiality threshold was held to be ordinarily incorporated into the concept of JE itself.',
         keywords:['three-stage','materiality','JE framework','Project Blue Sky'],
         facts:'A Bangladeshi-born applicant for a partner visa challenged the tribunal\'s decision after it misconstrued the financial-hardship limb and other public-interest criteria. The errors were real, but the High Court held they could not have changed the result.'},
    kr:{ rule:'관할권적 오류는 세 단계로 풀어 본다.\n(1) 법이 권한에 어떤 조건을 붙여 두었는지 짚는다.\n(2) 그 조건을 어기면 결정 자체가 무효가 되도록 의회가 의도했는지(Project Blue Sky의 PBS 질문) 본다.\n(3) 그렇다면 그 위반이 중요한가 — 즉, 오류만 없었다면 결정이 달라졌을 현실적 가능성이 있었는지 따진다.',
         principle:'Hossain은 현대 JE 분석을 이 세 단계로 정리하고, 중요성(materiality)을 JE의 기본 구성요소로 끌어올린 판결이다. 그 전에는 "강행" 조건을 어기면 결정이 자동으로 무효라고 보기도 했지만, 이제는 진짜 법적 오류가 있어도 결과가 바뀔 가능성이 없었으면 JE로 보지 않는다. 다만 편향(Ebner), Kirk 수준의 심각한 PF 위반, 관할권적 사실, 최종 결정의 비합리성처럼 곧바로 JE로 가는 예외 몇 가지는 빠진다.',
         when:'법상 조건의 위반이 쟁점이 되는 모든 사법심사 답안의 뼈대로 쓴다. 어떤 사유로 들어가기 전에, 무엇을 어떤 순서로 봐야 하는지 알려 준다.',
         howApply:[
           '1단계 — 조건 짚기: 수권조항을 그대로 인용한 다음, 명시적 조건("만족하는 경우…", 기간 등)과 묵시적 조건(Coco의 합법성 추정, Kioa의 PF 추정)으로 갈라 적는다.',
           '2단계 — Project Blue Sky로 묻기: 그 특정 조건을 어겼을 때 의회가 어떤 결과를 의도했는가. 조문·맥락·목적·법령 체계를 함께 본다.',
           '3단계 — 중요성 적용(MZAPC / LPDT): 오류가 없었다면 결과가 달라졌을 현실적 가능성이 있었는지 사실에서 추론한다. 입증은 신청인 몫이지만, PF 사안에서는 문턱이 낮다(Nathanson).',
           '예외 점검: 편향(Ebner), Kirk 수준의 심각한 PF, 관할권적 사실(Enfield), 최종 결정의 비합리성, 위임입법 무효 — 이 다섯 가지는 중요성을 묻지 않고 곧장 JE로 간다.'
         ],
         issue:'파트너 비자 사건에서 심판소가 공익 요소를 잘못 다룬 것이 관할권적 오류인가.',
         conclusion:'오류는 있었지만 결과에 영향을 줄 정도는 아니었다 → JE 아님. 이 사건에서 High Court는 중요성 기준이 JE 개념 안에 본래 들어 있다고 정리했다.',
         keywords:['3단계','중요성','JE 분석틀','Project Blue Sky'],
         facts:'방글라데시 출신 파트너 비자 신청인의 사건. 심판소가 재정적 곤란 요건과 공익 기준을 잘못 해석한 것이 다투어졌고, 오류는 인정됐지만 결과를 바꾸지 못했다는 것이 High Court의 판단이었다.'}},
  lpdt: {
    id:'lpdt', name:'LPDT v Minister for Immigration, Citizenship and Multicultural Affairs', cite:'[2024] HCA 12', icon:'⊙', color:'c-ochre',
    topic:'W4', category:'Case',
    en:{ rule:'Materiality is the threshold a procedural or reasoning error must clear before it counts as jurisdictional error. The test: was there a realistic possibility that, absent the error, the decision could have been different? The court reasons inferentially from the record — it must NOT reconstruct the decision-making process by hypothesising what the decision-maker "would have" decided. The Full Court approach of saying "even if (a) had been disregarded, the same conclusion follows" is rejected.',
         principle:'LPDT is the most recent and most direct High Court statement on materiality. It vindicates the inferential approach signalled in WZARH and pushes back against any tendency to defeat materiality by reconstructing the decision-maker\'s reasoning. Together with Hossain (introducing materiality), MZAPC (onus on the applicant, balance of probabilities), and Nathanson (low bar in PF context), it completes the modern materiality framework. Treat LPDT as the operative current statement of the test, especially for PF and reasoning errors.',
         when:'Use LPDT as the controlling authority on materiality whenever the issue is PF or reasoning error and the respondent argues the error did not change the outcome. It is the answer to "but the decision-maker would have reached the same conclusion anyway" arguments.',
         howApply:[
           'State the test clearly: was there a realistic possibility that, absent the error, the decision could have been different?',
           'Reason inferentially from the record — what evidence was missed, what submissions were not made, what considerations were short-circuited?',
           'Refuse the invitation to reconstruct — do not ask "what would the decision-maker have decided?" Ask only whether a different decision was realistically possible.',
           'In PF cases, remember the bar is low (Nathanson) — courts are readily inclined to infer that further submissions could have made a difference.',
           'Onus stays on the applicant (MZAPC), but the inferential reasoning helps discharge it.'
         ],
         issue:'Whether procedural fairness and reasoning errors in a s 501 visa cancellation by the Tribunal were material to the decision.',
         conclusion:'Yes — the errors were material. The Full Court\'s reconstruction-style approach (asking what the decision-maker would have decided absent the error) was rejected. JE was made out.',
         keywords:['realistic possibility','no reconstruction','LPDT','materiality'],
         facts:'A New Zealand-born plaintiff had his visa cancelled under s 501 of the Migration Act. The Tribunal\'s decision was challenged on procedural fairness and reasoning errors, with the Minister arguing the errors made no difference to the outcome.'},
    kr:{ rule:'Materiality(중요성)는 절차적·추론 오류가 관할권적 오류로 인정되기 위해 넘어야 하는 문턱이다. 기준은 — 오류가 없었다면 결정이 달라졌을 현실적 가능성이 있었는가. 법원은 기록에서 추론으로 판단해야 하며, 결정자가 "어떻게 결정했을 것인가"를 가정해서 의사결정을 재구성해서는 안 된다. "(a)를 무시했더라도 같은 결론에 이르렀을 것"이라는 Full Court식 접근은 거부된다.',
         principle:'LPDT는 materiality에 대한 가장 최근의, 가장 직접적인 High Court 진술이다. WZARH가 시사한 추론적 접근을 확인했고, 결정자의 추론을 재구성해서 materiality를 무력화하려는 어떤 시도도 막아 세웠다. Hossain(materiality 도입), MZAPC(원고에게 개연성 우월의 입증책임), Nathanson(PF 맥락에서 낮은 문턱)과 함께 현대 materiality framework를 완성한다. 특히 PF·추론 오류 사안에서는 LPDT를 현행 기준의 운영적 진술로 다룬다.',
         when:'쟁점이 PF나 추론 오류이고, 피고가 "오류가 결과를 바꾸지 않았다"고 다툴 때 가장 먼저 인용한다. "결정자는 어쨌든 같은 결론에 이르렀을 것"이라는 주장에 대한 정답이다.',
         howApply:[
           '기준을 명확히 진술한다 — 오류가 없었다면 결정이 달라졌을 현실적 가능성이 있었는가.',
           '기록에서 추론으로 판단한다 — 어떤 증거가 누락됐는가, 어떤 의견이 제출되지 못했는가, 어떤 고려가 끊겼는가.',
           '재구성의 유혹을 거부한다 — "결정자가 어떻게 결정했을 것인가"를 묻지 않는다. 다른 결정이 현실적으로 가능했는지만 묻는다.',
           'PF 사안에서는 문턱이 낮다는 점을 기억한다(Nathanson) — 법원은 추가 의견이 영향을 줄 수 있었음을 쉽게 추론하는 경향이 있다.',
           '입증책임은 원고에게 있지만(MZAPC), 추론적 추리가 그 책임을 덜어 준다.'
         ],
         issue:'Tribunal의 s 501 비자 취소에서 절차적 공정·추론 오류가 결정에 중요한가.',
         conclusion:'그렇다 — 오류는 중요했다. 결정자가 오류 없이도 어떤 결정을 했을지를 가정하는 Full Court식 재구성 접근은 거부됐다. JE 인정.',
         keywords:['현실적 가능성','재구성 금지','LPDT','materiality'],
         facts:'뉴질랜드 출신 원고가 Migration Act s 501에 따라 비자가 취소된 사건. Tribunal 결정이 PF·추론 오류를 이유로 다투어졌고, 장관 측은 그 오류가 결과를 바꾸지 않았다고 다퉜다.'}},
  mzapc: {
    id:'mzapc', name:'MZAPC v Minister for Immigration, Citizenship, Migrant Services and Multicultural Affairs', cite:'[2021] HCA 17; (2021) 273 CLR 506', icon:'⚖', color:'c-coral',
    topic:'W4', category:'Case',
    en:{ rule:'On materiality, the applicant bears the formal onus on the balance of probabilities — the applicant must show that, but for the error, there was a realistic possibility of a different outcome. Some categories of error remain "always-JE" and bypass the materiality limb entirely: bias (Ebner), final-decision unreasonableness, jurisdictional facts, Kirk-egregious PF, and delegated-legislation invalidity.',
         principle:'MZAPC fixed two things in the materiality framework. First, the formal allocation of onus: the applicant must positively establish the realistic possibility of a different outcome, not merely raise it. Second, it preserved the always-JE list — categories where the very nature of the breach makes the materiality inquiry inappropriate. The case sat in tension with WZARH on how easily the realistic possibility can be inferred; LPDT (2024) later resolved that tension in favour of the inferential approach. Read MZAPC for onus, LPDT for the operative test.',
         when:'Cite MZAPC when the question is who bears the burden on materiality, or when the case is in an "always-JE" category and you need to explain why materiality is bypassed.',
         howApply:[
           'Identify whether the breach is in an "always-JE" category (bias, final-decision unreasonableness, jurisdictional fact, Kirk-egregious PF, delegated-legislation invalidity). If so, materiality is bypassed.',
           'If not, allocate the onus: the applicant must establish materiality on the balance of probabilities.',
           'Use LPDT for the substantive test (realistic possibility, inferential reasoning, no reconstruction) — MZAPC for the formal onus point.',
           'In PF cases, remember the bar is low (Nathanson) — the onus is more easily discharged because of how readily the inference is drawn.'
         ],
         issue:'Whether the Tribunal\'s failure to disclose to the applicant an adverse referral from the Magistrates Court was a material error such that JE was made out.',
         conclusion:'Not material on the facts — the applicant did not discharge the onus of showing a realistic possibility that disclosure would have produced a different outcome. The majority confirmed the formal onus rests on the applicant.',
         keywords:['onus','materiality','formal burden','always-JE'],
         facts:'A migration tribunal failed to put to the applicant an adverse referral from a Magistrates Court before relying on it. Whether the failure was material to the visa decision — and who bore the onus of proving so — was contested.'},
    kr:{ rule:'Materiality에 대해서는, 원고가 개연성의 우월(balance of probabilities)로 형식적 입증책임을 진다 — 오류가 없었다면 결과가 달라졌을 현실적 가능성이 있었음을 적극적으로 입증해야 한다. 다만 일부 오류 범주는 여전히 "always-JE"로 materiality 단계를 거치지 않는다: 편향(Ebner), 최종 결정의 비합리성, 관할권적 사실, Kirk 수준의 중대한 PF, 위임입법의 무효.',
         principle:'MZAPC는 materiality framework에서 두 가지를 고정했다. 첫째, 입증책임의 형식적 배분 — 원고가 단순히 가능성을 제기하는 것이 아니라 다른 결과의 현실적 가능성을 적극 입증해야 한다. 둘째, "always-JE" 목록의 보존 — 위반의 성격 자체가 materiality 분석을 부적절하게 만드는 범주들. 이 판결은 WZARH와 "현실적 가능성을 얼마나 쉽게 추론할 수 있는가"를 두고 긴장 관계에 있었는데, LPDT(2024)가 그 긴장을 추론적 접근 쪽으로 해소했다. 입증책임은 MZAPC, 운영적 기준은 LPDT로 읽는다.',
         when:'쟁점이 materiality의 입증책임이 누구에게 있는가일 때, 또는 사건이 "always-JE" 범주여서 materiality가 우회되는 이유를 설명할 때 인용한다.',
         howApply:[
           '위반이 "always-JE" 범주에 속하는지 확인한다(편향, 최종 결정 비합리성, 관할권적 사실, Kirk 수준의 중대 PF, 위임입법 무효). 속한다면 materiality는 우회된다.',
           '그렇지 않다면 입증책임을 배분한다 — 원고가 개연성의 우월로 materiality를 입증해야 한다.',
           '실체적 기준(현실적 가능성, 추론적 추리, 재구성 금지)에는 LPDT를, 형식적 입증책임 포인트에는 MZAPC를 인용한다.',
           'PF 사안에서는 문턱이 낮다는 점을 기억한다(Nathanson) — 추론이 쉽게 그어지기 때문에 입증책임도 쉽게 충족된다.'
         ],
         issue:'Tribunal이 Magistrates Court의 불리한 의뢰를 신청인에게 공개하지 않은 채 의존한 오류가 JE를 성립시킬 만큼 중요한가.',
         conclusion:'사실관계에서 중요하지 않음 — 원고가 공개됐더라면 결과가 달라졌을 현실적 가능성을 입증할 책임을 다하지 못했다. 다수의견은 형식적 입증책임이 원고에게 있음을 확인했다.',
         keywords:['입증책임','중요성','형식적 부담','always-JE'],
         facts:'이민 tribunal이 Magistrates Court의 불리한 의뢰를 신청인에게 제시하지 않은 채 의존한 사건. 그 누락이 비자 결정에 중요했는지, 그리고 누가 입증책임을 지는지가 다투어졌다.'}},
  wzarh: {
    id:'wzarh', name:'Minister for Immigration and Border Protection v WZARH', cite:'[2015] HCA 40; (2015) 256 CLR 326', icon:'✉', color:'c-coral',
    topic:'W5', category:'Case',
    en:{ rule:'In a procedural-fairness context, the inference that further submissions or evidence could have been made — and could realistically have changed the outcome — is readily drawn from the record. The materiality threshold for PF breaches is therefore low. The inferential approach signalled here was vindicated by LPDT (2024).',
         principle:'WZARH is the High Court\'s clearest pre-LPDT statement that PF materiality is established by inference from what could have been said, not by reconstructing what would have been decided. Read with Nathanson (low PF bar) and LPDT (no reconstruction).',
         when:'Use WZARH alongside Nathanson and LPDT to defeat "the decision would have been the same anyway" objections in PF cases.',
         howApply:[
           'Establish the PF breach (Kioa default + Saeed clear-words analysis).',
           'Argue materiality inferentially — what submissions or evidence could the applicant have put if PF had been observed?',
           'Resist reconstruction of the decision-maker\'s reasoning (LPDT) — only ask whether a different outcome was realistically possible.'
         ],
         issue:'Whether the change of reviewer mid-process in an Independent Merits Review, without notice to the applicant, breached PF and was material.',
         conclusion:'Yes — PF breached; materiality established because further submissions tailored to the new reviewer could readily be inferred to have made a difference.',
         keywords:['PF materiality','readily inferred','reviewer change','inferential'],
         facts:'In an IMR for a refugee status assessment, the reviewer was changed mid-process without notice to the applicant. The new reviewer reached an adverse conclusion; the applicant had no chance to tailor submissions to the new reviewer.'},
    kr:{ rule:'PF 맥락에서, 추가 의견이나 증거가 제출됐을 수 있고 그것이 결과를 현실적으로 바꿀 수 있었다는 추론은 기록에서 손쉽게 그어진다. 따라서 PF 위반의 materiality 문턱이 낮다. 여기서 시사된 추론적 접근은 LPDT(2024)로 확인됐다.',
         principle:'WZARH는 PF materiality가 "무엇을 결정했을까"의 재구성이 아니라 "무엇을 말할 수 있었을까"의 추론으로 입증된다는, LPDT 이전 High Court의 가장 또렷한 진술이다. Nathanson(낮은 PF 문턱), LPDT(재구성 금지)와 함께 읽는다.',
         when:'PF 사안에서 "결정은 어쨌든 같았을 것"이라는 항변을 깨기 위해 Nathanson, LPDT와 함께 인용한다.',
         howApply:[
           'PF 위반을 입증한다(Kioa 기본 + Saeed 명시 문언 분석).',
           'Materiality를 추론적으로 주장한다 — PF가 지켜졌더라면 신청인이 어떤 의견·증거를 낼 수 있었는가.',
           '결정자 추론의 재구성에 저항한다(LPDT) — 다른 결과가 현실적으로 가능했는지만 묻는다.'
         ],
         issue:'IMR 절차 도중 심사관이 신청인에게 고지 없이 교체된 것이 PF 위반이며 중요한가.',
         conclusion:'그렇다 — PF 위반. 새 심사관에 맞춘 의견 제출이 결과를 바꿀 수 있었음이 손쉽게 추론되어 materiality 인정.',
         keywords:['PF materiality','쉬운 추론','심사관 교체','추론적'],
         facts:'난민 지위 평가의 IMR에서 심사관이 신청인 고지 없이 절차 도중 교체됐다. 새 심사관이 불리한 결론에 이르렀고, 신청인은 새 심사관에 맞춰 의견을 조정할 기회가 없었다.'}},
  annetts: {
    id:'annetts', name:'Annetts v McCann', cite:'[1990] HCA 57; (1990) 170 CLR 596', icon:'☼', color:'c-coral',
    topic:'W5', category:'Case',
    en:{ rule:'The PF default presumption applies to any decision affecting an identifiable person\'s rights, interests or legitimate expectations — including coronial inquiries into a death where the family\'s reputational interests are engaged. PF can only be excluded by clear statutory words; the coronial Act\'s silence did not amount to exclusion.',
         principle:'Annetts is an early consolidation of the Kioa default. It also confirms that PF\'s reach extends beyond the obvious "decision-affecting-rights" cases into investigative and inquiry contexts where reputational or family interests are at stake.',
         when:'Cite Annetts to anchor PF\'s default reach into investigative or inquiry contexts (coronial, disciplinary, ombuds-style), or as a companion citation to Kioa for the default presumption.',
         howApply:[
           'Identify the affected person and the interest engaged (rights, interests, reputation).',
           'Apply the Kioa/Annetts default — PF presumed to apply.',
           'Look for clear statutory words excluding PF (Saeed); silence is not enough.'
         ],
         issue:'Whether the parents of a 16-year-old whose death was being investigated by a coroner had a right to be heard in the coronial inquiry.',
         conclusion:'Yes — PF default applied; the coronial Act did not, in clear and unambiguous words, exclude the parents\' right to be heard.',
         keywords:['PF default','coronial','clear words','reputational interest'],
         facts:'A 16-year-old died in a remote area. The coroner conducted an inquiry; the parents sought to be heard. The coronial Act did not expressly grant or deny them a hearing.'},
    kr:{ rule:'PF 기본 추정은 식별 가능한 개인의 권리·이익·정당한 기대에 영향을 주는 모든 결정에 적용된다 — 가족의 평판 이익이 걸린 사망 검시도 포함된다. PF는 분명한 법령 문언으로만 배제될 수 있고, 검시법의 침묵은 배제가 아니다.',
         principle:'Annetts는 Kioa 기본 추정을 일찍이 굳힌 판결이다. PF의 도달이 명백한 "권리에 영향" 사안을 넘어 평판이나 가족 이익이 걸린 조사·심리 맥락까지 미친다는 점도 확인한다.',
         when:'PF의 기본 도달이 조사·심리 맥락(검시, 징계, 옴부즈만형)에 미침을 정초할 때, 또는 Kioa 기본 추정의 동반 인용으로 사용한다.',
         howApply:[
           '영향을 받는 사람과 걸린 이익(권리, 이익, 평판)을 식별한다.',
           'Kioa/Annetts 기본을 적용한다 — PF가 적용되는 것으로 추정.',
           'PF를 배제하는 분명한 법령 문언을 찾는다(Saeed). 침묵으로는 부족하다.'
         ],
         issue:'검시관이 사망을 조사 중인 16세 청소년의 부모에게 검시에서 청문권이 있는가.',
         conclusion:'그렇다 — PF 기본이 적용. 검시법은 부모의 청문권을 분명하고 모호하지 않은 문언으로 배제하지 않았다.',
         keywords:['PF 기본값','검시','분명한 문언','평판 이익'],
         facts:'16세 청소년이 외딴 지역에서 사망했다. 검시관이 조사를 진행했고 부모가 청문권을 청했다. 검시법은 부모의 청문권을 명시적으로 부여하지도 부정하지도 않았다.'}},
  lam: {
    id:'lam', name:'Re Minister for Immigration and Multicultural and Indigenous Affairs; Ex parte Lam', cite:'[2003] HCA 6; (2003) 214 CLR 1', icon:'◎', color:'c-violet',
    topic:'W5', category:'Case',
    en:{ rule:'The touchstone of procedural fairness is "practical injustice" — whether the applicant was, in fact, denied a fair opportunity in a way that mattered to the decision. The "legitimate expectation" doctrine is not the gateway; it has been displaced. The question is what fair procedure required in the circumstances and whether there was a real denial of fair opportunity.',
         principle:'Lam (Gleeson CJ) modernised PF analysis by reframing it around practical injustice rather than legitimate expectation. Quin had already trimmed the doctrine; Lam effectively closed it as the analytic axis. Practical-injustice framing now governs PF analysis.',
         when:'Use Lam whenever counsel is reaching for "legitimate expectation" framing — Lam directs the analysis to practical injustice instead. Also useful when defending a PF claim where the applicant suffered no real prejudice.',
         howApply:[
           'Frame PF analysis around practical injustice — was there a real denial of a fair opportunity?',
           'Avoid legitimate-expectation framing; if counsel uses it, redirect to practical-injustice analysis.',
           'On the facts, ask whether the impugned procedural feature in fact mattered to the applicant\'s ability to put their case.'
         ],
         issue:'Whether the Minister\'s failure to interview the carer of the applicant\'s children — despite an earlier departmental indication that an interview would occur — breached PF in the s 501 cancellation.',
         conclusion:'No practical injustice — the applicant\'s case was put fully and the missed interview was not shown to have made a real difference. PF not breached.',
         keywords:['practical injustice','legitimate expectation','Gleeson CJ','PF axis'],
         facts:'A Vietnamese-born applicant\'s visa was cancelled under s 501. The Department had earlier indicated it would interview his children\'s carer to test the impact of cancellation; that interview did not occur. The applicant argued PF was breached.'},
    kr:{ rule:'절차적 공정의 핵심 기준은 "실질적 부정의(practical injustice)"이다 — 신청인이 실제로 결정에 의미 있는 방식으로 공정한 기회를 박탈당했는지. "정당한 기대" 법리는 더 이상 관문이 아니다 — 옮겨졌다. 질문은 그 상황에서 공정한 절차가 무엇을 요구했고, 공정한 기회의 실질적 박탈이 있었는지이다.',
         principle:'Lam(Gleeson CJ)은 PF 분석을 정당한 기대에서 실질적 부정의로 재정렬해 현대화한 판결이다. Quin이 이미 그 법리를 좁혔다면, Lam은 분석의 축으로서 그것을 사실상 닫았다. 이제 실질적 부정의 framing이 PF 분석을 지배한다.',
         when:'변호인이 "정당한 기대" framing을 꺼내려 할 때 인용한다 — Lam이 분석을 실질적 부정의 쪽으로 돌린다. 신청인이 실제로 불이익을 입지 않은 PF 주장을 방어할 때도 유용.',
         howApply:[
           'PF 분석을 실질적 부정의를 중심으로 짠다 — 공정한 기회의 실질적 박탈이 있었는가.',
           '정당한 기대 framing을 피한다. 상대가 꺼내면 실질적 부정의 분석으로 돌린다.',
           '사실관계에서, 다투어진 절차적 특징이 실제로 신청인이 자기 입장을 밝힐 능력에 의미 있게 영향을 주었는지 묻는다.'
         ],
         issue:'장관이 신청인 자녀의 양육자를 — 부처가 사전에 면담을 시사했음에도 — 면담하지 않은 것이 s 501 취소에서 PF 위반인가.',
         conclusion:'실질적 부정의 없음 — 신청인의 입장이 충분히 제출됐고, 누락된 면담이 실질적 차이를 만들었음이 입증되지 않았다. PF 위반 아님.',
         keywords:['실질적 부정의','정당한 기대','Gleeson CJ','PF 축'],
         facts:'베트남 출신 신청인의 비자가 s 501에 따라 취소됐다. 부처가 사전에 자녀 양육자 면담을 통해 취소 영향을 검토하겠다고 시사했지만 그 면담은 이뤄지지 않았다. 신청인이 PF 위반을 주장한 사건.'}},
  li: {
    id:'li', name:'Minister for Immigration and Citizenship v Li', cite:'[2013] HCA 18; (2013) 249 CLR 332', icon:'☼', color:'c-ochre',
    topic:'W8', category:'Case',
    en:{ rule:'A discretionary decision is legally unreasonable when it lacks an "evident and intelligible justification" — when the result is disproportionate to the statutory purpose, or the path of reasoning is so opaque that no reasonable decision-maker on the same statute could have arrived there. The test is broader than Wednesbury\'s "so unreasonable that no reasonable person could" formulation.',
         principle:'Li reformulated unreasonableness for the modern era. Courts no longer need to find an "extreme" decision in the Wednesbury sense; an absence of evident, intelligible justification — the kind of justification a reasonable decision-maker would supply — is enough. This made unreasonableness a workable, mainstream sub-ground rather than a doctrinal last resort. Stretton (FCAFC) and DUA16 (HCA, on procedural unreasonableness) build on this footing.',
         when:'Reach for Li whenever a discretion has been exercised in a way that looks disproportionate, unexplained, or arbitrary on the face of the record. It is the standard ground when the applicant cannot point to a missed consideration or a PF breach but the result still feels indefensible.',
         howApply:[
           'Identify the discretionary power and the statutory purpose against which the result must be measured (read the empowering provision, not just the impugned decision).',
           'Look for an evident and intelligible justification in the reasons. Is there a coherent chain from the facts found, through the statutory criteria, to the result?',
           'Ask whether the decision falls within the range of outcomes a reasonable decision-maker on this statute could reach. Disproportion to purpose, gross weighting errors, or opaque reasoning all count.',
           'If no justification is evident, articulate the gap precisely — and remember that materiality (Hossain stage 3) still applies.'
         ],
         issue:'Whether the migration tribunal\'s refusal to adjourn pending a skills-assessment review was legally unreasonable.',
         conclusion:'Yes — the refusal was disproportionate and unsupported by any evident, intelligible justification, and therefore legally unreasonable.',
         keywords:['legal unreasonableness','Li framework','adjournment','evident and intelligible justification'],
         facts:'A migration tribunal refused to adjourn a hearing despite knowing that a skills-assessment review — the very thing that could change the outcome — was already underway. The refusal had no apparent reason on the face of the record.'},
    kr:{ rule:'재량 결정은 "명확하고 이해 가능한 정당화(evident and intelligible justification)"를 결여할 때 법적으로 비합리적이야. 결과가 법령의 목적에 비추어 비례성을 잃었거나, 추론 과정이 너무 불투명해서 같은 법령을 적용하는 합리적 결정자라면 도달할 수 없는 결론이라면 이 기준에 걸립니다. Wednesbury의 "합리적 사람이라면 결코 도달할 수 없을 정도" 기준보다 넓다.',
         principle:'Li는 비합리성 사유를 현대적으로 다시 짠 판결이다. 더 이상 Wednesbury 식의 "극단적" 결정을 입증할 필요가 없고, 합리적 결정자라면 제시했을 정당화가 보이지 않는다는 사실만으로도 충분한다. 그 결과 비합리성은 마지막 카드가 아니라 일반적으로 쓰는 사유가 됐다. Stretton(FCAFC), DUA16(HCA의 절차적 비합리성)은 이 토대를 확장한 후속 판결이다.',
         when:'재량 행사가 표면상 비례성을 잃었거나, 설명이 빈약하거나, 자의적으로 보이는 경우라면 Li가 출발점이다. 누락된 고려사항이나 PF 위반을 짚어 낼 수 없는데도 결과가 변호하기 어려울 때 가장 자연스럽게 쓰는 사유이다.',
         howApply:[
           '문제된 재량 권한을 특정하고, 결과를 비교할 잣대가 되는 법령상 목적을 확인해(문제된 결정만 보지 말고 수권조항을 함께 읽는다).',
           '판단 이유에서 evident and intelligible justification을 찾습니다. 사실인정 → 법령상 기준 → 결과로 이어지는 일관된 흐름이 보이는지.',
           '같은 법령을 적용하는 합리적 결정자가 도달할 수 있는 결과의 범위 안에 들어가는지 묻는다. 목적에 대한 비례성 상실, 가중치 부여의 큰 오류, 불투명한 추론이 모두 해당돼.',
           '정당화가 보이지 않는다면 그 공백을 구체적으로 짚어내고, materiality(Hossain 3단계)는 여전히 적용된다는 점을 잊지 마.'
         ],
         issue:'기능 평가 검토가 진행 중인 상황에서 이민 tribunal이 연기를 거부한 것이 법적으로 비합리적인가.',
         conclusion:'그렇다 — 비례성을 잃었고 기록상 정당화가 드러나지 않으므로 법적으로 비합리적이야.',
         keywords:['법적 비합리성','Li 분석틀','연기','명확하고 이해 가능한 정당화'],
         facts:'결과를 바꿀 수 있는 기능 평가 검토가 진행 중인데도 이민 tribunal이 심리 연기를 거부한 사건. 기록상 거부의 이유가 드러나지 않았다.'}},
  ebner: {
    id:'ebner', name:'Ebner v Official Trustee in Bankruptcy', cite:'[2000] HCA 63; (2000) 205 CLR 337', icon:'◉', color:'c-blue',
    topic:'W6', category:'Case',
    en:{ rule:'Apprehended bias is established when a fair-minded lay observer, properly informed of the circumstances, might reasonably apprehend that the decision-maker might not bring an impartial mind to the decision. The party alleging bias must articulate the test in two steps:\n(i) identify the matter said to give rise to the apprehension, and\n(ii) explain the logical connection between that matter and the feared deviation from impartiality.',
         principle:'Ebner gave Australian law the dominant double-step articulation for apprehended bias and clarified that the standard is the fair-minded informed observer, not the parties\' actual feelings. By requiring an explicit logical connection, the court raised the bar against bare-suspicion claims and made apprehended-bias analysis disciplined and structured. Bias is one of the "always-JE" categories — once established it does not require materiality (it goes straight to JE).',
         when:'Use Ebner whenever the integrity of the decision-maker is in issue: financial interest, prior involvement in the case or subject-matter, family or social ties, public statements suggesting prejudgment. It is also the lens through which Webb (criminal jurors), Jia (ministerial decision-makers), Isbester (advisers in the room), CNY17 (security-cleared officers), and Hot Holdings (commercial relationships) are read.',
         howApply:[
           'Identify the impugned circumstance specifically — what exactly is the decision-maker said to be tied to (a shareholding, a prior client, a public statement, a family connection)?',
           'State the fair-minded informed observer test verbatim, and ask whether such an observer, knowing the circumstance and the surrounding institutional context, might reasonably apprehend prejudgment.',
           'Articulate the logical connection: explain in one or two sentences why the circumstance could plausibly cause the decision-maker not to bring an impartial mind to bear. A bare assertion is not enough.',
           'Remember that bias is an always-JE category — no materiality limb. Once established, JE follows directly, and the remedy will usually be certiorari plus rehearing before a different decision-maker.'
         ],
         issue:'Whether a trial judge\'s shareholding in a bank that was a party to the proceedings required the judge to disqualify themselves for apprehended bias.',
         conclusion:'No — the connection between the shareholding and the matter to be decided was too remote to ground a reasonable apprehension of partiality.',
         keywords:['apprehended bias','double-might','two-step','fair-minded observer'],
         facts:'A trial judge sitting on commercial proceedings held shares in a bank that was a party. The applicants moved for the judge\'s disqualification on grounds of apprehended bias.'},
    kr:{ rule:'추정 편향은, 사정을 제대로 안 공정한 마음의 일반 관찰자가 결정자가 공정한 마음으로 사건을 다루지 않을 수 있다고 합리적으로 의심할 만한 경우에 인정돼. 주장하는 측은 두 단계로 명확히 짜야 하는데,\n(i) 그런 의심을 불러일으킨다는 사정 자체를 구체적으로 짚어 내고,\n(ii) 그 사정과 두려워하는 편향 사이의 논리적 연결을 풀어 보여야 한다.',
         principle:'Ebner는 호주 법에서 추정 편향 분석의 표준 2단계 틀을 자리잡게 한 판결이다. 기준은 당사자의 실제 감정이 아니라 "공정한 마음의, 사정을 잘 아는 관찰자"이고, 명시적인 논리적 연결을 요구함으로써 단순한 의혹 제기를 걸러냅니다. 편향은 "always-JE" 범주 중 하나이기 때문에 인정만 되면 materiality 단계를 거치지 않고 바로 JE로 이어진다.',
         when:'결정자 자신의 적격성이 문제될 때 — 재정적 이해관계, 사건이나 분야에 대한 이전 관여, 가족·사회적 관계, 사전 판단을 시사하는 공개 발언 등 — Ebner를 꺼내 봐. Webb(형사 배심), Jia(장관 결정자), Isbester(자문관 동석), CNY17(보안 인가 공무원), Hot Holdings(상업적 관계)도 모두 같은 렌즈로 읽힌다.',
         howApply:[
           '문제된 사정을 구체적으로 특정해 — 결정자가 정확히 무엇과(주식 보유인지, 이전 의뢰인 관계인지, 공개 발언인지, 가족 관계인지) 묶여 있는가.',
           '공정한 마음의 사정에 밝은 관찰자 기준을 그대로 진술하고, 그 관찰자가 상황과 제도적 맥락을 함께 알았을 때 사전 판단을 합리적으로 의심할 만한지 묻는다.',
           '논리적 연결을 한두 문장으로 풀어 줘 — 그 사정이 어떻게 결정자의 공정성을 흔들 수 있는지를. 단순한 단언은 부족해.',
           '편향은 always-JE 범주이므로 materiality는 묻지 않는다. 인정되면 JE로 직행하며, 구제는 보통 certiorari + 다른 결정자에 의한 재심리야.'
         ],
         issue:'소송 당사자인 은행의 주식을 보유한 재판관이 추정 편향을 이유로 회피해야 하는가.',
         conclusion:'아니오 — 주식 보유와 다투어진 쟁점 사이의 연관이 너무 멀어 합리적 의심의 근거가 되지 않다.',
         keywords:['추정 편향','이중 might','2단계','공정한 관찰자'],
         facts:'상사 사건을 맡은 재판관이 당사자인 은행의 주식을 보유한 사실이 드러났고, 신청인들이 추정 편향을 이유로 회피를 신청한 사건.'}},
  peko: {
    id:'peko', name:'Minister for Aboriginal Affairs v Peko-Wallsend Ltd', cite:'[1986] HCA 40; (1986) 162 CLR 24', icon:'☰', color:'c-forest',
    topic:'W7', category:'Case',
    en:{ rule:'A failure to take into account a mandatory relevant consideration is a reviewable error. Mason J\'s framework:\n(i) what is "mandatory" is determined by statutory construction (express words or necessary implication from subject-matter, scope and purpose);\n(ii) the court does not reweigh — it only asks whether the consideration was actually taken into account;\n(iii) weight is for the decision-maker, save for irrational weighting that crosses into unreasonableness.',
         principle:'Peko-Wallsend established the dominant Australian framework for the relevant-considerations sub-ground and built in two important guard-rails: the court does not substitute its own assessment of weight for the decision-maker\'s, and it polices only mandatory considerations identified by the statute (not every consideration counsel argues was important). Tickner extended the framework, and M1/2021 reaffirmed that the consideration must actually be considered, not merely listed in the reasons.',
         when:'Use Peko-Wallsend whenever the applicant says "the decision-maker did not take X into account, and they were required to". It is a structural sub-ground, not an unreasonableness argument — keep them separate.',
         howApply:[
           'Identify the candidate consideration with precision (a specific submission, a specific fact, a specific factor).',
           'Locate the legal source that makes it mandatory: an express statutory requirement, or a necessary implication from the subject-matter, scope and purpose of the empowering Act.',
           'Ask whether the decision-maker actually engaged with the consideration — listing in reasons is not the same as taking into account; ignoring late but plainly relevant material is the classic Peko fact pattern.',
           'Do not argue weight — that is not the court\'s role. If the real complaint is bad weighting, redirect to Li unreasonableness instead.',
           'If the breach is made out, apply Hossain stage 3 (materiality) — would consideration of the missed factor have created a realistic possibility of a different outcome?'
         ],
         issue:'Whether the Minister was bound to consider further submissions made by the mining company after the report and before the decision on an Aboriginal land claim covering a uranium deposit.',
         conclusion:'Yes — failing to consider the company\'s late but plainly relevant submissions was a reviewable error of the relevant-considerations kind.',
         keywords:['relevant considerations','5 principles','Mason J','mandatory consideration'],
         facts:'Minister Holding decided an Aboriginal land claim over a uranium deposit without considering submissions Peko-Wallsend had made after the official recommendation. The submissions went to facts plainly within the statutory criteria.'},
    kr:{ rule:'법령이 반드시 고려하라고 정한 사항(mandatory relevant consideration)을 누락한 결정은 심사 대상이야. Mason J의 분석틀은 이렇다.\n(i) "강행"인지는 법령 해석으로 정해지고(명시 문언이거나, 수권법의 주제·범위·목적에서 필연적으로 도출되거나),\n(ii) 법원은 가중치를 다시 매기지 않고 그 사항이 실제로 고려되었는지만 본다,\n(iii) 가중치 자체는 결정자의 몫이고, 다만 그 가중치가 비합리성으로 넘어가는 수준이라면 별도로 다툴 수 있다.',
         principle:'Peko-Wallsend는 관련 고려사항 사유의 호주 표준 framework를 세웠고, 두 가지 안전장치를 함께 깔았다. 법원은 결정자의 가중치를 대체하지 않으며, 법령이 강행으로 지정한 사항만 단속한다는 점이야. Tickner는 이 framework를 확장했고, M1/2021은 이유서에 적어 두는 것과 실제로 고려하는 것은 다르다는 점을 다시 확인했다.',
         when:'신청인이 "결정자가 X를 고려해야 했는데 하지 않았다"라고 주장할 때 꺼내는 사유다. 비합리성 주장과는 결이 다르니 분리해서 써.',
         howApply:[
           '문제된 고려사항을 구체적으로 짚어 내(특정 의견서·특정 사실·특정 요소).',
           '그것을 강행으로 만드는 법적 근거를 찾아 — 명시적 법령 요건이거나, 수권법의 주제·범위·목적에서 필연적으로 도출되는 묵시적 요건이거나.',
           '결정자가 실제로 그 사항과 마주했는지 묻는다 — 이유서에 단순히 나열하는 것과 실제로 고려하는 것은 다르다. 뒤늦지만 명백히 관련된 자료를 무시한 것이 Peko 패턴의 전형이다.',
           '가중치 자체를 다투지 마 — 법원의 영역이 아니다. 진짜 불만이 가중치라면 Li 비합리성으로 돌리는 편이 맞다.',
           '위반이 성립하면 Hossain 3단계(materiality)를 적용해, 누락된 사항을 고려했더라면 결과가 달라졌을 현실적 가능성이 있었는지 묻는다.'
         ],
         issue:'우라늄 광상에 걸친 원주민 토지 청구 사건에서, 공식 권고 이후 광업사가 제출한 추가 의견서를 장관이 결정 전에 고려해야 했는가.',
         conclusion:'그렇다 — 뒤늦었지만 명백히 관련된 의견서를 고려하지 않은 것은 관련 고려사항 누락의 심사 가능한 오류야.',
         keywords:['관련 고려사항','5원칙','Mason J','강행 고려사항'],
         facts:'Holding 장관이 우라늄 광상에 걸친 원주민 토지 청구를 결정할 때, 권고 이후 광업사 Peko-Wallsend가 제출한 추가 의견서를 검토하지 않은 사건. 의견서 내용은 법령상 기준에 명백히 들어맞는 사실관계였다.'}},
  schlieske: {
    id:'schlieske', name:'Schlieske v Minister for Immigration and Ethnic Affairs', cite:'(1988) 84 ALR 719; (1988) 26 FCR 540', icon:'◐', color:'c-coral',
    topic:'W7', category:'Case',
    en:{ rule:'A statutory power exercised for an unauthorised purpose is invalid, even if the impugned action falls within the literal scope of the empowering provision. Where the dominant or operative purpose is one the Act does not authorise — for example, using a deportation power to effect a disguised extradition — the exercise is improper-purpose JE.',
         principle:'Schlieske is the leading Australian authority on improper-purpose JE. The court looks to the dominant operative purpose behind the exercise; if that purpose is unauthorised, the action is invalid even if it could nominally have been taken for a proper purpose.',
         when:'Use Schlieske when the impugned exercise looks dressed-up — formally within power, but actually pursuing some other end the empowering Act does not authorise.',
         howApply:[
           'Identify the empowering provision and the purposes it authorises.',
           'Identify the dominant operative purpose of the impugned exercise on the facts (intent, surrounding arrangements, who benefits).',
           'If the dominant purpose is unauthorised, the exercise is improper-purpose JE — invalidity follows.'
         ],
         issue:'Whether the Minister\'s deportation order against Schlieske was an improper exercise of the deportation power, given it was arranged so German police could take him into custody after two failed extradition attempts.',
         conclusion:'Yes — the dominant operative purpose was disguised extradition, which was unauthorised. Improper-purpose JE.',
         keywords:['improper purpose','disguised extradition','dominant purpose','deportation'],
         facts:'A West German national. After two failed formal extradition attempts, a deportation order was arranged so that he would be received by German police on arrival in Germany.'},
    kr:{ rule:'법령상 권한이 수권되지 않은 목적으로 행사되면 무효이다 — 다투어진 행위가 수권 조항의 문언적 범위 안에 들더라도. 지배적·작용적 목적이 그 법이 수권하지 않은 것 — 예컨대 추방 권한을 위장 인도에 사용 — 이라면 그 행사는 부정한 목적의 JE이다.',
         principle:'Schlieske는 부정한 목적 JE에 관한 호주의 선도 판례다. 법원은 행사 뒤의 지배적·작용적 목적을 보고, 그 목적이 수권되지 않은 것이면 명목상 적법한 목적으로 취해질 수 있었더라도 그 행위는 무효.',
         when:'다투어진 행사가 — 형식상은 권한 안이지만 실제로는 그 법이 수권하지 않은 다른 목적을 추구하는 — 옷을 갈아입은 것처럼 보일 때 인용한다.',
         howApply:[
           '수권 조항과 그것이 수권하는 목적을 식별한다.',
           '사실관계에서 다투어진 행사의 지배적·작용적 목적을 식별한다(의도, 주변 정황, 누가 이득을 보는가).',
           '지배적 목적이 수권되지 않았다면 부정한 목적의 JE — 무효가 따른다.'
         ],
         issue:'두 차례 형식적 인도 시도가 실패한 뒤, 독일 경찰이 도착 시 그를 구금할 수 있도록 주선된 Schlieske에 대한 장관의 추방 명령이 추방 권한의 부정한 행사인가.',
         conclusion:'그렇다 — 지배적·작용적 목적은 위장 인도였고, 그것은 수권되지 않았다. 부정한 목적의 JE.',
         keywords:['부정한 목적','위장 인도','지배적 목적','추방'],
         facts:'서독 국적자. 두 차례의 형식적 인도 시도가 실패한 뒤, 독일 도착 시 독일 경찰이 그를 인도받도록 추방 명령이 주선됐다.'}},
  tickner: {
    id:'tickner', name:'Tickner v Chapman', cite:'[1995] FCAFC 1726; (1995) 57 FCR 451', icon:'✦', color:'c-violet',
    topic:'W7', category:'Case',
    en:{ rule:'A statutory duty to "consider" representations or material requires the decision-maker\'s own active intellectual engagement — reading, identifying, understanding, evaluating. The mental act cannot be delegated to an adviser; reliance on an adviser\'s summary, without the decision-maker\'s own engagement with the material, is failure to consider and a relevant-considerations / due-consideration breach.',
         principle:'Tickner sets the personal-engagement requirement for "consider" obligations. Distinguish from M1/2021, which held the standard for engagement is not high — but it must be the decision-maker\'s own engagement, not the adviser\'s.',
         when:'Use Tickner when the decision-maker delegated the act of considering to an adviser, relied on a summary that filtered out content, or otherwise failed to personally engage with the required material.',
         howApply:[
           'Identify the statutory obligation to consider (express or implied).',
           'Examine whether the decision-maker personally engaged with the material, or relied entirely on an adviser\'s filtered summary.',
           'If the latter, Tickner failure-to-consider is made out — proceed to materiality (Hossain stage 3).'
         ],
         issue:'Whether the Minister "considered" the 400 representations made about the Hindmarsh Island bridge declaration when he relied on his adviser\'s summary without reading them himself.',
         conclusion:'No — relying on the adviser\'s summary without personal engagement was not "consideration". The declaration was set aside.',
         keywords:['active consideration','intellectual process','no delegation','personal engagement'],
         facts:'In considering the Hindmarsh Island bridge declaration, Minister Tickner received 400 representations. He did not read them himself, relying instead on a summary prepared by his adviser Ms Kee.'},
    kr:{ rule:'의견이나 자료를 "고려"하라는 법령상 의무는 결정자 자신의 적극적 지적 관여 — 읽고, 식별하고, 이해하고, 평가하는 — 를 요구한다. 그 정신적 행위를 보좌관에게 위임할 수 없다 — 결정자 자신의 관여 없이 보좌관의 요약에만 의존한 것은 고려 의무 위반이고, 관련 고려사항·정당한 고려 사유 위반.',
         principle:'Tickner는 "고려" 의무에 대한 인적 관여 요건을 정한다. M1/2021과 distinguishing — M1/2021은 관여 기준이 높지 않다고 했지만, 어쨌든 결정자 자신의 관여여야지 보좌관의 관여로는 안 된다.',
         when:'결정자가 고려 행위 자체를 보좌관에게 위임했거나, 내용을 걸러 낸 요약에 의존했거나, 그 외에 요구된 자료에 인적으로 관여하지 못했을 때 인용한다.',
         howApply:[
           '고려 의무(명시 또는 묵시)를 식별한다.',
           '결정자가 자료에 인적으로 관여했는지, 아니면 전적으로 보좌관의 걸러진 요약에 의존했는지 검토한다.',
           '후자라면 Tickner의 고려 의무 위반이 성립 — materiality(Hossain 3단계)로 진행.'
         ],
         issue:'Hindmarsh Island 다리 선언에 대해 제출된 400건의 의견을, 장관이 직접 읽지 않고 보좌관 요약에 의존했을 때 "고려"했다고 할 수 있는가.',
         conclusion:'아니다 — 인적 관여 없이 보좌관 요약에만 의존한 것은 "고려"가 아니다. 선언은 취소됐다.',
         keywords:['적극적 고려','지적 과정','위임 불가','인적 관여'],
         facts:'Hindmarsh Island 다리 선언 검토에서 Tickner 장관이 400건의 의견을 받았다. 그는 그 의견들을 직접 읽지 않고 보좌관 Ms Kee가 준비한 요약에 의존했다.'}},
  'm1-2021': {
    id:'m1-2021', name:'Plaintiff M1/2021 v Minister for Home Affairs', cite:'[2022] HCA 17; (2022) 275 CLR 582', icon:'☷', color:'c-ochre',
    topic:'W7', category:'Case',
    en:{ rule:'Standard for considering representations: read, identify, understand, evaluate. Not high — deferential majority view.',
         when:'Reasonable consideration of representations ground.',
         issue:'Whether 5-word treatment of non-refoulement claim was sufficient.',
         conclusion:'Majority: standard met. Dissent (Edelman + Gleeson JJ): cursory treatment insufficient.',
         keywords:['read identify understand evaluate','representations','non-refoulement'],
         facts:'South Sudan-born plaintiff; mandatory s 501(3A) cancellation; non-refoulement representations addressed in 5 words.'},
    kr:{ rule:'의견 검토 기준: 읽기, 식별, 이해, 평가. 다수 의견은 결정자의 재량을 존중하며 문턱이 높지 않다.',
         when:'의견의 합리적 검토 사유.',
         issue:'비-반환 주장의 5단어 처리가 충분한가.',
         conclusion:'다수: 충족. 반대(Edelman + Gleeson JJ): 형식적 처리는 부족.',
         keywords:['읽기 식별 이해 평가','의견 진술','비-반환'],
         facts:'남수단 출신 원고에 대한 의무적 s 501(3A) 취소에서 비-반환 주장이 5단어로 처리되었다.'}},
  green: {
    id:'green', name:'Green v Daniels', cite:'(1977) 51 ALJR 463', icon:'✕', color:'c-coral',
    topic:'W7', category:'Case',
    en:{ rule:'A policy that inflexibly substitutes for statutory criteria — applied automatically, without engagement with the statutory question on the individual facts — is unlawful. The decision-maker must apply the empowering Act, not a policy proxy. This is the inflexible-application-of-policy ground (sometimes called "fettering discretion").',
         principle:'Green v Daniels is the leading Australian authority on the inflexible-policy ground. Policy can guide; it cannot displace the statutory inquiry. Distinguish M64, where a tiered priority policy with an exception clause was upheld because evaluative discretion was preserved.',
         when:'Use Green when a decision-maker applied a policy mechanically — automatic exclusion, fixed bar, cookie-cutter outcome — without engaging with the statutory criteria for the individual case.',
         howApply:[
           'Identify the statutory criteria the decision-maker was required to apply.',
           'Identify the policy and how it was applied — was it mechanical and automatic, or used as a guide subject to evaluation?',
           'If the policy displaced the statutory inquiry on the individual facts, Green is engaged — invalidity follows.'
         ],
         issue:'Whether the Department of Social Security\'s policy of treating school leavers as ineligible for unemployment benefit until the end of the school holidays was a lawful application of s 107.',
         conclusion:'No — the policy substituted for the statutory inquiry under s 107. Declaration that it was applied unlawfully.',
         keywords:['inflexible policy','school leaver','Green v Daniels','fettering'],
         facts:'Karen Green, a school leaver, applied for unemployment benefit. Departmental policy treated school leavers as automatically ineligible until the end of the school holidays, regardless of their individual circumstances.'},
    kr:{ rule:'법적 기준을 경직되게 대체하는 정책 — 개별 사실에 대한 법령상 질문과의 관여 없이 자동으로 적용되는 정책 — 은 위법이다. 결정자는 정책 대용물이 아니라 수권법을 적용해야 한다. 이게 정책의 경직된 적용 사유(때로 "재량의 fettering").',
         principle:'Green v Daniels는 정책 경직 적용 사유에 관한 호주의 선도 판례다. 정책은 안내할 수 있지만 법령상 분석을 대체할 수는 없다. M64와 distinguishing — 거기서는 예외 조항을 둔 계층적 우선순위 정책이 평가적 재량을 보존했기에 유효였다.',
         when:'결정자가 정책을 기계적으로 적용했을 때 — 자동 배제, 고정 차단, 쿠키 커터 결과 — 개별 사건의 법령상 기준에 관여 없이 인용한다.',
         howApply:[
           '결정자가 적용해야 했던 법령상 기준을 식별한다.',
           '정책과 그것이 어떻게 적용됐는지 식별한다 — 기계적·자동적이었는가, 아니면 평가에 종속된 안내로 사용됐는가.',
           '정책이 개별 사실에 대한 법령상 분석을 대체했다면 Green이 작동 — 무효가 따른다.'
         ],
         issue:'사회보장부의 정책 — 졸업생을 방학 종료까지 자동으로 실업급여 부적격으로 다루는 — 이 s 107의 적법한 적용인가.',
         conclusion:'아니다 — 정책이 s 107의 법령상 분석을 대체했다. 위법 적용에 대한 declaration.',
         keywords:['경직된 정책','학교 졸업생','Green v Daniels','fettering'],
         facts:'학교 졸업생 Karen Green이 실업급여를 신청했다. 부처 정책은 졸업생을 개별 사정과 무관하게 방학 종료까지 자동으로 부적격으로 다루었다.'}},
  m64: {
    id:'m64', name:'Plaintiff M64/2015 v Minister for Immigration and Border Protection', cite:'[2015] HCA 50; (2015) 258 CLR 173', icon:'◫', color:'c-forest',
    topic:'W7', category:'Case',
    en:{ rule:'A tiered priority policy that ranks classes of visa applicants for processing order is permissible — and not an unlawful fetter on discretion — if it preserves evaluative discretion in the individual case. The PAM 3 exception clause, allowing departure from the priority order in particular cases, negated the inflexibility that would otherwise have engaged Green v Daniels.',
         principle:'M64 is the modern counterpoint to Green v Daniels. Properly drafted priority or guidance policies — those preserving genuine individual evaluation through exception clauses — survive unlawful-policy challenges. The drafting matters: rigid policy = Green; flexible policy with exceptions = M64.',
         when:'Use M64 to defend a properly drafted priority/guidance policy against a Green-style challenge, or as a contrast point when arguing that a particular policy crosses the Green line into inflexibility.',
         howApply:[
           'Identify the priority/guidance policy and locate any exception clause that permits departure on individual facts.',
           'If a real exception mechanism exists and was genuinely available, M64 protects the policy from a Green challenge.',
           'If no exception or exception was nominal/illusory, the policy crosses into Green territory and is unlawful.'
         ],
         issue:'Whether the Department\'s tiered priority policy — ranking IMA-proposed Subclass 202 visas at the lowest priority — was an unlawful inflexible policy.',
         conclusion:'No — the PAM 3 exception clause preserved evaluative discretion in individual cases. M64 distinguished from Green v Daniels.',
         keywords:['priorities policy','exception clause','PAM 3','M64 contrast'],
         facts:'An Afghan-born proposer applied for a Subclass 202 visa for 4 family members. The Departmental priority policy ranked IMA-proposed visas at the lowest priority; July 2014 backlog was approximately 45,000.'},
    kr:{ rule:'비자 신청자 처리 순서를 계층적으로 우선순위 매기는 정책 — 개별 사건에서 평가적 재량을 보존한다면 — 은 적법하며 재량의 위법한 fetter가 아니다. 특정 사건에서 우선순위에서 벗어나는 것을 허용한 PAM 3의 예외 조항이, 그렇지 않으면 Green v Daniels를 작동시킬 경직성을 부정했다.',
         principle:'M64는 Green v Daniels의 현대적 반대편이다. 제대로 짜인 우선순위·안내 정책 — 예외 조항으로 진정한 개별 평가를 보존하는 — 은 위법한 정책 다툼을 살아남는다. 작성이 결정적 — 경직된 정책 = Green, 예외 있는 유연한 정책 = M64.',
         when:'제대로 짜인 우선순위·안내 정책을 Green식 다툼에 맞서 방어할 때, 또는 특정 정책이 Green의 경직성 선을 넘었다고 주장할 때 대조점으로 인용한다.',
         howApply:[
           '우선순위·안내 정책을 식별하고, 개별 사실에서 벗어남을 허용하는 예외 조항을 찾는다.',
           '실질적 예외 메커니즘이 있고 진정으로 사용 가능했다면, M64가 Green 다툼에서 정책을 보호.',
           '예외가 없거나 명목적·환상적이라면 정책이 Green 영토로 넘어가 위법.'
         ],
         issue:'부처의 계층적 우선순위 정책 — IMA 제안 Subclass 202 비자를 최하위에 둔 — 이 위법한 경직 정책인가.',
         conclusion:'아니다 — PAM 3 예외 조항이 개별 사건에서 평가적 재량을 보존했다. Green v Daniels와 distinguishing.',
         keywords:['우선순위 정책','예외 조항','PAM 3','M64 대조'],
         facts:'아프가니스탄 출신 제안자가 가족 4인 Subclass 202 비자를 신청했다. 부처 우선순위 정책은 IMA 제안 비자를 최하위에 두었고, 2014년 7월 대기는 약 45,000명이었다.'}},
  enfield: {
    id:'enfield', name:'Corporation of the City of Enfield v Development Assessment Commission', cite:'[2000] HCA 5; (2000) 199 CLR 135', icon:'⚓', color:'c-blue',
    topic:'W8', category:'Case',
    en:{ rule:'Where a statute makes a particular fact a precondition to the exercise of power — a "jurisdictional fact" — the court determines the existence of that fact for itself on the evidence. The decision-maker\'s view of the fact receives no special weight or deference. This is a structural feature of jurisdictional facts: because the power does not exist unless the fact does, the court cannot delegate the question to the very body whose power depends on it.',
         principle:'Enfield is the leading Australian authority on jurisdictional facts. It draws a sharp line between two kinds of fact-finding: ordinary findings within power (which the court reviews only for legal error, not on the merits) and jurisdictional facts (which the court determines independently). The doctrine matters because jurisdictional-fact errors are "always-JE" — they bypass the materiality limb (a power that never arose cannot be saved by saying the result would have been the same). SZMDS later addressed state-of-mind / "subjective" jurisdictional facts and held the threshold there is illogicality / irrationality, not de novo determination.',
         when:'Use Enfield when the statutory power is conditioned on a particular factual state of affairs and the applicant says that fact does not exist (or did not at the relevant time). It is the case that lets you escape the deferential standard normally applied to fact-finding.',
         howApply:[
           'Read the empowering provision and identify any factual precondition to the exercise of power (e.g. "the Authority may approve X if the activity is a Y").',
           'Argue that the precondition is a jurisdictional fact — its truth is essential for the power to arise.',
           'If accepted, the court determines the fact itself on the evidence. The decision-maker\'s view receives no deference.',
           'For state-of-mind preconditions ("if the Minister is satisfied that…"), use SZMDS — the test there is illogicality / irrationality, not independent determination.',
           'Jurisdictional-fact errors are always-JE — no materiality limb. Remedy: certiorari + (usually) prohibition or mandamus to remake the decision on the correct facts.'
         ],
         issue:'Whether the classification of a proposed waste-recycling activity as a "special industry" — a precondition to the Development Assessment Commission\'s power to approve it under SA planning law — was a jurisdictional fact that the court should determine for itself.',
         conclusion:'Yes — the classification was a jurisdictional fact. The court determined the question independently on the evidence; the Commission\'s view received no deference.',
         keywords:['jurisdictional fact','no deference','Enfield','always-JE'],
         facts:'A planning authority approved a waste-recycling facility on the basis that the activity was a "special industry" within the meaning of the SA planning regime. The Corporation of Enfield (the local council) challenged the classification.'},
    kr:{ rule:'법령이 어떤 특정 사실을 권한 행사의 전제로 정한 경우 — 즉 "관할권적 사실(jurisdictional fact)" — 법원이 제출된 증거를 토대로 그 사실의 존재 여부를 직접 판단한다. 결정자의 견해에 특별한 비중이나 존중이 주어지지 않는다. 관할권적 사실의 구조적 특성이다 — 그 사실이 없으면 권한 자체가 존재하지 않으므로, 그 권한이 의존하는 바로 그 기관에 이 질문을 맡길 수 없다.',
         principle:'Enfield는 호주의 관할권적 사실에 관한 선도 판례다. 두 종류의 사실인정에 분명한 선을 긋는다 — 권한 내의 일상적 사실인정(법원은 법적 오류만 심사하지 본안은 보지 않음)과 관할권적 사실(법원이 독립적으로 판단함). 이 법리가 중요한 이유는 관할권적 사실 오류가 "always-JE"이기 때문 — materiality 단계를 거치지 않는다(애초에 발생하지 않은 권한은 "결과가 같았을 것"이라는 말로 살릴 수 없다). SZMDS는 이후 주관적/state-of-mind 관할권적 사실을 다루며, 그 자리에서는 비논리성·비합리성이 기준이지 de novo 판단은 아니라고 정리했다.',
         when:'법령상 권한이 특정 사실 상태를 조건으로 하고, 신청인이 그 사실이 존재하지 않는다(또는 관련 시점에 없었다)고 주장할 때 인용한다. 사실인정에 통상 적용되는 deference 기준에서 벗어나게 해 주는 판례다.',
         howApply:[
           '수권조항을 읽고 권한 행사의 사실적 전제가 있는지 식별한다(예: "그 행위가 Y인 경우 당국이 X를 승인할 수 있다").',
           '그 전제가 관할권적 사실 — 그 사실이 진실이어야 권한이 발생하는 것 — 임을 주장한다.',
           '인정되면 법원이 직접 증거로 그 사실을 판단한다. 결정자의 견해는 deference 없음.',
           '주관적 전제("장관이 만족하는 경우…")라면 SZMDS를 쓴다 — 그 자리의 기준은 비논리성·비합리성이지 독립적 판단이 아니다.',
           '관할권적 사실 오류는 always-JE — materiality 단계 없음. 구제: certiorari + (보통) prohibition 또는 mandamus로 정확한 사실에서 결정 재실시.'
         ],
         issue:'폐기물 재활용 시설이 SA 계획법상 "특수 산업"에 해당하는지의 분류 — Development Assessment Commission이 승인 권한을 행사하기 위한 전제 — 가 법원이 직접 판단해야 하는 관할권적 사실인가.',
         conclusion:'그렇다 — 그 분류는 관할권적 사실이다. 법원이 증거로 직접 판단했고, 위원회의 견해는 deference 받지 않았다.',
         keywords:['관할권적 사실','존중 없음','Enfield','always-JE'],
         facts:'계획 당국이 폐기물 재활용 시설을 SA 계획 체계상 "특수 산업"에 해당한다는 전제로 승인했다. Enfield Corporation(지방 의회)이 그 분류를 다툰 사건.'}},
  szmds: {
    id:'szmds', name:'Minister for Immigration and Citizenship v SZMDS', cite:'[2010] HCA 16; (2010) 240 CLR 611', icon:'⊝', color:'c-violet',
    topic:'W8', category:'Case',
    en:{ rule:'Illogical or irrational reasoning in fact-finding can amount to jurisdictional error — but the threshold is high. Mere disagreement with the inference drawn, or a finding the reviewing court would not have made, is not enough. The reasoning must be one no reasonable decision-maker could have engaged in. For state-of-mind preconditions ("if the Minister is satisfied that…"), this is the relevant test, not the Enfield independent-determination approach.',
         principle:'SZMDS sits at the intersection of jurisdictional facts and unreasonableness. Where a statute conditions power on a decision-maker\'s state of mind ("satisfied that X"), the court does not redetermine X for itself (that would override the statutory grant of evaluative judgment). Instead it asks whether the reasoning that produced the satisfaction is illogical or irrational — a high bar. The case demonstrates the doctrine\'s genuine bite (the majority found no JE on the facts but the test itself is real) and is read in tandem with Li (legal unreasonableness more generally) and Enfield (objective jurisdictional facts).',
         when:'Use SZMDS when the impugned finding is one the statute committed to the decision-maker\'s satisfaction or judgment, and the applicant says the reasoning was illogical or irrational. It is the right tool for "Minister was satisfied" / credibility / inference-from-evidence challenges.',
         howApply:[
           'Identify the statutory precondition — is it objective ("a Y industry": Enfield route) or subjective ("if satisfied that Y": SZMDS route)?',
           'For subjective preconditions, the question is illogicality or irrationality of the reasoning, not whether the court agrees with the conclusion.',
           'Hold a high threshold — disagreement, alternative inferences, or different weight allocations are not enough; the reasoning must be one no reasonable decision-maker could engage in.',
           'Frame the argument structurally — point to specific reasoning steps that defy logic (e.g. internal contradictions, inferences without an evidentiary base, conclusions that ignore uncontradicted evidence).',
           'On materiality, apply Hossain stage 3 — but if the decision-maker\'s state of mind is itself the jurisdictional precondition, the error may be always-JE (Enfield-adjacent territory).'
         ],
         issue:'Whether the Refugee Review Tribunal\'s rejection of the Pakistani plaintiff\'s credibility — central to its denial of his sexuality-based persecution claim — was illogical or irrational and therefore jurisdictional error.',
         conclusion:'Majority: no JE. The tribunal\'s reasoning, while not the only one possible, was within the range of reasonable conclusions; it was not illogical or irrational. The high threshold was not met.',
         keywords:['illogicality','irrationality','high threshold','state of mind'],
         facts:'A Pakistani man claimed refugee status on the basis of persecution due to his sexuality. The Refugee Review Tribunal rejected his credibility based on inferences from inconsistencies in his evidence. He challenged the credibility findings as illogical.'},
    kr:{ rule:'사실인정의 비논리적·비합리적 추론은 관할권적 오류를 구성할 수 있다 — 다만 문턱이 높다. 단순히 추론에 동의하지 않거나, 심사 법원이라면 다른 결론을 내렸을 것이라는 정도로는 부족하다. 합리적인 결정자라면 결코 따를 수 없는 추론이어야 한다. 주관적 전제("장관이 X라고 만족하는 경우…")에서는 이 기준이 적용되며, Enfield의 독립적 판단 접근은 적용되지 않는다.',
         principle:'SZMDS는 관할권적 사실과 비합리성의 교차점에 선다. 법령이 권한을 결정자의 상태(satisfaction)에 조건 지운 경우("X에 만족하는 경우"), 법원이 X를 직접 다시 판단하지 않는다 — 그러면 평가적 판단을 결정자에게 부여한 법령 의도를 뒤집는 셈이 된다. 대신 그 만족을 만들어 낸 추론이 비논리적·비합리적인지를 묻는다 — 문턱이 높다. 이 판결은 그 법리에 진짜 무게가 있음을 보여 주며(다수의견은 사실에서 JE를 부정했지만 기준 자체는 실재한다), Li(일반적 법적 비합리성), Enfield(객관적 관할권적 사실)와 함께 읽는다.',
         when:'다투어진 인정이 법령이 결정자의 만족·판단에 맡긴 것이고, 신청인이 그 추론이 비논리적·비합리적이라고 주장할 때 인용한다. "장관이 만족했다" / 신빙성 / 증거로부터의 추론을 다투는 사안의 도구.',
         howApply:[
           '법령상 전제를 식별한다 — 객관적("Y 산업이라면": Enfield 경로)인가, 주관적("Y라고 만족하는 경우": SZMDS 경로)인가.',
           '주관적 전제라면 질문은 추론의 비논리성·비합리성이지, 법원이 결론에 동의하는가가 아니다.',
           '문턱을 높게 유지한다 — 이견, 다른 추론, 다른 가중치 배분으로는 부족하다. 합리적 결정자가 결코 따를 수 없는 추론이어야 한다.',
           '주장은 구조적으로 짠다 — 논리에 어긋나는 구체적 추론 단계를 짚는다(내적 모순, 증거 기반 없는 추론, 반박 없는 증거를 무시하는 결론 등).',
           'Materiality는 Hossain 3단계로 — 다만 결정자의 상태 자체가 관할권적 전제라면 그 오류는 always-JE일 수 있다(Enfield 인접 영역).'
         ],
         issue:'난민심사심판소가 파키스탄 신청인의 신빙성을 부정한 것 — 성지향 박해 주장 거부의 핵심 — 이 비논리적·비합리적이며 관할권적 오류인가.',
         conclusion:'다수: JE 아님. 심판소의 추론이 유일한 결론은 아니었지만 합리적 결론의 범위 안에 있었다 — 비논리적이거나 비합리적이지 않았다. 높은 문턱이 충족되지 않았다.',
         keywords:['비논리성','비합리성','높은 문턱','state of mind'],
         facts:'파키스탄 남성이 자신의 성지향으로 인한 박해를 이유로 난민 지위를 신청했다. 난민심사심판소가 그의 진술 내 불일치에서 추론을 끌어내 신빙성을 부정했다. 그는 그 신빙성 인정이 비논리적이라고 다툰 사건.'}},
  dua16: {
    id:'dua16', name:'Minister for Home Affairs v DUA16', cite:'[2020] HCA 46; (2020) 271 CLR 550', icon:'⊕', color:'c-ochre',
    topic:'W8', category:'Case',
    en:{ rule:'A failure to exercise a procedural power available to the decision-maker — for example, the power to invite further comment, to put adverse material, or to grant an extension — can itself be legally unreasonable. Procedural decisions attract closer review than substantive merits decisions because they shape the fairness of the process leading to the result; the deference owed to substantive merits judgments is less appropriate where the decision under review is purely about how to run the procedure.',
         principle:'DUA16 extended Li-style legal unreasonableness from substantive outcomes to procedural decisions. The structural reason: when a court reviews a substantive outcome, it must give the decision-maker latitude in weighing competing considerations; when it reviews a procedural choice (invite comment? grant extension? put the new material?), there are no merits to defer to — only fairness and rationality. The case is the doctrinal home of "procedural unreasonableness" as a distinct ground, often pleaded alongside PF (Kioa/Saeed) but with a different analytic structure: the question is not whether PF was breached, but whether the procedural exercise was so deficient as to fall outside reasonable decision-making.',
         when:'Use DUA16 when the impugned conduct is a procedural choice or omission — not putting material, refusing extension, declining to invite comment — and the failure looks unreasonable on the face of the record. It is often a useful complement or alternative to a Kioa PF argument.',
         howApply:[
           'Identify the procedural power that was (or was not) exercised — power to invite comment, put adverse material, grant adjournment, request submissions, etc.',
           'Frame the question around procedural reasonableness — was the choice to use or not use the power one a reasonable decision-maker on this statute could have made?',
           'Note the lower deference owed to procedural decisions (compared to substantive merits) — the court is closer to the line.',
           'Consider running this in parallel with a PF argument (Kioa, VEAL) — the PF analysis asks whether the duty was breached; the DUA16 analysis asks whether the procedural exercise was unreasonable.',
           'Materiality applies (Hossain stage 3 / Nathanson) — but in PF-adjacent procedural contexts the bar is generally low.'
         ],
         issue:'Whether the migration tribunal\'s failure to invite the plaintiff to comment on adverse country information that emerged late in the proceedings was legally unreasonable.',
         conclusion:'Yes — failing to invite comment in the circumstances was procedurally unreasonable; it produced jurisdictional error.',
         keywords:['procedural unreasonableness','invitation','closer review','DUA16'],
         facts:'In a migration tribunal review, adverse country information bearing on the plaintiff\'s claim emerged late in the process. The tribunal had a procedural power to invite comment on the new material but did not exercise it before deciding.'},
    kr:{ rule:'결정자에게 주어진 절차적 권한 — 예컨대 추가 의견을 초청할 권한, 불리한 자료를 제시할 권한, 기간을 연장할 권한 — 을 행사하지 않은 것 자체가 법적으로 비합리적일 수 있다. 절차적 결정은 실체적 본안 결정보다 더 엄격한 심사를 받는다 — 결과로 가는 절차의 공정성을 형성하기 때문이며, 본안 판단에 적용되는 deference가 절차 운용의 선택에는 그만큼 적합하지 않기 때문이다.',
         principle:'DUA16은 Li 식의 법적 비합리성을 실체적 결과에서 절차적 결정으로 확장한 판결이다. 구조적 이유: 법원이 실체적 결과를 심사할 때는 결정자에게 가중치 부여의 여지를 주어야 하지만, 절차적 선택(의견 초청? 연장 부여? 새 자료 제시?)을 심사할 때는 deference할 본안이 없고 — 공정성과 합리성만 있다. 이 판결은 "절차적 비합리성"을 독립된 사유로 자리잡게 한 곳이며, PF(Kioa/Saeed)와 함께 자주 주장되지만 분석 구조가 다르다 — PF는 의무가 위반됐는지를 묻고, DUA16은 절차적 행사가 합리적 의사결정 범위 밖일 만큼 결함이 있었는지를 묻는다.',
         when:'다투어진 행위가 절차적 선택이나 누락 — 자료 미제시, 연장 거부, 의견 초청 거부 — 이고, 그 누락이 기록상 비합리적으로 보일 때 인용한다. Kioa PF 주장의 보충이나 대안으로 자주 쓰인다.',
         howApply:[
           '행사됐(거나 행사되지 않았)던 절차적 권한을 식별한다 — 의견 초청 권한, 불리 자료 제시 권한, 연기 권한, 의견 제출 요청 권한 등.',
           '질문을 절차적 합리성으로 짠다 — 그 권한을 쓴(또는 쓰지 않은) 선택이 이 법령상 합리적 결정자가 할 수 있는 선택이었는가.',
           '절차적 결정에 대한 deference가 더 낮다는 점을 짚는다(실체적 본안에 비해) — 법원이 선에 더 가까이 간다.',
           'PF 주장(Kioa, VEAL)과 병행해 돌리는 것을 고려한다 — PF는 의무 위반 여부, DUA16은 절차적 행사의 합리성을 묻는다.',
           'Materiality는 적용된다(Hossain 3단계 / Nathanson) — 다만 PF 인접의 절차적 맥락에서는 보통 문턱이 낮다.'
         ],
         issue:'이민 tribunal이 절차 막바지에 등장한 신청인 청구에 영향을 주는 불리한 출신국 정보에 대해 신청인에게 의견 제출을 초청하지 않은 것이 법적으로 비합리적인가.',
         conclusion:'그렇다 — 그 상황에서 의견을 초청하지 않은 것은 절차적으로 비합리적이며 관할권적 오류를 일으켰다.',
         keywords:['절차적 비합리성','초청','엄격한 심사','DUA16'],
         facts:'이민 tribunal 재심사에서 신청인 청구에 영향을 주는 불리한 출신국 정보가 절차 막바지에 나왔다. tribunal에는 그 새 자료에 대한 의견을 초청할 절차적 권한이 있었지만, 결정 전에 그 권한을 행사하지 않았다.'}},
  stretton: {
    id:'stretton', name:'Minister for Immigration and Border Protection v Stretton', cite:'[2016] FCAFC 11; (2016) 237 FCR 1', icon:'∥', color:'c-gray',
    topic:'W8', category:'Case',
    en:{ rule:'Substantive review of merits-affecting discretionary decisions remains deferential. The court does not reweigh — it asks only whether the reasoning lacks "evident and intelligible justification" in the Li sense, or whether the result is one no reasonable decision-maker on the same statute could reach. The deference is greater for substantive merits choices than for procedural choices (DUA16).',
         principle:'Stretton (FCAFC, Allsop CJ) is the leading Federal Court synthesis of legal unreasonableness for substantive merits decisions. It applies the Li test (evident and intelligible justification) but with explicit calibration: substantive discretion attracts more deference than procedural choice. The case is the standard citation for unreasonableness review of visa-cancellation type decisions, and forms part of the post-Li trilogy alongside DUA16 (procedural unreasonableness, HCA) and Li itself (the underlying reformulation).',
         when:'Use Stretton when challenging a substantive merits decision (visa cancellation, character finding, weight given to a factor) on unreasonableness grounds. It frames the deferential calibration the court will apply.',
         howApply:[
           'Frame the challenge in Li terms — did the reasoning lack evident and intelligible justification, or is the result one no reasonable decision-maker could reach?',
           'Acknowledge the deference owed to substantive merits judgments — the court does not reweigh, it patrols the outer bounds of reasonable decision-making.',
           'Identify specific reasoning gaps or disproportions that put the decision outside the range — opaque reasoning, gross weighting errors, results disproportionate to statutory purpose.',
           'Distinguish from DUA16 procedural-unreasonableness territory — Stretton is about substantive choices, DUA16 about procedural ones.',
           'Apply materiality (Hossain stage 3) — was there a realistic possibility that, with reasoned justification, a different outcome could have followed?'
         ],
         issue:'Whether the Minister\'s s 501 visa cancellation decision against Stretton was legally unreasonable in its reasoning about the character test.',
         conclusion:'On the facts the decision was unreasonable — but the deferential standard remained the operative test; the result was based on identifiable reasoning gaps, not on the court\'s own preferred outcome.',
         keywords:['substantive review','deference','Stretton','evident and intelligible justification'],
         facts:'The Minister cancelled Mr Stretton\'s visa under s 501 on character grounds. The reasoning about the character test — including weighing of his personal circumstances — was challenged as legally unreasonable.'},
    kr:{ rule:'본안에 영향을 주는 재량 결정에 대한 실체적 심사는 여전히 결정자의 재량을 존중한다. 법원은 가중치를 다시 매기지 않는다 — Li가 말한 "명확하고 이해 가능한 정당화"가 추론에 결여됐는지, 또는 같은 법령에서 합리적 결정자라면 도달할 수 없는 결과인지만 묻는다. 그 deference는 절차적 선택(DUA16)보다 실체적 본안 선택에서 더 크다.',
         principle:'Stretton(연방항소법원, Allsop CJ)은 실체적 본안 결정에 대한 법적 비합리성을 가장 또렷이 종합한 연방법원 판결이다. Li 기준(evident and intelligible justification)을 적용하면서도 명시적 보정을 한다 — 실체적 재량은 절차적 선택보다 더 큰 deference를 받는다. 비자 취소형 결정에 대한 비합리성 심사의 표준 인용 판례이며, Li(기저 재구성), DUA16(절차적 비합리성, HCA)과 함께 Li-이후 3부작을 이룬다.',
         when:'실체적 본안 결정(비자 취소, 인격 인정, 어떤 요소에 부여한 가중치)을 비합리성 사유로 다툴 때 인용한다. 법원이 적용할 deference 보정 framing을 짠다.',
         howApply:[
           '쟁점을 Li framing으로 짠다 — 추론에 evident and intelligible justification이 결여됐는가, 또는 합리적 결정자가 도달할 수 없는 결과인가.',
           '실체적 본안 판단에 부여되는 deference를 인정한다 — 법원은 가중치를 다시 매기지 않고, 합리적 의사결정의 외연만 단속한다.',
           '결정을 그 범위 밖으로 밀어내는 구체적 추론 공백이나 비례성 결여를 짚는다 — 불투명한 추론, 가중치 부여의 큰 오류, 법령 목적에 비례성을 잃은 결과.',
           'DUA16의 절차적 비합리성 영토와 구분한다 — Stretton은 실체적 선택, DUA16은 절차적 선택.',
           'Materiality는 적용한다(Hossain 3단계) — 정당화된 추론이 있었다면 다른 결과가 따랐을 현실적 가능성이 있었는가.'
         ],
         issue:'장관의 s 501 비자 취소 결정의 인격 요건 추론이 법적으로 비합리적인가.',
         conclusion:'사실관계에서 비합리적이었다 — 다만 deferential한 기준은 그대로 운영적 기준으로 남았고, 결과는 식별 가능한 추론 공백에 기반한 것이지 법원의 선호 결과에 기반한 것이 아니었다.',
         keywords:['실체적 심사','존중','Stretton','명확하고 이해 가능한 정당화'],
         facts:'장관이 s 501 인격 사유로 Stretton의 비자를 취소했다. 인격 요건에 대한 추론 — 그의 개인적 사정 가중치 부여를 포함 — 이 법적 비합리성으로 다투어졌다.'}},
  acf: {
    id:'acf', name:'Australian Conservation Foundation Inc v Commonwealth', cite:'[1980] HCA 53; (1980) 146 CLR 493', icon:'✓', color:'c-blue',
    topic:'W9', category:'Case',
    en:{ rule:'To have standing to seek a declaration or injunction in public-law litigation, a plaintiff must show a "special interest" in the subject-matter of the action — an interest beyond that of an ordinary member of the public, and beyond mere intellectual or emotional concern. Conservation, ideological or moral interest alone is not enough.',
         principle:'ACF set the common-law baseline test for public-law standing in Australia. The "special interest" formulation has been refined and stretched in later cases (Onus on cultural custodianship, North Coast EC on advocacy bodies, Bateman\'s Bay on commercial competitors, Argos on economic detriment) but the core question is unchanged: is your interest something more than a member of the general public would have? Statute can override the baseline — e.g. the open-standing provision in s 487 EPBC for environmental matters — so always check the empowering Act first.',
         when:'Use ACF whenever standing is in issue for a declaration or injunction in administrative-law litigation, and there is no statutory open-standing provision in play. It is also the lens through which Onus, North Coast, Bateman\'s Bay, Argos, and Right to Life are read.',
         howApply:[
           'Check first for any statutory standing provision in the empowering Act (e.g. EPBC s 487). If statute confers open or extended standing, apply that — ACF is the fallback.',
           'Identify the plaintiff\'s actual stake in the subject-matter — economic, proprietary, custodial, cultural, professional, regulatory etc. Be concrete, not abstract.',
           'Compare that stake to what a member of the general public would have. Anything truly distinctive — economic detriment from competition (Argos), cultural custodianship (Onus), dedicated advocacy with statutory recognition (North Coast EC), competitive commercial position (Bateman\'s Bay) — can ground special interest.',
           'Mere ideological commitment, however sincere, is not enough — that was the very point of ACF itself.',
           'Note the practical context: the standing inquiry is ultimately a relational one between the plaintiff, the defendant, and the relief sought, not a fixed checklist.'
         ],
         issue:'Whether the Australian Conservation Foundation had standing to seek a declaration challenging Commonwealth approvals for the Iwasaki tourist development at Yeppoon.',
         conclusion:'No — on the facts as they then stood, the Foundation\'s interest in conservation outcomes was not "special" in the sense the rule requires; it was an interest of the same kind, though deeper in degree, as that of any concerned member of the public.',
         keywords:['standing','special interest','Gibbs J','public-law litigation'],
         facts:'The Australian Conservation Foundation sought to challenge Commonwealth environmental approvals for a large tourist development at Yeppoon, Queensland. The Commonwealth raised standing as a threshold objection.'},
    kr:{ rule:'공공법 소송에서 declaration이나 injunction을 구하려면 원고가 사건의 주제에 대해 "특별한 이해(special interest)"를 가져야 해. 일반 시민이 가지는 정도를 넘어서는, 단순한 지적·정서적 관심 이상의 이해여야 한다. 환경보전·이념·도덕적 관심만으로는 부족해.',
         principle:'ACF는 호주 공공법 소송에서 원고적격의 보통법상 기본선을 그어 둔 판결이다. "특별한 이해" 기준은 이후 판례에서 다듬어지고 넓혀졌지만(문화적 수호의 Onus, 시민단체의 North Coast EC, 상업적 경쟁자의 Bateman\'s Bay, 경제적 불이익의 Argos), 핵심 질문은 그대로 — 당신의 이해가 일반 시민이 가지는 것 이상의 무엇인가? 다만 법령이 이 기본선을 덮어쓸 수 있다(예: EPBC s 487의 환경 사안 open standing). 그래서 수권법을 먼저 확인하는 게 순서야.',
         when:'declaration이나 injunction의 원고적격이 다투어지고 별도의 법정 open-standing 조항이 없는 행정법 소송이라면 ACF가 출발점이다. Onus, North Coast EC, Bateman\'s Bay, Argos, Right to Life도 같은 렌즈로 읽힙니다.',
         howApply:[
           '먼저 수권법에 standing 조항이 있는지 확인해(예: EPBC s 487). 법령이 open standing을 주면 그쪽이 우선이고, ACF는 보충적 기준이다.',
           '원고가 사건 주제에 대해 실제로 갖는 이해를 구체적으로 짚어 봐 — 경제적·재산적·수호적·문화적·직업적·규제상 이해 등. 추상적으로 말하지 말고 구체적으로.',
           '그 이해를 일반 시민이 가지는 정도와 비교해. 진짜로 구별되는 것이라면 — 경쟁으로 인한 경제적 불이익(Argos), 문화적 수호(Onus), 법령에서 인정한 대표성을 가진 시민단체(North Coast EC), 상업적 경쟁 위치(Bateman\'s Bay) — 모두 special interest의 근거가 될 수 있다.',
           '단순한 이념적 신념은, 아무리 진지해도 부족해요 — 이게 바로 ACF 사건의 핵심 메시지였습니다.',
           '실무적 맥락을 잊지 마. standing은 결국 원고·피고·구하는 구제 사이의 관계적 판단이지, 고정된 체크리스트가 아니다.'
         ],
         issue:'호주환경보전재단(ACF)이 Yeppoon의 Iwasaki 관광 개발에 대한 연방 승인을 다툴 declaration을 구할 적격이 있는가.',
         conclusion:'아니오 — 당시 사실관계에서 재단의 환경 보전 관심은 법이 요구하는 의미의 "특별한 이해"는 아니었다. 정도의 차이일 뿐, 일반 시민의 우려와 같은 종류의 관심이라는 판단이었습니다.',
         keywords:['원고적격','특별한 이해','Gibbs J','공공법 소송'],
         facts:'호주환경보전재단이 퀸즐랜드 Yeppoon의 대규모 관광 개발에 대한 연방 환경 승인을 다투려 했다. 연방 측이 관문 단계에서 standing을 다툰 사건이다.'}},
  onus: {
    id:'onus', name:'Onus v Alcoa of Australia Ltd', cite:'[1981] HCA 50; (1981) 149 CLR 27', icon:'☼', color:'c-forest',
    topic:'W9', category:'Case',
    en:{ rule:'The cultural and spiritual interest of Aboriginal custodians in protecting sacred sites or objects on traditional country is sufficient to ground special-interest standing under ACF. Custodianship is more than ideological or moral concern — it is a substantive, distinctive interest tied to the subject-matter of the proceedings.',
         principle:'Onus extended ACF\'s "special interest" beyond conventional economic or property interests to indigenous cultural custodianship. The case opened the door for indigenous custodians to seek public-law remedies (declaration, injunction) protecting cultural and spiritual interests.',
         when:'Use Onus when an indigenous custodian or community seeks standing to protect cultural, spiritual or heritage interests in country, sacred sites, or objects.',
         howApply:[
           'Identify the cultural / spiritual / custodial interest — be specific (this place, these objects, this country).',
           'Frame it as a substantive interest tied to the subject-matter, not mere ideological concern (the ACF distinction).',
           'Apply ACF\'s baseline test — Onus shows custodial interests fit within "special interest".'
         ],
         issue:'Whether the Gournditch-mara people had standing to seek an injunction restraining Alcoa\'s aluminium works at Portland from disturbing sacred sites on their traditional country.',
         conclusion:'Yes — their cultural and spiritual custodianship was a special interest sufficient for standing.',
         keywords:['standing','cultural interest','custodianship','indigenous'],
         facts:'The Gournditch-mara people sought to enjoin Alcoa\'s Portland aluminium works, alleging that the works would disturb sacred sites on their traditional country.'},
    kr:{ rule:'전통 영토의 성지나 성물을 보호하는 원주민 수호자의 문화·정신적 이해는 ACF의 special-interest standing에 충분하다. 수호 관계는 이념적·도덕적 관심 이상이다 — 소송 주제에 묶인 실체적·구별되는 이해이다.',
         principle:'Onus는 ACF의 "special interest"를 통상의 경제적·재산적 이해를 넘어 원주민 문화적 수호로 확장한 판결이다. 원주민 수호자가 문화·정신적 이해를 보호하기 위해 공공법 구제(declaration, injunction)를 구할 길을 열었다.',
         when:'원주민 수호자나 공동체가 영토·성지·성물의 문화적·정신적·문화유산 이해를 보호하기 위해 standing을 구할 때 인용한다.',
         howApply:[
           '문화적·정신적·수호적 이해를 구체적으로 식별한다 — 이 장소, 이 성물, 이 영토.',
           '단순한 이념적 관심이 아니라 주제에 묶인 실체적 이해로 framing한다(ACF 구별).',
           'ACF의 기본 테스트를 적용한다 — Onus가 수호적 이해도 "special interest"에 들어맞음을 보여 준다.'
         ],
         issue:'Gournditch-mara가 Alcoa의 포틀랜드 알루미늄 작업이 그들의 전통 영토 성지를 훼손하는 것을 막을 standing을 갖는가.',
         conclusion:'그렇다 — 그들의 문화적·정신적 수호는 standing에 충분한 special interest이다.',
         keywords:['원고적격','문화적 이해','수호','원주민'],
         facts:'Gournditch-mara가 Alcoa의 포틀랜드 알루미늄 작업이 자신들의 전통 영토 성지를 훼손할 것이라며 작업의 금지를 구한 사건.'}},
  s157: {
    id:'s157', name:'Plaintiff S157/2002 v Commonwealth', cite:'[2003] HCA 2; (2003) 211 CLR 476', icon:'⛨', color:'c-ochre',
    topic:'W9', category:'Case',
    en:{ rule:'A privative clause in Commonwealth legislation cannot oust the High Court\'s s 75(v) jurisdiction to grant constitutional writs against an officer of the Commonwealth for jurisdictional error. The court achieves this by reading "decision" in the privative clause to mean a decision that is itself lawful — i.e., a decision not affected by JE — so that a JE-affected decision is not within the clause\'s protection in the first place.',
         principle:'S157 is the constitutional spine of Australian federal judicial review. It locks in two inseparable propositions:\n(1) s 75(v) is constitutionally entrenched and Parliament cannot legislate it away\n(2) the technique of "reading down" privative clauses preserves the supervisory function without striking the clause down.\n\nThe complementary State case is Kirk, which entrenches State Supreme Court supervisory jurisdiction over JE under Ch III. Together S157 and Kirk mean that no Australian legislature — Cth or State — can shield administrative decisions from JR for jurisdictional error.',
         when:'Reach for S157 whenever a Commonwealth privative clause is in play and the question is whether JR for JE remains available. It is also the case that justifies pivoting from a blocked ADJR claim (e.g. Bond, Tang) to s 75(v) / s 39B(1).',
         howApply:[
           'Identify the privative clause and what it purports to exclude (e.g., Migration Act s 474 protecting "decisions" from review).',
           'Apply the S157 reading: "decision" is read down to mean a lawful decision — a JE-affected decision is outside the clause\'s scope, not protected by it.',
           'Confirm the constitutional pivot: s 75(v) jurisdiction for jurisdictional error against Commonwealth officers cannot be ousted; the clause is preserved by reading down rather than striking down.',
           'For State decisions, cite Kirk for the equivalent entrenchment of State Supreme Court supervisory jurisdiction.',
           'Watch the 2024 feedback drafting trap: a clause using "or purported to be made" attempts to capture even JE-affected decisions and is a direct Kirk contravention — that clause itself is invalid.'
         ],
         issue:'Whether s 474 of the Migration Act 1958 — which sought to make Tribunal "decisions" final and unreviewable — excluded the High Court\'s constitutional jurisdiction under s 75(v) to review for jurisdictional error.',
         conclusion:'No — s 474 was read down to apply only to lawful decisions. JE-affected decisions fell outside the clause and remained reviewable under s 75(v). The constitutional jurisdiction was preserved.',
         keywords:['privative clause','s 75(v)','reading down','constitutional entrenchment'],
         facts:'A migration applicant challenged the Refugee Review Tribunal\'s decision. The Migration Act 1958 s 474 purported to make Tribunal decisions "final and conclusive" and unreviewable. The plaintiff invoked s 75(v) of the Constitution.'},
    kr:{ rule:'연방 법령의 배제조항(privative clause)은 영연방 공무원에 대해 관할권적 오류로 헌법적 writ를 발부할 High Court의 s 75(v) 관할을 봉쇄할 수 없다. 법원은 배제조항의 "결정"을 적법한 결정 — 즉 JE의 영향을 받지 않은 결정 — 으로 좁게 읽어, JE의 영향을 받은 결정은 애초에 그 조항의 보호 범위 밖에 있도록 한다.',
         principle:'S157은 호주 연방 사법심사의 헌법적 척추다. 분리될 수 없는 두 명제를 못박았다:\n(1) s 75(v)는 헌법적으로 보호되어 의회가 입법으로 없앨 수 없다\n(2) 배제조항을 "좁게 읽는(read down)" 기법이 조항을 무효화하지 않으면서도 감독 기능을 보존한다.\n\n주(州) 차원의 짝은 Kirk로, Ch III에 따라 주 대법원의 JE 감독관할을 헌법적으로 보호한다. S157과 Kirk를 합치면, 호주의 어느 입법부도 — 연방이든 주든 — 관할권적 오류에 대한 사법심사로부터 행정결정을 차단할 수 없다.',
         when:'연방 배제조항이 등장하고 JE에 대한 JR이 여전히 가능한지가 쟁점일 때 인용한다. ADJR이 막힌 사건(Bond, Tang 등)에서 s 75(v) / s 39B(1)로 갈아타는 정당화의 근거이기도 하다.',
         howApply:[
           '배제조항을 식별하고 그것이 무엇을 배제하려 하는지 본다(예: Migration Act s 474가 "결정"을 심사에서 보호).',
           'S157의 좁은 해석을 적용한다 — "결정"은 적법한 결정만을 의미하도록 좁게 읽고, JE의 영향을 받은 결정은 그 조항의 범위 밖에 있어 보호받지 못한다.',
           '헌법적 갈아타기를 확인한다 — 영연방 공무원에 대한 관할권적 오류의 s 75(v) 관할은 봉쇄될 수 없고, 조항은 무효화가 아니라 좁게 해석으로 보존된다.',
           '주(州) 결정에는 Kirk를 인용한다(주 대법원 감독관할의 등가적 헌법 보호).',
           '2024 피드백 함정을 주의한다 — "or purported to be made" 문구를 쓴 조항은 JE의 영향을 받은 결정까지 잡으려는 시도로 Kirk 정면 위반이며, 그 조항 자체가 무효이다.'
         ],
         issue:'Migration Act 1958 s 474 — Tribunal의 "결정"을 종국적·확정적·심사 불가로 만들려 한 조항 — 가 관할권적 오류에 대한 High Court의 s 75(v) 헌법적 관할을 배제하는가.',
         conclusion:'아니다 — s 474는 적법한 결정에만 적용되도록 좁게 해석됐다. JE의 영향을 받은 결정은 그 조항의 범위 밖에 있어 s 75(v)로 여전히 심사 가능하다. 헌법적 관할이 보존됐다.',
         keywords:['배제조항','s 75(v)','좁은 해석','헌법적 보호'],
         facts:'한 이민 신청인이 Refugee Review Tribunal의 결정을 다투었다. Migration Act 1958 s 474는 Tribunal 결정을 "종국적·확정적"이고 심사 불가로 규정하려 했다. 원고는 헌법 s 75(v)를 원용했다.'}},
  'kirk-jurisdiction': {
    id:'kirk-jurisdiction', name:'Kirk v Industrial Relations Commission (NSW)', cite:'[2010] HCA 1; (2010) 239 CLR 531', icon:'☷', color:'c-blue',
    topic:'W4', category:'Case',
    en:{ rule:'State Supreme Court supervisory jurisdiction over jurisdictional error of inferior courts/tribunals constitutionally entrenched (Ch III).',
         when:'State equivalent of S157 — privative clauses cannot oust JE supervision.',
         issue:'Whether NSW IRC privative clause excluded review for JE.',
         conclusion:'No — supervisory jurisdiction constitutionally entrenched.',
         keywords:['Kirk','State entrenchment','Ch III'],
         facts:'NSW Industrial Relations Commission decision under privative clause challenged for JE.'},
    kr:{ rule:'하급 법원·tribunal의 관할권적 오류에 대한 주 대법원의 감독 관할은 헌법적으로 보호된다(Ch III).',
         when:'S157의 주 차원 등가물 — 배제조항이 JE 감독을 배제할 수 없다.',
         issue:'NSW IRC 배제조항이 JE 심사를 배제하는가.',
         conclusion:'아니오 — 감독 관할은 헌법적으로 보호된다.',
         keywords:['Kirk','주 헌법적 보호','Ch III'],
         facts:'NSW Industrial Relations Commission의 결정이 JE를 이유로 배제조항 하에서 다투어졌다.'}},
  'kirk-criterion': {
    id:'kirk-criterion', name:'Kirk v Industrial Relations Commission (NSW)', cite:'[2010] HCA 1; (2010) 239 CLR 531', icon:'⛨', color:'c-coral',
    topic:'W4', category:'Case',
    en:{ rule:'Egregious PF breach — calling accused as a witness — is "absolutely fundamental" rule of accusatorial system; always JE without materiality inquiry.',
         when:'Identifying always-JE category for fundamental procedural defects.',
         issue:'Whether trial judge\'s allowing accused to testify against himself was JE.',
         conclusion:'Yes — fundamental rule breached.',
         keywords:['egregious PF','accusatorial','always-JE'],
         facts:'Mr Kirk called as witness in his own prosecution under WHS legislation.'},
    kr:{ rule:'중대 PF 위반 — 피고인을 증인으로 부르는 행위 — 은 대심제의 "절대적으로 근본적인 규칙"이며 중요성 심사 없이 항상 JE이다.',
         when:'근본적 절차 결함의 항상-JE 범주 식별.',
         issue:'재판부가 피고인을 자신에 대한 증인으로 부른 것이 JE인가.',
         conclusion:'그렇다 — 근본 규칙 위반.',
         keywords:['중대 PF','대심제','항상-JE'],
         facts:'WHS 법령 하의 자신에 대한 기소에서 Mr Kirk가 증인으로 호출되었다.'}},
  bhardwaj: {
    id:'bhardwaj', name:'Minister for Immigration and Multicultural and Indigenous Affairs v Bhardwaj', cite:'[2002] HCA 11; (2002) 209 CLR 597', icon:'∅', color:'c-violet',
    topic:'W4', category:'Case',
    en:{ rule:'A decision affected by jurisdictional error is no decision at all in law. Because there is no operative decision, the statutory power has not been exhausted and can be re-exercised by the same decision-maker without need for any external setting-aside or remittal. The doctrine flows from S157\'s reading-down of "decision" to mean lawful decision: a JE-affected decision is outside that meaning, so the decision-maker is free to act again.',
         principle:'Bhardwaj is the doctrinal foundation for self-correction by administrative decision-makers. It says that JE renders a decision a nullity, not merely voidable. Two practical consequences:\n(1) the original decision-maker can re-exercise the power and produce a fresh, valid decision without needing court intervention\n(2) for remedies analysis, Bhardwaj underpins why certiorari + mandamus are the standard JE pair (quash the nullity, compel re-exercise of an unexpired power). The case complements Plaintiff S157 (privative-clause framing of "decision" as lawful decision) and explains why JE-affected decisions sit outside the protected category.',
         when:'Use Bhardwaj in two contexts:\n(1) when a decision-maker realises they have made a JE-affected decision and wants to re-exercise the power without going to court\n(2) at the remedies stage, to explain why certiorari + mandamus is the structurally correct combination for JE.',
         howApply:[
           'Confirm that the original decision is affected by JE — apply the Hossain framework to identify a validity-condition breach plus materiality (or fall within an always-JE category).',
           'If JE is established, the original decision is a nullity in law — there is "no decision at all" for the empowering Act.',
           'The statutory power is therefore not exhausted; the original decision-maker can re-exercise it. No court order is strictly necessary, though a declaration may be useful for clarity.',
           'For remedies, Bhardwaj justifies the certiorari + mandamus pairing: certiorari quashes the apparent decision (clearing the air); mandamus compels re-exercise on the correct legal basis.',
           'Be careful with practical consequences: rights or obligations may have been acted on in reliance on the original decision; declaration may be needed to settle the legal state of affairs.'
         ],
         issue:'Whether the Migration Review Tribunal could remake its decision after realising it had failed to give the applicant a hearing — or whether the Tribunal had functus officio (no power left to act).',
         conclusion:'The original decision was a nullity because of the PF breach — JE means "no decision at all". The Tribunal\'s power was not exhausted and it could re-exercise it.',
         keywords:['no decision at all','re-exercise','nullity','self-correction'],
         facts:'An Indian student visa applicant\'s case was decided by the Migration Review Tribunal without giving him an opportunity to be heard. The Tribunal realised the error and remade the decision. The Minister contended the Tribunal had no power to do so because its decision (even if flawed) was final.'},
    kr:{ rule:'관할권적 오류의 영향을 받은 결정은 법적으로 "결정이 아닌 것"이다. 운영적 결정이 존재하지 않으므로 법령상 권한은 소진되지 않았고, 외부의 취소나 환송 명령 없이도 같은 결정자가 권한을 다시 행사할 수 있다. 이 법리는 S157이 "결정"을 적법한 결정으로 좁게 읽은 것에서 흘러나온다 — JE의 영향을 받은 결정은 그 의미 밖에 있으므로, 결정자는 다시 행동할 수 있다.',
         principle:'Bhardwaj는 행정 결정자의 자기 시정에 관한 교리적 토대다. JE는 결정을 단순히 취소 가능한 것이 아니라 무효(nullity)로 만든다고 말한다. 실무적 결과 두 가지:\n(1) 원 결정자가 법원 개입 없이 권한을 다시 행사해 새롭고 유효한 결정을 낼 수 있다\n(2) 구제 분석에서 certiorari + mandamus가 JE의 표준 짝패인 이유를 설명한다(무효를 무효화 + 소진되지 않은 권한의 재행사 명령). Plaintiff S157(배제조항 framing의 "결정"=적법한 결정)을 보완하며, JE의 영향을 받은 결정이 보호 범주 밖에 있는 이유를 설명한다.',
         when:'두 맥락에서 인용한다:\n(1) 결정자가 자신이 JE 영향 결정을 했음을 깨닫고 법원에 가지 않은 채 권한을 다시 행사하려 할 때\n(2) 구제 단계에서 certiorari + mandamus가 JE의 구조적으로 올바른 조합인 이유를 설명할 때.',
         howApply:[
           '원 결정이 JE의 영향을 받았는지 확인한다 — Hossain framework로 유효성 조건 위반 + materiality를 식별하거나, always-JE 범주에 해당하는지 본다.',
           'JE가 인정되면 원 결정은 법적으로 무효 — 수권법상 "결정이 없다".',
           '따라서 법령상 권한은 소진되지 않았고, 원 결정자가 다시 행사할 수 있다. 법원 명령이 엄격히 필요하지는 않지만, 명확성을 위해 declaration이 유용할 수 있다.',
           '구제에서는 Bhardwaj가 certiorari + mandamus 짝을 정당화한다 — certiorari로 외관상 결정을 무효화(공기 정화), mandamus로 정확한 법적 기반에서 재행사 명령.',
           '실무적 결과에 유의 — 원 결정에 의존해 권리·의무가 행사됐을 수 있으므로 법적 상태를 정리하기 위해 declaration이 필요할 수 있다.'
         ],
         issue:'Migration Review Tribunal이 신청인에게 청문 기회를 주지 않은 사실을 깨달은 뒤 결정을 다시 할 수 있는가, 아니면 functus officio(더 이상 행사할 권한이 없음) 상태인가.',
         conclusion:'PF 위반 때문에 원 결정은 무효 — JE는 "결정이 아닌 것"을 뜻한다. Tribunal의 권한은 소진되지 않았고 다시 행사할 수 있었다.',
         keywords:['결정이 아닌 것','재행사','무효','자기 시정'],
         facts:'인도 학생 비자 신청인의 사건을 Migration Review Tribunal이 청문 기회 없이 결정했다. Tribunal이 오류를 깨닫고 결정을 다시 했다. 장관 측은 결함이 있더라도 원 결정이 종국적이므로 다시 할 권한이 없다고 주장했다.'}},

  /* ─── 2026 Seminar Plan additions ───────────────────────── */
  ainsworth:{
    id:'ainsworth', name:'Ainsworth v Criminal Justice Commission', cite:'[1992] HCA 10; (1992) 175 CLR 564', icon:'⊜', color:'c-blue',
    topic:'W2', category:'Case',
    en:{ rule:'Certiorari is available only against an act or decision that has a discernible or apparent legal effect on rights, interests or legal status. A pure recommendation or report that does not, in itself, alter legal rights or status is not amenable to certiorari. Declaration, by contrast, is more flexible — it can issue to vindicate a PF breach in the making of a report, even where certiorari cannot.',
         principle:'Ainsworth draws the operative line for certiorari and reaffirms declaration as the workhorse remedy where legal effect is too attenuated for the prerogative writ. The case made clear that "decision" for remedial purposes is functional, not formal — what matters is whether something has been done that affects legal rights or status, not the label attached. The result also showed that PF can be breached in non-binding contexts (where the resulting damage is reputational or to interests short of strict legal rights), and declaration is the appropriate remedy in that scenario.',
         when:'Use Ainsworth at the remedies stage when the impugned act looks like a recommendation, report, or advisory output rather than a binding decision. It is the case that justifies seeking declaration even when certiorari is off the table.',
         howApply:[
           'Identify what was actually done and ask whether it has a discernible legal effect on rights, interests, or legal status.',
           'If yes (e.g. a licence cancellation, a finding triggering exclusion under statute), certiorari may issue.',
           'If no (e.g. a pure recommendation or advisory report), certiorari is not available — but declaration remains an option.',
           'Frame the declaration around the unlawful conduct (PF breach, exceeded power, etc.) rather than around the absent legal effect.',
           'Remember that declaration\'s flexibility makes it valuable where reputation or non-strict interests are damaged by an unlawful process.'
         ],
         issue:'Whether a Criminal Justice Commission report recommending Ainsworth\'s exclusion from the Queensland poker-machine industry — made without giving him a hearing — was amenable to certiorari, or whether declaration was the appropriate remedy.',
         conclusion:'Certiorari was not available because the report itself had no discernible legal effect on Ainsworth\'s rights. But declaration was available to vindicate the PF breach in the report\'s making.',
         keywords:['legal effect','certiorari','declaration','reports'],
         facts:'The Queensland Criminal Justice Commission produced a report recommending that Ainsworth be excluded from the Queensland poker-machine industry, without ever giving him an opportunity to be heard. He sought certiorari and, in the alternative, declaration.'},
    kr:{ rule:'Certiorari는 권리·이익·법적 지위에 식별 가능한 또는 외관상 법적 효과를 가지는 행위·결정에 대해서만 발할 수 있다. 그 자체로는 법적 권리·지위를 변경하지 않는 순수한 권고나 보고서는 certiorari의 대상이 아니다. 반면 Declaration은 더 유연해 — 보고서 작성 과정에서 PF가 위반된 경우 certiorari가 막혀도 그 위법성을 확인하기 위해 발부될 수 있다.',
         principle:'Ainsworth는 certiorari의 운영적 경계선을 긋고, 법적 효과가 약해 prerogative writ가 닿지 않는 자리에서 declaration이 주력 구제임을 다시 확인한 판결이다. 구제 목적의 "결정"은 라벨이 아니라 기능으로 본다는 점 — 권리·지위에 영향을 주는 무엇이 행해졌는지가 중요하다는 점 — 도 분명히 했다. PF가 비-구속적 맥락(평판이나 엄격한 법적 권리에 못 미치는 이익이 손상되는 자리)에서도 위반될 수 있으며, 그 자리에서 적절한 구제는 declaration이라는 결론도 함께 보여 준다.',
         when:'구제 단계에서, 다투려는 행위가 구속력 있는 결정이라기보다 권고·보고서·자문 산출물로 보일 때 인용한다. certiorari가 막힌 자리에서 declaration을 구하는 정당화의 근거.',
         howApply:[
           '실제 행해진 것이 무엇인지 식별하고, 그것이 권리·이익·법적 지위에 식별 가능한 법적 효과를 가지는지 묻는다.',
           '효과가 있다면(예: 면허 취소, 법령상 배제를 촉발하는 인정), certiorari가 가능하다.',
           '효과가 없다면(예: 순수한 권고나 자문 보고서), certiorari는 불가능 — 그러나 declaration은 여전히 가능.',
           'Declaration은 부재하는 법적 효과가 아니라 위법한 행위(PF 위반, 권한 초과 등) 자체를 중심으로 짠다.',
           'Declaration의 유연성은 평판이나 엄격하지 않은 이익이 위법 절차로 손상된 자리에서 특히 가치 있다는 점을 기억한다.'
         ],
         issue:'CJC가 청문 없이 Ainsworth의 퀸즐랜드 포커기 산업 배제를 권고한 보고서가 certiorari로 다툴 수 있는가, 아니면 declaration이 맞는 구제인가.',
         conclusion:'보고서 자체가 Ainsworth의 권리에 식별 가능한 법적 효과를 갖지 않으므로 certiorari는 불가. 다만 보고서 작성 과정의 PF 위반에 대해 declaration은 발부 가능.',
         keywords:['법적 효과','certiorari','declaration','보고서'],
         facts:'퀸즐랜드 형사사법위원회(CJC)가 Ainsworth에게 한 번도 청문 기회를 주지 않은 채, 그를 퀸즐랜드 포커기 산업에서 배제할 것을 권고하는 보고서를 냈다. 그는 certiorari를, 예비적으로 declaration을 구했다.'}},
  m68:{
    id:'m68', name:'Plaintiff M68/2015 v Minister for Immigration and Border Protection', cite:'[2016] HCA 1; (2016) 257 CLR 42', icon:'⌬', color:'c-violet',
    topic:'W2', category:'Case',
    en:{ rule:'The reach of s 75(v) of the Constitution — and of "officer of the Commonwealth" jurisdiction more generally — is functional, not formal. Ministers and their delegates remain amenable to constitutional writs even when the impugned conduct is carried out indirectly, through arrangements with a foreign State, statutory authorities, or private contractors. Outsourcing or offshoring does not strip the conduct of its character as Commonwealth executive action.',
         principle:'M68 is the modern affirmation that Commonwealth executive power cannot be insulated from JR by clever institutional arrangements. The court looked through the Australia–Nauru detention arrangements to identify Australian officers as the operative actors, anchoring the s 75(v) jurisdiction. The case matters across two contexts:\n(1) outsourced detention and offshore processing — Australia retains JR exposure for its own officers\n(2) the wider lesson for any Cth function delivered by a private or foreign intermediary — the substance of the action, not the legal form, controls amenability.',
         when:'Use M68 whenever a respondent argues that JR is unavailable because the conduct in question was technically performed by a foreign government, a private contractor, or some intermediary structure. It also helps when sketching the scope of s 75(v) generally.',
         howApply:[
           'Identify the impugned conduct and trace who actually directed, funded, controlled, or authorised it.',
           'If a Commonwealth officer or Minister was the operative actor in substance, s 75(v) reaches them — regardless of the formal contracting party.',
           'Resist arguments that outsourcing or offshore arrangements remove JR exposure — formal layers do not insulate the substance.',
           'Pair with Plaintiff S157 if a privative clause is in play — the constitutional jurisdiction cannot be ousted.',
           'On the merits, run the usual JE analysis (PF, considerations, reasonableness, etc.) against the Cth officer or Minister.'
         ],
         issue:'Whether the offshore detention of asylum seekers on Nauru, conducted under arrangements between Australia and Nauru and operated by a private contractor, was within Commonwealth executive power and amenable to constitutional review.',
         conclusion:'Yes — within the s 61 executive power; the conduct was attributable to Commonwealth officers and reviewable under s 75(v).',
         keywords:['s 75(v)','officer of Commonwealth','offshore','outsourcing'],
         facts:'A Bangladeshi woman held in offshore detention on Nauru under arrangements between the Australian and Nauruan governments — operated on the ground by a private contractor — challenged her detention as outside Commonwealth executive power.'},
    kr:{ rule:'헌법 s 75(v)의 — 그리고 더 일반적으로 "영연방 공무원" 관할의 — 범위는 형식이 아니라 기능으로 본다. 장관과 위임관은 다투어진 행위가 외국 정부·법정 기관·민간 계약자와의 협정을 통해 간접적으로 수행됐더라도 헌법적 영장의 대상이 된다. 외주화나 역외화가 그 행위의 영연방 행정작용으로서의 성격을 벗기지 못한다.',
         principle:'M68은 영연방 행정권이 영리한 제도적 배치로 JR에서 차단될 수 없다는 점을 현대적으로 다시 확인한 판결이다. 법원은 호주-나우루 구금 협정의 형식을 꿰뚫어 호주 공무원을 운영적 행위자로 식별했고, 그것으로 s 75(v) 관할을 정초했다. 두 맥락에서 의미가 크다:\n(1) 외주 구금·역외 처리 — 호주는 자국 공무원에 대한 JR 노출을 유지한다\n(2) 더 넓게는 민간·외국 매개체를 통해 수행되는 모든 영연방 기능에 대한 교훈 — 법적 형식이 아니라 행위의 실체가 적격성을 결정한다.',
         when:'피고 측이 "행위가 외국 정부, 민간 계약자, 매개 구조에 의해 형식적으로 수행되었으므로 JR이 불가능하다"고 다툴 때 인용한다. s 75(v)의 범위를 일반적으로 설명할 때도 유용.',
         howApply:[
           '다투어진 행위를 식별하고, 누가 실제로 지시·자금·통제·수권했는지를 추적한다.',
           '실체에서 영연방 공무원이나 장관이 운영적 행위자였다면 s 75(v)가 그들에게 미친다 — 형식적 계약 당사자와 무관하게.',
           '"외주화·역외 협정으로 JR 노출이 사라진다"는 주장에 저항한다 — 형식적 층위가 실체를 차단하지 못한다.',
           '배제조항이 등장하면 Plaintiff S157과 짝지어 — 헌법적 관할은 봉쇄될 수 없다.',
           '본안에서는 영연방 공무원·장관에 대해 통상의 JE 분석(PF, 고려사항, 비합리성 등)을 돌린다.'
         ],
         issue:'호주-나우루 정부 간 협정 아래에서, 현장에서는 민간 계약자에 의해 운영된 나우루 역외 구금이 영연방 행정권 안에 있고 헌법적 심사의 대상인가.',
         conclusion:'그렇다 — s 61 행정권 안. 그 행위는 영연방 공무원에게 귀속되고 s 75(v)로 심사 가능하다.',
         keywords:['s 75(v)','Cth 공무원','역외','외주화'],
         facts:'호주-나우루 정부 간 협정 아래 나우루에서 역외 구금된 — 현장에서는 민간 계약자가 운영하던 — 방글라데시 여성이 자신의 구금이 영연방 행정권 밖이라며 다툰 사건.'}},
  neat:{
    id:'neat', name:'NEAT Domestic Trading Pty Ltd v AWB Ltd', cite:'[2003] HCA 35; (2003) 216 CLR 277', icon:'⊠', color:'c-gray',
    topic:'W3', category:'Case',
    en:{ rule:'A private corporation that has been given a statutory veto over a public function is not, by that fact alone, transformed into a public body amenable to ADJR. The majority adopted a formal / structural approach — looking at what the body legally is (a private company with shareholders and commercial duties), not what it functionally does (gatekeeping a statutory scheme). Functional analysis (the UK Datafin approach) was rejected for ADJR purposes.',
         principle:'NEAT is the structural counterpoint to M61. M61 said "outsourcing the input does not insulate the output"; NEAT says "the entity exercising the veto is still a private body for ADJR purposes — it is not magically converted into a public actor by the statutory role". The result is that AWBI\'s consent decisions could not be challenged under ADJR. The case has been controversial — many commentators preferred the functional Datafin approach — but it remains the law in Australia for ADJR\'s "under an enactment" reach. After NEAT, Cth contractual-veto structures are largely outside ADJR; applicants pivot to s 75(v) (against Cth officers, where one can be identified) or to non-statutory review.',
         when:'Use NEAT defensively when arguing that ADJR does not reach a private body. For applicants, NEAT is the case to distinguish — show that the body is in substance a public actor, or pivot to s 75(v) against the responsible Cth officer.',
         howApply:[
           'Identify what the body legally is (private company, statutory authority, government department).',
           'Apply the formal/structural test — if it is a private corporation with commercial purposes and shareholders, NEAT pulls it outside ADJR even if it has statutory functions.',
           'Resist the functional Datafin argument as a matter of Australian doctrine — it is persuasive overseas but not the High Court\'s line.',
           'For applicants pinned by NEAT, pivot to s 75(v) / s 39B(1) against the Cth officer who can be identified as responsible (M68 logic), or to declaration in equity.',
           'Note the policy debate — NEAT is criticised as creating an accountability gap; future legislative reform may unwind it for specific schemes.'
         ],
         issue:'Whether AWB International\'s decision to refuse consent for non-AWB bulk wheat exports — a statutory precondition under the Wheat Marketing Act — was reviewable under ADJR.',
         conclusion:'No — AWBI was a private company; even though the Act made its consent a gateway, the corporation itself remained a private body and its consent decisions were not "under an enactment" for ADJR purposes.',
         keywords:['private body','statutory veto','formal approach','functional','Datafin'],
         facts:'AWB International (AWBI) was a private company whose consent was a statutory precondition under the Wheat Marketing Act 1989 (Cth) for any non-AWB exporter to ship bulk wheat. NEAT, a competitor, sought ADJR review when AWBI refused consent.'},
    kr:{ rule:'공공 기능에 대한 법령상 거부권을 부여받은 민간법인이라고 해서, 그 사실만으로 ADJR의 대상이 되는 공공체로 전환되지는 않는다. 다수의견은 형식·구조적 접근을 채택했다 — 법적으로 그것이 무엇인가(주주가 있고 상업적 의무를 지는 민간 회사)를 보고, 기능적으로 무엇을 하는가(법령 체계의 문지기 역할)는 보지 않는다. 기능적 분석(영국 Datafin 접근)은 ADJR 목적상 거부됐다.',
         principle:'NEAT은 M61의 구조적 반대편에 선다. M61이 "입력의 외주가 출력을 차단하지 않는다"였다면, NEAT은 "거부권을 행사하는 그 주체는 ADJR 목적상 여전히 민간체이지, 법령상 역할로 마법처럼 공공 행위자가 되지 않는다"이다. 그 결과 AWBI의 동의 결정은 ADJR로 다툴 수 없게 됐다. 많은 학자들이 기능적 Datafin 접근을 선호했지만, 호주에서는 ADJR의 "under an enactment" 도달 범위에 관한 한 NEAT이 여전히 법이다. NEAT 이후 영연방의 계약적 거부권 구조는 대체로 ADJR 밖이고, 신청인들은 s 75(v)(영연방 공무원을 짚어 낼 수 있는 경우)나 비-법정 심사로 갈아탄다.',
         when:'피고 측에서 ADJR이 민간체에 닿지 않는다고 방어할 때 NEAT을 쓴다. 신청인 측이라면 NEAT을 distinguishing해야 한다 — 그 주체가 실질에서는 공공 행위자임을 보이거나, 책임 있는 영연방 공무원을 향해 s 75(v)로 갈아탄다.',
         howApply:[
           '그 주체가 법적으로 무엇인지 식별한다(민간 회사, 법정 기관, 정부 부처).',
           '형식·구조적 테스트를 적용한다 — 상업적 목적과 주주를 가진 민간 회사라면, 법령상 기능이 있더라도 NEAT가 그것을 ADJR 밖으로 끌어낸다.',
           '호주 법리의 입장으로서 기능적 Datafin 주장에 저항한다 — 해외에서는 설득력이 있지만 High Court의 노선은 아니다.',
           'NEAT에 막힌 신청인은 책임 있는 영연방 공무원을 향해 s 75(v) / s 39B(1)로 갈아타거나(M68 논리), 형평법상 declaration으로 간다.',
           '정책 논쟁에 유의 — NEAT은 책임 공백을 만든다는 비판을 받으며, 특정 체계에서는 입법으로 풀릴 가능성이 있다.'
         ],
         issue:'Wheat Marketing Act 1989 (Cth) 아래 비-AWB 밀 수출에 법정 전제였던 AWBI의 동의 거부 결정이 ADJR로 심사 대상인가.',
         conclusion:'아니다 — AWBI는 민간 회사. 법이 그 동의를 게이트로 만들었더라도 그 법인 자체는 민간체로 남고, 그 동의 결정은 ADJR 목적상 "under an enactment"가 아니다.',
         keywords:['민간기관','법정 거부권','형식적 접근','기능적','Datafin'],
         facts:'AWB International(AWBI)은 민간 회사로, Wheat Marketing Act 1989 (Cth) 아래에서 비-AWB 수출자가 벌크 밀을 선적하려면 그 동의가 법정 전제였다. 경쟁사인 NEAT가 AWBI의 동의 거부에 대해 ADJR 심사를 구한 사건.'}},
  datafin:{
    id:'datafin', name:'R v Panel on Take-overs and Mergers; Ex parte Datafin Plc', cite:'[1986] EWCA Civ 8; [1987] QB 815', icon:'⌖', color:'c-teal',
    topic:'W3', category:'Case',
    en:{ rule:'(UK) A private body exercising essentially public-law functions in a regulated field can be amenable to judicial review — the test is functional (what does the body do?), not formal (what is the body legally?). The English approach extends JR to bodies that, but for the regulator\'s presence, government would itself perform.',
         principle:'Datafin is the leading UK authority for functional public-body JR. It was NOT followed by the Australian High Court majority in NEAT, which preferred the formal/structural approach. Datafin remains useful as comparative authority and as the doctrinal counterpoint to NEAT.',
         when:'Cite Datafin in comparative argument or where you are asking the court to extend JR to a private body exercising essentially public functions; expect resistance under NEAT but the argument has academic and policy traction.',
         howApply:[
           'Identify the body and characterise its function as essentially public (regulatory, gatekeeping, would otherwise be performed by government).',
           'Argue the functional approach — what the body does, not what it legally is, controls amenability.',
           'Acknowledge NEAT (the Australian formal/structural counterpoint) and either distinguish the body or invite the court to revisit.'
         ],
         issue:'Whether the (non-statutory) City of London Takeover Panel was amenable to judicial review of its rulings.',
         conclusion:'Yes — although the Panel was a private body in form, its function was public, and JR was available.',
         keywords:['functional approach','UK comparative','public function','Datafin'],
         facts:'Datafin challenged a Takeover Panel ruling in a contested takeover. The Panel was a non-statutory City of London body, but it effectively regulated UK takeovers in the absence of formal government regulation.'},
    kr:{ rule:'(영국) 규제 분야에서 본질적으로 공법적 기능을 행하는 민간 기관도 사법심사 대상이 될 수 있다 — 기준은 기능적(그 기관이 무엇을 하는가)이지 형식적(그 기관이 법적으로 무엇인가)이 아니다. 영국 접근은 그 규제기관이 없으면 정부가 직접 했을 기능에 JR을 확장한다.',
         principle:'Datafin은 기능적 공공체 JR의 영국 선도 판례다. 호주 High Court 다수(NEAT)는 따르지 않았고, 형식·구조적 접근을 선호했다. Datafin은 비교법 권위와 NEAT의 교리적 반대편으로서 여전히 유용하다.',
         when:'비교법 논의에서, 또는 본질적으로 공적 기능을 행하는 민간 기관에 JR을 확장하자고 법원에 청할 때 인용한다. NEAT 아래에서 저항이 예상되지만 학문·정책적 무게가 있는 주장.',
         howApply:[
           '그 기관을 식별하고 그 기능을 본질적으로 공적인 것(규제, 문지기, 정부가 했을 일)으로 성격 짓는다.',
           '기능적 접근을 주장한다 — 법적으로 무엇이 아니라 무엇을 하는가가 적격성을 결정한다.',
           'NEAT(호주의 형식·구조적 반대편)를 인정하고, 그 기관을 distinguishing하거나 법원에 재검토를 청한다.'
         ],
         issue:'(법령 근거 없는) City of London Takeover Panel의 결정이 사법심사 대상인가.',
         conclusion:'그렇다 — Panel은 형식상 민간체였지만 기능이 공적이어서 JR이 가능하다.',
         keywords:['기능적 접근','영국 비교법','공적 기능','Datafin'],
         facts:'Datafin이 적대적 인수에서 Takeover Panel의 결정을 다퉜다. Panel은 City of London의 비-법정 기관이었지만, 영국에서 정부의 정식 규제가 없는 가운데 사실상 인수합병을 규제했다.'}},
  fuller:{
    id:'fuller', name:'Fuller v Lawrence', cite:'[2024] HCA 45', icon:'⊡', color:'c-blue',
    topic:'W3', category:'Case',
    en:{ rule:'Recent High Court application of the Tang two-step "under an enactment" test confirms its continuing operation: statutory authorisation alone is not enough if the impugned decision does not have legal force on rights through statute. Both limbs must still be satisfied.',
         principle:'Fuller is the most current illustration that Tang remains the operative gateway test for ADJR. It does not unsettle Tang; it shows the test still applies in contemporary contexts.',
         when:'Cite Fuller as the most recent confirmation of Tang when running an ADJR-jurisdiction argument.',
         howApply:[
           'Apply Tang two-limb analysis as usual.',
           'Cite Fuller for the proposition that the High Court continues to apply Tang in 2024.',
           'If statutory authorisation exists but legal effect on rights flows from a non-statutory source, ADJR fails.'
         ],
         issue:'Whether the impugned decision satisfied both limbs of the Tang "under an enactment" test in the relevant statutory matrix.',
         conclusion:'The High Court applied Tang; outcome turned on whether the second limb (legal force on rights through statute) was satisfied on the particular statutory matrix.',
         keywords:['Tang','under enactment','recent','ADJR gateway'],
         facts:'Recent High Court application revisiting and applying the Tang criteria for ADJR jurisdiction.'},
    kr:{ rule:'High Court의 가장 최근 적용으로, Tang의 두 단계 "under an enactment" 테스트가 계속 운영됨을 확인한다 — 법령상 권한만으로는 부족하며, 다투어진 결정이 법령을 통해 권리에 법적 효력을 가져야 한다. 두 단계 모두 여전히 충족돼야 한다.',
         principle:'Fuller는 Tang이 ADJR의 운영적 관문 테스트로 남아 있음을 보여 주는 가장 최근의 사례다. Tang을 흔들지 않으며, 현대 맥락에서도 그 테스트가 여전히 적용된다는 점을 보여 준다.',
         when:'ADJR 관할 주장에서 Tang의 가장 최근 확인으로 인용한다.',
         howApply:[
           '평소처럼 Tang의 두 단계 분석을 적용한다.',
           '"High Court가 2024년에도 Tang을 계속 적용한다"는 명제로 Fuller를 인용한다.',
           '법령상 권한은 있지만 권리에 미치는 법적 효력이 비-법령 원천에서 나오면 ADJR은 막힌다.'
         ],
         issue:'다투어진 결정이 해당 법령 구조에서 Tang "under an enactment" 테스트의 두 단계를 모두 충족하는가.',
         conclusion:'High Court가 Tang을 적용했고, 결과는 그 특정 법령 구조에서 둘째 단계(법령을 통한 권리에 대한 법적 효력)가 충족됐는지에 달렸다.',
         keywords:['Tang','under enactment','최근','ADJR 관문'],
         facts:'Tang 기준을 재검토하고 적용한 High Court의 최근 사례.'}},
  m174:{
    id:'m174', name:'Plaintiff M174/2016 v Minister for Immigration and Border Protection', cite:'[2018] HCA 16; (2018) 264 CLR 217', icon:'∅', color:'c-violet',
    topic:'W4', category:'Case',
    en:{ rule:'Although a decision affected by jurisdictional error has no legal force (Bhardwaj nullity doctrine), it may continue to produce practical and factual effects on the ground until a court formally declares it invalid or quashes it. The Brian Lawlor doctrine recognises that the legal/practical gap is real — and explains why declaratory or certiorari relief is often still needed even where Bhardwaj logically renders the original decision void.',
         principle:'M174 reconciles the Bhardwaj nullity doctrine with the practical reality that administrative decisions, until quashed, drive real-world consequences. The doctrine justifies maintaining declaration and certiorari as live remedies even after Bhardwaj.',
         when:'Cite M174 to explain why a court declaration or certiorari is still useful even though Bhardwaj logically makes the original decision a nullity. Useful for the remedies stage of any JE answer.',
         howApply:[
           'Establish the JE on Hossain analysis.',
           'Acknowledge Bhardwaj — the decision is, in law, a nullity.',
           'Cite M174 — the legal nullity does not unwind the practical effects; certiorari and declaration remain needed to clear the air on the ground.'
         ],
         issue:'Whether a decision affected by jurisdictional error continues to produce practical effects pending a court ruling — and what that means for the choice of remedy.',
         conclusion:'A JE-affected decision has no legal force but practical effects persist; declaration and certiorari remain practically necessary remedies even after Bhardwaj.',
         keywords:['no decision','Brian Lawlor','practical effect','remedies need'],
         facts:'Migration decision challenged for JE; the Court analysed the practical consequences of the Bhardwaj nullity doctrine and the continuing need for declaratory and certiorari relief.'},
    kr:{ rule:'JE의 영향을 받은 결정은 법적 효력이 없지만(Bhardwaj 무효 법리), 법원이 정식으로 무효를 선언하거나 무효화하기 전까지는 현장에서 사실적·실무적 효과를 계속 일으킬 수 있다. Brian Lawlor 법리는 이 법적·실무적 간극이 실재함을 인정하며 — Bhardwaj가 논리적으로 원 결정을 무효로 만들더라도 declaration이나 certiorari가 여전히 필요한 이유를 설명한다.',
         principle:'M174는 Bhardwaj 무효 법리와 — 행정결정이 무효화되기 전까지 현실적 결과를 굴린다는 — 실무적 현실을 화해시킨다. Bhardwaj 이후에도 declaration과 certiorari를 살아 있는 구제로 유지할 정당화의 근거.',
         when:'Bhardwaj가 논리적으로 원 결정을 무효로 만들더라도 법원의 declaration이나 certiorari가 왜 여전히 유용한지 설명할 때 인용한다. 모든 JE 답안의 구제 단계에 유용.',
         howApply:[
           'Hossain 분석으로 JE를 입증한다.',
           'Bhardwaj를 인정한다 — 결정은 법적으로 무효.',
           'M174를 인용한다 — 법적 무효가 실무적 효과를 풀어내지 않는다. 현장의 공기를 정화하기 위해 certiorari와 declaration이 여전히 필요.'
         ],
         issue:'JE 영향 결정이 법원 판결 전까지 실무적 효과를 계속 일으키는가, 그리고 그것이 구제 선택에 어떤 의미를 갖는가.',
         conclusion:'JE 영향 결정은 법적 효력은 없지만 실무적 효과가 지속한다. Bhardwaj 이후에도 declaration과 certiorari가 실무적으로 필요한 구제로 남는다.',
         keywords:['결정 아님','Brian Lawlor','실무적 효과','구제 필요성'],
         facts:'이민 결정이 JE로 다투어진 사건. 법원이 Bhardwaj 무효 법리의 실무적 결과와, declaration·certiorari 구제의 지속적 필요성을 분석했다.'}},
  kioa:{
    id:'kioa', name:'Kioa v West', cite:'[1985] HCA 81; (1985) 159 CLR 550', icon:'☼', color:'c-blue',
    topic:'W5', category:'Case',
    en:{ rule:'Procedural fairness applies as a default common-law presumption to any administrative decision that affects an individual\'s rights, interests, or legitimate expectations. Mason J described its application as "fairly obvious" — the duty is implied into the empowering Act unless the statute clearly and unambiguously excludes it. The content of the duty has two limbs: the hearing rule (notice + opportunity to respond) and the bias rule.',
         principle:'Kioa flipped the default. Before Kioa, courts asked whether PF could be implied into a particular statute; after Kioa, courts ask whether it can be excluded. This made fair-hearing a structural condition implied into virtually every empowering Act in Australian administrative law. Saeed (2010) reinforced the threshold by holding that exclusion requires clear and unambiguous statutory language (legality principle); Lam (2003) modernised the analysis by reframing PF around "practical injustice" rather than "legitimate expectation"; WZARH and Nathanson connect Kioa to materiality.',
         when:'Use Kioa as the opening move in any PF analysis. It tells you the duty exists; the rest of the analysis is about content (what the duty required on these facts) and breach (whether it was discharged).',
         howApply:[
           'Identify the decision and ask whether it affects rights, interests, or legitimate expectations of an identifiable person — almost any individual administrative decision will satisfy this.',
           'Look for clear and unambiguous statutory exclusion of PF (Saeed). Silence or implication is not enough; the legality principle (Coco) demands express words.',
           'If PF applies, define the content the situation requires: notice of the case to be met, disclosure of credible and relevant adverse material (VEAL), a real opportunity to respond, and an unbiased decision-maker (Ebner).',
           'Identify the specific breach on the facts — was material withheld? Was the response window unreasonably short? Was there a hidden adverse view?',
           'Apply materiality (Hossain stage 3 / Nathanson) — but remember the bar is low in PF cases; a realistic possibility that submissions could have made a difference is enough.'
         ],
         issue:'Whether the deportation decision affecting a Tongan family required procedural fairness when it was based on adverse Departmental file material that had not been disclosed to them.',
         conclusion:'Yes — PF applied as a default duty implied into the empowering Act, and required disclosure of credible, relevant adverse material together with an opportunity to respond.',
         keywords:['default PF','rights/interests','disclosure','adverse material','Mason J'],
         facts:'A Tongan family in Australia faced deportation. The decision-maker relied on adverse material in the Departmental file that had never been put to the family for comment.'},
    kr:{ rule:'절차적 공정(PF)은 누군가의 권리·이익·정당한 기대에 영향을 주는 행정결정이라면 일단 적용된다고 본다. Mason J가 "꽤 분명한 일"이라고 한 그 말이 핵심 — PF 의무는 수권법 안에 묵시적으로 들어 있다고 보고, 법이 분명한 문언으로 빼내지 않는 한 살아 있다. 의무는 두 갈래다. 청문(고지 + 답변 기회)과 편향 금지.',
         principle:'Kioa는 PF 분석의 기본값을 뒤집은 판결이다. 그 전에는 "이 법에 PF를 묵시할 수 있나"를 물었다면, Kioa 뒤로는 "이 법이 PF를 배제했나"를 묻는다. 그 결과 공정한 청문은 호주 행정법에서 사실상 모든 수권법에 깔려 있는 구조적 조건이 됐다. 이후 Saeed(2010)가 "배제하려면 분명하고 모호하지 않은 말이 필요하다"고 못박았고(합법성 원칙), Lam(2003)이 분석 축을 "정당한 기대"에서 "실질적 부정의"로 옮겼으며, WZARH와 Nathanson이 Kioa를 중요성과 이어 붙였다.',
         when:'PF 사안에 들어갈 때 제일 먼저 꺼내는 카드. Kioa는 "의무가 일단 존재한다"는 출발점을 깔아 주고, 그다음 분석은 의무의 내용(이 사실에서 뭘 요구하는가)과 위반 여부에 집중한다.',
         howApply:[
           '문제된 결정이 누군가의 권리·이익·정당한 기대에 영향을 주는지 본다 — 개별 행정결정은 거의 다 이 문턱을 넘는다.',
           '법이 PF를 분명한 문언으로 배제했는지 확인한다(Saeed). 침묵이나 시사로는 안 된다 — 합법성 원칙(Coco)이 명시적 문언을 요구한다.',
           'PF가 적용되면 이 상황에서 뭘 요구하는지 구체화한다 — 다툴 쟁점의 고지, 불리한 자료의 공개(VEAL), 실질적인 답변 기회, 편향 없는 결정자(Ebner).',
           '사실에서 무엇이 어떻게 무너졌는지 짚는다 — 자료를 숨겼는지, 답변 시간이 너무 짧았는지, 드러나지 않은 불리한 견해가 있었는지.',
           '마지막에 중요성(Hossain 3단계 / Nathanson)을 댄다. 다만 PF 사안에서는 문턱이 낮다 — 의견 제출이 결과를 바꿨을 수 있다는 정도면 충분하다.'
         ],
         issue:'공개되지 않은 부처 내부 자료에 기댄 추방 결정에 절차적 공정 의무가 적용되는가.',
         conclusion:'적용된다. PF는 수권법에 묵시된 기본 의무이고, 신빙성 있고 관련된 불리한 자료라면 공개해서 답변 기회를 줘야 한다는 게 결론이다.',
         keywords:['기본 PF','권리·이익','공개','불리한 자료','Mason J'],
         facts:'호주에 살던 통가인 가족이 추방될 처지에 놓인 사건. 결정자는 그 가족에게 한 번도 보여 준 적 없는 부처 내부 불리 자료에 의존해 결정을 내렸다.'}},
  saeed:{
    id:'saeed', name:'Minister for Immigration and Citizenship v Saeed', cite:'[2010] HCA 23; (2010) 241 CLR 252', icon:'⊞', color:'c-coral',
    topic:'W5', category:'Case',
    en:{ rule:'The common-law duty of procedural fairness implied into administrative power can only be excluded by clear and unambiguous statutory language. A statutory code purporting to "cover the field" of PF will not displace the common-law duty unless its words plainly say so. This is an application of the principle of legality (Coco) to PF: fundamental rights/protections require express words to be cut down.',
         principle:'Saeed sealed the gap that Kioa opened. Kioa flipped the default to PF-applies-unless-excluded; Saeed defined what "exclusion" looks like — clear, unambiguous statutory language, not silence, implication, or "covering the field" by the back door. The two cases together produce the operative rule: PF is implied into virtually every empowering Act, and stays implied unless Parliament has used express words. The case also matters for the reach of statutory codes: even a detailed code does not silently exclude common-law content unless its language unmistakably does so.',
         when:'Use Saeed whenever the respondent argues that a statutory code or detailed procedural scheme excludes the common-law PF duty. It is the answer to "the Act covers the field" arguments.',
         howApply:[
           'Identify the statutory code or scheme said to exclude PF.',
           'Read its words carefully — does it use clear and unambiguous language to exclude common-law PF, or merely set out additional procedural requirements?',
           'Apply the legality principle (Coco): fundamental rights/protections (including PF) cannot be cut down by silence or implication.',
           'If the code does not exclude PF, common-law PF applies on top of (or alongside) the code.',
           'If the code does plainly exclude PF for some category of decision but not others, the common-law duty applies wherever the express exclusion does not reach (the actual Saeed result for offshore applicants).'
         ],
         issue:'Whether the procedural code in the Migration Act excluded the common-law duty of procedural fairness for an offshore visa applicant.',
         conclusion:'No — the code\'s express language addressed onshore applicants and did not, in clear and unambiguous terms, exclude the common-law PF duty for offshore applicants. Common-law PF therefore applied.',
         keywords:['statutory exclusion','clear words','code','principle of legality'],
         facts:'A Pakistani offshore visa applicant\'s application was refused on the basis of an adverse fraud finding that had not been disclosed to her. The Minister argued that the Migration Act\'s detailed code excluded any common-law PF duty.'},
    kr:{ rule:'행정 권한에 묵시되는 보통법상 절차적 공정 의무는 명시적이고 모호하지 않은 법령으로만 배제할 수 있다. PF "전분야"를 규율한다고 하는 법전(code)도 분명한 문언으로 그렇게 말하지 않으면 보통법 PF를 배제하지 못한다. 이는 합법성 원칙(Coco)을 PF에 적용한 결과 — 기본권·기본 보호는 명시적 문언으로만 좁혀질 수 있다.',
         principle:'Saeed는 Kioa가 열어 둔 자리를 봉했다. Kioa가 기본값을 "PF 적용 — 명시 배제 없는 한"으로 뒤집었다면, Saeed는 그 "배제"가 어떤 모습이어야 하는지 정의했다 — 분명하고 모호하지 않은 법령 문언이지, 침묵·시사·"전분야 규율"의 우회로가 아니다. 두 판결을 합치면 운영 규칙이 나온다: PF는 거의 모든 수권법에 묵시되며, 의회가 명시 문언으로 배제하지 않는 한 묵시된 채로 남는다. 자세한 법전(code)이라도 명시 문언이 없으면 보통법 내용을 조용히 배제하지 못한다는 점도 이 판결의 의미다.',
         when:'피고 측이 법전이나 상세한 절차 체계가 보통법 PF를 배제한다고 다툴 때 인용한다. "법령이 전분야를 규율한다"는 주장에 대한 답이다.',
         howApply:[
           'PF를 배제한다고 하는 법전·체계를 식별한다.',
           '그 문언을 면밀히 읽는다 — 보통법 PF를 배제하는 분명하고 모호하지 않은 문언인가, 아니면 추가 절차 요건을 두는 것뿐인가.',
           '합법성 원칙(Coco)을 적용한다 — 기본권·기본 보호(PF 포함)는 침묵이나 시사로 좁혀지지 않는다.',
           '법전이 PF를 배제하지 않는다면, 보통법 PF가 법전 위에서(또는 함께) 적용된다.',
           '법전이 일부 범주의 결정에는 PF를 명시 배제하지만 다른 범주에는 침묵한다면, 명시 배제가 미치지 않는 곳에서는 보통법 PF가 적용된다(Saeed의 실제 결론 — 역외 신청자).'
         ],
         issue:'Migration Act의 절차 법전이 역외 비자 신청자에 대한 보통법상 PF 의무를 배제하는가.',
         conclusion:'아니다 — 법전의 명시 문언은 국내 신청자를 다뤘을 뿐, 역외 신청자에 대한 보통법 PF를 분명하고 모호하지 않게 배제하지 않았다. 보통법 PF가 적용된다.',
         keywords:['법령 배제','명시적 문언','법전','합법성 원칙'],
         facts:'파키스탄 출신 역외 비자 신청자의 신청이, 그녀에게 공개되지 않은 사기 인정에 근거해 거부됐다. 장관 측은 Migration Act의 상세한 법전이 보통법 PF 의무를 배제했다고 다퉜다.'}},
  s10:{
    id:'s10', name:'Plaintiff S10/2011 v Minister for Immigration and Citizenship', cite:'[2012] HCA 31; (2012) 246 CLR 636', icon:'⌭', color:'c-ochre',
    topic:'W5', category:'Case',
    en:{ rule:'The duty of procedural fairness is not a free-standing common-law obligation imposed on government from outside the statute. It flows from statutory implication — the empowering Act is read as impliedly requiring fair procedure unless its text and structure exclude it. The plurality (Gummow, Hayne, Crennan, Bell JJ) endorsed Brennan J\'s approach in Quin: PF lives inside the statute, not above it. The text and structure of certain non-compellable Ministerial powers (Migration Act ss 48B / 417) — discretions personal to the Minister, not subject to obligation to consider — can implicitly exclude PF.',
         principle:'S10 settled the doctrinal source of PF. Earlier formulations sometimes spoke of PF as a common-law duty applied to government from outside; S10 reframed it as an implication drawn from statutory construction. Two practical consequences:\n(1) the question is always "what does this Act, on its true construction, require?", not "what does the common law impose?"\n(2) PF can be excluded by the text and structure of the Act even short of the express words Saeed normally requires — non-compellable, deeply discretionary powers can carry implicit exclusion in their structure. Read S10 alongside Kioa (default presumption) and Saeed (clear words to exclude); together they map the modern source-of-PF doctrine.',
         when:'Use S10 when arguing about the source or scope of PF — particularly when the power is one Parliament has drawn as a non-compellable, personal Ministerial discretion. Also use it to anchor the framing that PF is statutory in origin, not external.',
         howApply:[
           'Frame the inquiry as one of statutory construction — "what does this empowering Act, on its proper construction, require?" — not as a common-law overlay.',
           'Identify the specific power and read its text and structure. Is it framed as a non-compellable, personal Ministerial discretion (Migration Act ss 48B / 417 model)?',
           'If yes, the structure may implicitly exclude PF — even without the express words Saeed normally requires.',
           'If the power is ordinary (compellable, with statutory criteria), apply Kioa\'s default presumption — PF is impliedly required unless clearly excluded.',
           'Resist common-law-overlay framings ("the common law imposes…"); always anchor in the statute.'
         ],
         issue:'Whether the non-compellable Ministerial intervention powers in ss 48B and 417 of the Migration Act attracted procedural fairness obligations.',
         conclusion:'No — the text and structure of those non-compellable powers excluded the PF duty. The powers were not subject to any obligation to consider, let alone to give a hearing.',
         keywords:['statutory implication','source of PF','Quin','non-compellable'],
         facts:'Asylum seekers asked the Minister to exercise the personal, non-compellable powers in ss 48B and 417 of the Migration Act 1958 (Cth) — powers to intervene in the public interest. They argued they were entitled to PF in the consideration of those requests.'},
    kr:{ rule:'절차적 공정 의무는 법령 밖에서 정부에 부과되는 독립된 보통법상 의무가 아니다. 그것은 법령상 묵시에서 나온다 — 수권법은 그 문언과 구조가 배제하지 않는 한 공정 절차를 묵시적으로 요구하는 것으로 읽힌다. 다수의견(Gummow, Hayne, Crennan, Bell JJ)은 Quin에서 Brennan J가 취한 접근을 채택했다 — PF는 법령 안에 살지, 그 위에 있지 않다. 일부 강제불가(non-compellable) 장관 권한(Migration Act ss 48B / 417) — 장관 개인의 재량으로, 검토 의무조차 없는 권한 — 은 그 문언과 구조가 PF를 묵시적으로 배제할 수 있다.',
         principle:'S10은 PF의 교리적 원천을 정리했다. 과거에는 PF를 정부에 외부에서 부과되는 보통법상 의무로 말하기도 했지만, S10은 그것을 법령 해석에서 끌어낸 묵시로 다시 짰다. 실무적 결과 두 가지:\n(1) 질문은 항상 "이 법령은 올바르게 해석하면 무엇을 요구하는가"이지 "보통법이 무엇을 부과하는가"가 아니다\n(2) PF는 Saeed가 통상 요구하는 명시 문언이 없어도 법령의 문언과 구조에 의해 배제될 수 있다 — 강제불가·고도 재량적 권한은 그 구조 자체에 묵시적 배제를 담고 있을 수 있다. Kioa(기본 추정)와 Saeed(배제하려면 명시 문언)와 나란히 읽으면 현대 PF 원천 교리의 지도가 완성된다.',
         when:'PF의 원천이나 범위를 다툴 때 — 특히 의회가 강제불가·개인적 장관 재량으로 짠 권한의 경우 — 인용한다. PF가 외부적 보통법이 아니라 법령에서 비롯된다는 framing을 정초할 때도 쓴다.',
         howApply:[
           '질문을 법령 해석으로 짠다 — "이 수권법은 올바르게 해석하면 무엇을 요구하는가" — 보통법 덧씌우기로 짜지 않는다.',
           '문제된 권한을 식별하고 문언과 구조를 읽는다. 강제불가·개인적 장관 재량으로 짜여 있는가(Migration Act ss 48B / 417 모델)?',
           '그렇다면 그 구조가 PF를 묵시적으로 배제할 수 있다 — Saeed가 통상 요구하는 명시 문언 없이도.',
           '권한이 일상적(강제 가능, 법령상 기준 있음)이라면 Kioa의 기본 추정을 적용한다 — 명시 배제 없는 한 PF가 묵시 요구된다.',
           '"보통법이 부과한다…" 같은 덧씌우기 framing에 저항하고 항상 법령에 닻을 내린다.'
         ],
         issue:'Migration Act ss 48B와 417의 강제불가 장관 개입 권한이 절차적 공정 의무를 동반하는가.',
         conclusion:'아니다 — 그 강제불가 권한들의 문언과 구조가 PF 의무를 배제했다. 검토 의무조차 없는 권한이라, 청문 의무는 더더욱 없다.',
         keywords:['법령상 묵시','PF 원천','Quin','강제불가'],
         facts:'망명 신청자들이 장관에게 Migration Act 1958 (Cth) ss 48B와 417의 개인적·강제불가 권한 — 공익적 개입 권한 — 의 행사를 요청했다. 그들은 그 요청 검토에 PF가 적용된다고 주장했다.'}},
  veal:{
    id:'veal', name:'VEAL v Minister for Immigration and Multicultural and Indigenous Affairs', cite:'[2005] HCA 72; (2005) 225 CLR 88', icon:'✉', color:'c-coral',
    topic:'W5', category:'Case',
    en:{ rule:'When a decision-maker has adverse information that is credible, relevant and significant to the decision, the substance of that information must be disclosed to the affected person so they can respond — even if the source is confidential. The hearing-rule duty attaches to the substance of the material, not its provenance. Source-protection (e.g. an anonymous informant) can be respected by withholding identity, but the gist of the allegation must be put.',
         principle:'VEAL is the leading authority on PF\'s disclosure duty when adverse material is confidential. It draws a precise line: the duty is content-based (the substance of credible, relevant, significant adverse material must be disclosed) but identity-blind (the source can stay anonymous if there is good reason). The case operationalises Kioa\'s general PF duty and connects to LPDT/Nathanson on materiality — failure to disclose adverse substance is one of the classic PF breaches that easily clears the materiality bar.',
         when:'Use VEAL whenever a decision-maker relies on adverse material that the applicant has not been shown — particularly anonymous tip-offs, internal departmental notes, third-party allegations, or information held in confidence. It is the answer to "but the source was confidential" objections.',
         howApply:[
           'Identify the adverse material the decision-maker relied on — what was it, where did it come from, and what does it say?',
           'Apply the three-part filter: is it (i) credible (worthy of consideration), (ii) relevant (bears on the decision), and (iii) significant (could affect the outcome)?',
           'If yes to all three, the substance must be disclosed — even if the source is anonymous or confidential.',
           'Frame the disclosure to preserve any legitimate source-protection (e.g. "we have received information that you committed an offence in country X") without identifying the informant.',
           'On materiality, run Nathanson — the bar is low in PF cases; failure to disclose the substance of credible adverse material almost always clears it.'
         ],
         issue:'Whether the Department was required to disclose to the applicant the substance of an anonymous letter alleging he had committed murder in Eritrea, before relying on it in a refugee-status decision.',
         conclusion:'Yes — the substance had to be disclosed because it was credible, relevant and significant. The author\'s identity could be protected, but the gist of the allegation had to be put for response.',
         keywords:['confidential information','substance','credible relevant significant','VEAL filter'],
         facts:'The Department received an anonymous letter alleging that VEAL, an Eritrean refugee applicant, had committed a murder in Eritrea. The Department considered the letter when refusing his visa, but never put its contents to him for response.'},
    kr:{ rule:'결정자가 신빙성·관련성·중요성을 갖춘 불리한 정보를 가지고 있다면, 그 정보의 실질적 내용은 영향을 받는 사람에게 공개해서 답변 기회를 줘야 한다 — 그 출처가 기밀이라도. 청문 규칙의 의무는 자료의 실질에 붙지 출처에 붙지 않는다. 출처 보호(예: 익명 제보자)는 신원을 보류함으로써 존중할 수 있지만, 주장의 골자는 반드시 제시해야 한다.',
         principle:'VEAL은 불리한 자료가 기밀일 때 PF의 공개 의무에 관한 선도 판례다. 정확한 선을 긋는다 — 의무는 내용 기반(신빙성·관련성·중요성을 갖춘 불리한 자료의 실질은 공개)이지만 신원 무관(정당한 사유가 있으면 출처는 익명 유지 가능). Kioa의 일반 PF 의무를 운영적으로 구체화하고, materiality에서 LPDT·Nathanson과 연결된다 — 불리한 실질의 미공개는 materiality 문턱을 쉽게 넘는 전형적 PF 위반이다.',
         when:'결정자가 신청인에게 보여 주지 않은 불리한 자료에 의존했을 때 — 특히 익명 제보, 내부 부처 메모, 제3자 주장, 기밀로 보유된 정보 — 인용한다. "출처가 기밀이었다"는 항변에 대한 답이다.',
         howApply:[
           '결정자가 의존한 불리한 자료를 식별한다 — 그것이 무엇이고, 어디에서 왔으며, 무슨 내용인가.',
           '세 가지 필터를 적용한다: (i) 신빙성(검토할 만한가), (ii) 관련성(결정에 닿는가), (iii) 중요성(결과에 영향을 줄 수 있는가).',
           '셋 다 충족되면 실질은 공개해야 한다 — 출처가 익명·기밀이라도.',
           '공개의 형식은 정당한 출처 보호를 유지하면서 짠다(예: "당신이 X국에서 범죄를 저질렀다는 정보를 받았다") — 제보자 신원은 밝히지 않는다.',
           'Materiality는 Nathanson으로 — PF 사안에서는 문턱이 낮아, 신빙성 있는 불리한 실질의 미공개는 거의 항상 충족된다.'
         ],
         issue:'에리트레아 출신 난민 신청자에 대한 결정에 의존하기 전에, 부처가 그가 에리트레아에서 살인을 저질렀다고 주장하는 익명 편지의 실질을 그에게 공개해야 했는가.',
         conclusion:'그렇다 — 신빙성·관련성·중요성을 갖췄으므로 실질은 공개해야 했다. 작성자 신원은 보호할 수 있지만, 주장의 골자는 답변을 위해 제시되어야 했다.',
         keywords:['기밀 정보','실질','신빙성·관련성·중요성','VEAL 필터'],
         facts:'부처가 에리트레아 난민 신청자 VEAL이 에리트레아에서 살인을 저질렀다고 주장하는 익명 편지를 받았다. 부처는 비자 거부 시 그 편지를 고려했지만, 그 내용을 그에게 답변용으로 한 번도 제시하지 않았다.'}},
  nathanson:{
    id:'nathanson', name:'Nathanson v Minister for Home Affairs', cite:'[2022] HCA 26; (2022) 276 CLR 80', icon:'☉', color:'c-blue',
    topic:'W5', category:'Case',
    en:{ rule:'In a procedural-fairness context, the materiality threshold is low. The applicant still bears the formal onus on the balance of probabilities (MZAPC), but the court is "readily inclined" to infer that, had the PF duty been observed, the applicant could have put further submissions or evidence that might have made a difference. The realistic possibility of a different outcome is therefore far easier to establish in PF cases than in factual or reasoning-error cases.',
         principle:'Nathanson is the materiality companion to Kioa/Saeed. Hossain made materiality a default ingredient of JE; MZAPC put the formal onus on the applicant; Nathanson then specifically calibrated how that onus runs in PF cases — gently. The reason is structural: the very nature of a PF breach is that the applicant did not get to make their case, so the court cannot demand a high level of proof about what would have been said. LPDT (2024) builds on Nathanson by reinforcing that the inferential approach (no reconstruction) is the right way to reason about materiality.',
         when:'Cite Nathanson whenever PF has been breached and the respondent argues "the decision would have been the same anyway". It is the case that lowers the materiality bar in PF context.',
         howApply:[
           'Establish the PF breach first — typically failure to disclose adverse material (VEAL), denial of opportunity to respond, refusal of adjournment when one was clearly warranted (Li-style facts).',
           'Move to materiality and apply the Nathanson calibration — the bar is low.',
           'Reason inferentially from the record about what submissions or evidence the applicant could have put if PF had been observed.',
           'Frame the test consistent with LPDT — no reconstruction of what the decision-maker "would have" decided; only whether a different decision was realistically possible.',
           'Onus stays on the applicant (MZAPC), but the gentle inferential approach typically discharges it in PF context.'
         ],
         issue:'Whether the AAT\'s failure to give the applicant a fair opportunity to respond to character allegations introduced late in the s 501 cancellation hearing was material to the decision.',
         conclusion:'Yes — material. The decision was quashed. The Court emphasised that in PF context the threshold for inferring a realistic possibility of a different outcome is low.',
         keywords:['PF + materiality','realistic possibility','low threshold','readily inclined'],
         facts:'In an AAT review of a s 501 visa cancellation, new character allegations were introduced late in the hearing and the AAT refused an adjournment. The applicant did not have a fair opportunity to respond before the decision was made.'},
    kr:{ rule:'절차적 공정(PF) 맥락에서 materiality의 문턱은 낮다. 형식적 입증책임은 여전히 원고가 개연성의 우월로 진다(MZAPC)지만, 법원은 PF가 지켜졌더라면 신청인이 추가 의견·증거를 제출해 결과를 바꿀 수 있었음을 "쉽게 추론"하는 경향이 있다. 따라서 다른 결과의 현실적 가능성은 사실인정 오류나 추론 오류 사안보다 PF 사안에서 훨씬 쉽게 입증된다.',
         principle:'Nathanson은 Kioa·Saeed의 materiality 짝패다. Hossain이 materiality를 JE의 기본 요소로 만들었고, MZAPC가 형식적 입증책임을 원고에게 두었다면, Nathanson은 그 입증책임이 PF 사안에서 어떻게 작동하는지 — 부드럽게 — 구체적으로 보정했다. 구조적 이유가 있다: PF 위반의 본질이 신청인이 자기 입장을 제대로 말할 기회를 못 얻은 것이기 때문에, "그 자리에서 무슨 말을 했을 것인가"에 대해 법원이 높은 입증을 요구할 수 없다. LPDT(2024)는 추론적 접근(재구성 금지)이 materiality를 다루는 옳은 방식임을 확인하면서 Nathanson을 더 굳혔다.',
         when:'PF 위반이 있었고, 피고 측이 "결정은 어쨌든 같았을 것"이라고 다툴 때 인용한다. PF 맥락에서 materiality 문턱을 낮추는 핵심 판결이다.',
         howApply:[
           '먼저 PF 위반을 입증한다 — 보통 불리한 자료의 미공개(VEAL), 답변 기회 박탈, 연기가 명백히 필요했는데도 거부된 상황(Li 패턴) 등.',
           'Materiality로 넘어가 Nathanson 보정을 적용한다 — 문턱은 낮다.',
           'PF가 지켜졌더라면 신청인이 어떤 의견·증거를 낼 수 있었을지 기록에서 추론으로 따진다.',
           'LPDT의 틀을 유지한다 — 결정자가 "어떻게 결정했을 것인가"를 재구성하지 않고, 다른 결정이 현실적으로 가능했는지만 묻는다.',
           '입증책임은 원고에게 있지만(MZAPC), 부드러운 추론적 접근으로 PF 맥락에서는 보통 충족된다.'
         ],
         issue:'AAT가 s 501 비자 취소 심리 막바지에 새 인격 사유를 도입하고 연기를 거부함으로써 신청인에게 답변 기회를 주지 않은 것이 결정에 중요한가.',
         conclusion:'그렇다 — material하다. 결정은 취소됐다. 법원은 PF 맥락에서는 다른 결과의 현실적 가능성을 추론하는 문턱이 낮다는 점을 강조했다.',
         keywords:['PF + materiality','현실적 가능성','낮은 문턱','쉽게 추론'],
         facts:'AAT의 s 501 비자 취소 재심사에서, 새로운 인격 사유가 심리 막바지에 도입됐고 AAT가 연기를 거부했다. 결정 전에 신청인이 답변할 공정한 기회를 갖지 못했다.'}},
  jia:{
    id:'jia', name:'Minister for Immigration and Multicultural Affairs v Jia Legeng', cite:'[2001] HCA 17; (2001) 205 CLR 507', icon:'◑', color:'c-gray',
    topic:'W6', category:'Case',
    en:{ rule:'The standard for apprehended bias is calibrated to the office. A Minister exercising a politically charged statutory power is not held to the strict judicial standard. Pre-formed views that are consistent with announced policy or with the Minister\'s political role do not, by themselves, show prejudgment — provided the Minister keeps an open mind to the particular case and to the representations made on it.',
         principle:'Jia recognised that bias doctrine must accommodate institutional context. Judges are expected to approach each case as a tabula rasa; Ministers, by contrast, are political actors with publicly stated views, and the empowering Act often contemplates that. The fair-minded informed observer of Ebner is taken to know this. The doctrine is not soft on Ministers — actual prejudgment of the particular case (a "closed mind") still disqualifies — but generic policy alignment or robust public rhetoric is not enough. Read alongside Ebner (general bias test) and Hot Holdings (adviser bias).',
         when:'Use Jia whenever the impugned decision-maker is a Minister or other political actor and the alleged bias rests on prior public statements, policy positions, or political role. It is the reason why the same statement that would disqualify a judge will often not disqualify a Minister.',
         howApply:[
           'Identify the office of the decision-maker — judicial, quasi-judicial, administrative, or political.',
           'Calibrate the bias standard accordingly — Jia softens it for Ministers and political actors.',
           'Distinguish generic policy alignment / public rhetoric (not enough) from prejudgment of the particular case (still disqualifying).',
           'The fair-minded observer is taken to know the institutional context — they expect a Minister to have policy views; what they do not expect is a closed mind on this case.',
           'If the Minister demonstrably engaged with the representations on the merits, Jia favours no bias even after strong public statements.'
         ],
         issue:'Whether Minister Ruddock\'s strong public statements about character and visa cancellation, made before he decided to cancel Jia\'s visa under s 501, demonstrated apprehended bias.',
         conclusion:'No — the statements reflected policy and the Minister\'s political role, not prejudgment of Jia\'s individual case. The Minister had engaged with the representations made for Jia.',
         keywords:['Ministerial bias','open mind','political role','calibrated standard'],
         facts:'Minister Ruddock made strong public statements about character grounds and visa cancellation before personally cancelling Jia\'s visa under s 501. Jia argued that the public statements showed apprehended bias.'},
    kr:{ rule:'추정 편향(apprehended bias)의 기준은 그 직위에 맞춰 보정된다. 정치적으로 민감한 법령 권한을 행사하는 장관은 엄격한 사법 기준에 묶이지 않는다. 발표된 정책이나 장관의 정치적 역할에 부합하는 사전 견해는 그 자체만으로는 prejudgment를 보여 주지 않는다 — 다만 장관이 그 개별 사건과 그에 대한 의견에 열린 마음을 유지해야 한다.',
         principle:'Jia는 편향 법리가 제도적 맥락을 수용해야 한다는 점을 인정한 판결이다. 판사는 각 사건을 백지에서 출발하도록 기대되지만, 장관은 공개된 견해를 가진 정치적 행위자이며 수권법도 종종 그것을 전제한다. Ebner의 공정한 마음의 사정에 밝은 관찰자는 이를 알고 있다고 본다. 다만 이 법리가 장관에게 무른 것은 아니다 — 그 개별 사건에 대한 실제 prejudgment("닫힌 마음")는 여전히 자격 박탈 사유다. Ebner(일반 편향 기준), Hot Holdings(자문자 편향)와 나란히 읽는다.',
         when:'다투어진 결정자가 장관이나 정치적 행위자이고, 주장된 편향이 사전 공개 발언, 정책 입장, 정치적 역할에 기반할 때 인용한다. 판사라면 자격 박탈이 됐을 발언이 장관에서는 그렇지 않은 이유다.',
         howApply:[
           '결정자의 직위를 식별한다 — 사법, 준사법, 행정, 정치.',
           '편향 기준을 그에 맞춰 보정한다 — 장관·정치적 행위자에게는 Jia가 기준을 완화한다.',
           '일반적 정책 부합·공개 발언(부족)과 그 개별 사건에 대한 prejudgment(여전히 자격 박탈)를 구분한다.',
           '공정한 관찰자는 제도적 맥락을 안다고 본다 — 장관이 정책 견해를 가진 것은 당연히 예상되며, 예상되지 않는 것은 이 사건에 대한 닫힌 마음이다.',
           '장관이 본안에서 신청인의 의견과 실제로 마주했음이 입증되면, 강한 공개 발언이 있었어도 Jia는 편향 부정 쪽으로 기운다.'
         ],
         issue:'Ruddock 장관이 Jia의 비자를 s 501에 따라 취소하기 전에 한 강한 공개 발언이 추정 편향을 보이는가.',
         conclusion:'아니다 — 그 발언들은 정책과 장관의 정치적 역할을 반영한 것이지, Jia의 개별 사건에 대한 prejudgment는 아니다. 장관은 Jia 측 의견과 실제로 마주했다.',
         keywords:['장관 bias','열린 마음','정치적 역할','보정된 기준'],
         facts:'Ruddock 장관이 인격 사유와 비자 취소에 관해 강한 공개 발언을 한 뒤, 직접 Jia의 비자를 s 501에 따라 취소했다. Jia는 그 발언이 추정 편향을 보인다고 주장했다.'}},
  isbester:{
    id:'isbester', name:'Isbester v Knox City Council', cite:'[2015] HCA 20; (2015) 255 CLR 135', icon:'⊘', color:'c-violet',
    topic:'W6', category:'Case',
    en:{ rule:'A person who has played an active investigative or prosecutorial role in earlier related proceedings cannot also sit as a member of the panel deciding consequential administrative action against the same individual — that arrangement gives rise to apprehended bias as a matter of structure, regardless of the actual integrity of the person involved. The Hot Holdings tolerance for adviser involvement does not extend this far.',
         principle:'Isbester drew a structural line in apprehended-bias doctrine. Some role overlaps are categorically problematic — the prosecutor cannot become the decider on the same matter, even at a different stage. The fair-minded observer would reasonably apprehend that the person who built the case against you cannot then weigh whether the consequence should follow without prejudgment. The case sits beside Hot Holdings (adviser bias generally requires significance and proximity) and Ebner (the underlying double-step test) — Isbester is the structural-overlap case.',
         when:'Use Isbester whenever the same person, or someone closely identified with them, has acted on both the investigation/prosecution side and the decision side of a related matter. Typical contexts: regulators where staff investigate then sit on disciplinary panels; council officers who prosecute then sit on consequential decision panels; tribunal members who took an active prosecutorial role earlier.',
         howApply:[
           'Map the procedural sequence — who did what, at which stage, in what role?',
           'Identify any active investigatory or prosecutorial role in the earlier proceedings.',
           'Ask whether the same person (or someone closely identified) is now sitting on the panel deciding the consequential action.',
           'If yes, apprehended bias is structurally made out under Isbester — distinguishing facts in Hot Holdings (mere advisory role, independent decision-maker) does not save it.',
           'Bias is always-JE (no materiality limb) — the remedy will usually be certiorari plus rehearing before a differently-constituted panel.'
         ],
         issue:'Whether a Knox Council officer who had actively prosecuted a dog-attack offence against Ms Isbester could also sit as a member of the panel that subsequently decided whether to destroy her dog.',
         conclusion:'No — the structural overlap of prosecutor and decider on the same matter gave rise to apprehended bias. The decision was set aside.',
         keywords:['prior involvement','panel','prosecutor-decider','structural overlap'],
         facts:'A Knox Council officer prosecuted Ms Isbester under animal-management legislation arising from a dog attack. The same officer then sat as a member of the Council panel that subsequently decided to order the destruction of her dog.'},
    kr:{ rule:'사전 관련 절차에서 적극적인 조사·소추 역할을 했던 사람은, 같은 개인에 대한 후속 행정 결정 패널의 구성원으로도 앉을 수 없다 — 그 배치 자체가 그 개인의 실제 청렴성과 무관하게 구조적으로 추정 편향을 일으킨다. Hot Holdings가 인정한 자문자 관여의 허용 범위는 여기까지는 미치지 않는다.',
         principle:'Isbester는 추정 편향 법리에서 구조적 선을 그었다. 어떤 역할 중첩은 범주적으로 문제다 — 같은 사안에서, 단계만 다를 뿐, 소추자가 결정자가 될 수 없다. 공정한 마음의 관찰자라면 당신을 상대로 사건을 구축한 사람이 이제 그 결과가 따라야 할지를 prejudgment 없이 가늠할 수 있다고 보지 않는다. 이 판례는 Hot Holdings(자문자 편향은 일반적으로 의미 있는 역할과 근접성을 요함), Ebner(기저의 2단계 기준)와 함께 자리하는데, Isbester는 구조적 중첩 사건이다.',
         when:'같은 사람(또는 그와 긴밀히 동일시되는 자)이 관련 사안의 조사·소추 측과 결정 측에서 모두 활동했을 때 인용한다. 전형적 맥락: 규제기관에서 직원이 조사 후 징계 패널에 앉는 경우; 지자체 공무원이 소추 후 후속 결정 패널에 앉는 경우; tribunal 위원이 이전에 적극적 소추 역할을 했던 경우.',
         howApply:[
           '절차 순서를 지도화한다 — 누가 어느 단계에서 어떤 역할로 무엇을 했는가.',
           '이전 절차에서 적극적인 조사·소추 역할이 있었는지 식별한다.',
           '같은 사람(또는 긴밀히 동일시되는 자)이 이제 후속 결정 패널에 앉았는지 묻는다.',
           '그렇다면 Isbester에 따라 추정 편향이 구조적으로 성립 — Hot Holdings 식의 distinguishing(단순 자문 역할, 독립 결정자)은 통하지 않는다.',
           '편향은 always-JE(materiality 단계 없음) — 구제는 보통 certiorari + 다른 구성의 패널에서 재심리.'
         ],
         issue:'개 공격 사건에서 Isbester 부인을 동물 관리 법령 위반으로 적극 소추한 Knox Council 공무원이, 후속으로 그녀의 개 처분을 결정하는 Council 패널에도 앉을 수 있는가.',
         conclusion:'아니다 — 같은 사안에서 소추자와 결정자의 구조적 중첩이 추정 편향을 일으킨다. 결정은 취소됐다.',
         keywords:['사전 관여','패널','소추자-결정자','구조적 중첩'],
         facts:'Knox Council 공무원이 개 공격에서 비롯된 동물 관리 법령 위반으로 Isbester 부인을 소추했다. 그 뒤 같은 공무원이 그녀의 개 처분을 명령하기로 결정한 Council 패널의 구성원으로도 앉은 사건.'}},
  cny17:{
    id:'cny17', name:'CNY17 v Minister for Immigration and Border Protection', cite:'[2019] HCA 50; (2019) 268 CLR 76', icon:'◔', color:'c-coral',
    topic:'W6', category:'Case',
    en:{ rule:'Apprehended bias is judged from what a fair-minded observer would reasonably take from the prejudicial material that was placed before the decision-maker — not from the decision-maker\'s own assertion that they disregarded it. The court does not, and cannot, assume away the risk created by the material\'s presence on the file. (The majority and minority differed on the factual conclusion in CNY17 itself, but the legal test was common ground.)',
         principle:'CNY17 reinforced two propositions. First, the test is observer-facing — the question is what a fair-minded informed observer would apprehend, not what the decision-maker subjectively did. Second, "I read it but disregarded it" assurances do not by themselves dissolve the apprehension; the structural fact of exposure to the prejudicial material is what counts. The case is significant in administrative settings (IAA, AAT, regulators) where adverse files are routinely transmitted to decision-makers along with the substantive material — Ebner\'s observer is taken to know this and to apprehend the risk it carries.',
         when:'Use CNY17 whenever prejudicial material has been before the decision-maker even though the decision-maker says it was not relied on. Common scenarios: police antecedents transmitted to migration tribunals, prior unrelated adverse findings forwarded to merits-review bodies, or other "background" material that should never have been on the file.',
         howApply:[
           'Identify the prejudicial material that was placed before the decision-maker, and confirm it was actually received.',
           'Apply the Ebner observer test: would a fair-minded informed observer reasonably apprehend that the decision-maker might be unable to put that material out of mind?',
           'Treat any "I disregarded it" assurance as relevant but not decisive — the structural fact of exposure controls.',
           'Articulate the logical connection between the material and the apprehended deviation from impartiality (Ebner step 2).',
           'Bias is always-JE — once made out, no materiality limb. Remedy: certiorari and rehearing by a differently-constituted decision-maker.'
         ],
         issue:'Whether the IAA member\'s receipt of prejudicial detention-related material — material the member said had been disregarded — gave rise to apprehended bias.',
         conclusion:'Yes (majority) — apprehended bias was made out. The fair-minded observer would reasonably apprehend that the IAA member might not have been able to put the prejudicial material entirely out of mind.',
         keywords:['prejudicial material','reasonable observer','disregarded','IAA'],
         facts:'A detention authority forwarded prejudicial material about CNY17 to the IAA decision-maker reviewing his refugee claim. The IAA member said the material had been disregarded, but the material was on the file before the decision was made.'},
    kr:{ rule:'추정 편향은 결정자 앞에 놓였던 편견적 자료를 공정한 마음의 사정에 밝은 관찰자가 어떻게 읽을지로 판단된다 — 결정자 자신이 "무시했다"고 말한 것으로 판단되지 않는다. 그 자료가 기록에 존재했다는 사실로 생긴 위험을 법원이 가정으로 지워 버리지 못한다. (CNY17 자체에서는 다수와 소수가 사실 결론에서 갈렸지만, 법적 기준은 공통이었다.)',
         principle:'CNY17은 두 명제를 굳혔다. 첫째, 기준은 관찰자 측면 — 질문은 공정한 마음의 사정에 밝은 관찰자가 무엇을 의심할 것인가지, 결정자가 주관적으로 무엇을 했는가가 아니다. 둘째, "읽었지만 무시했다"는 안심시킴만으로 의심이 풀리지 않는다 — 편견적 자료에 노출됐다는 구조적 사실이 결정적이다. 행정 맥락(IAA, AAT, 규제기관)에서는 불리한 기록이 본안 자료와 함께 결정자에게 일상적으로 전달되는데 — Ebner의 관찰자는 이를 안다고 보고, 그것이 동반하는 위험도 의심한다.',
         when:'결정자가 의존하지 않았다고 말하더라도 편견적 자료가 결정자 앞에 놓였던 경우에 인용한다. 흔한 시나리오: 경찰 전과 자료가 이민 tribunal에 전달, 이전의 무관한 불리한 인정이 실체심사 기관에 전달, 기록에서는 안 됐던 "배경" 자료 등.',
         howApply:[
           '결정자 앞에 놓였던 편견적 자료를 식별하고, 실제로 수령됐음을 확인한다.',
           'Ebner 관찰자 기준을 적용한다 — 공정한 마음의 사정에 밝은 관찰자가 결정자가 그 자료를 마음에서 지우지 못할 수 있다고 합리적으로 의심할 만한가.',
           '"무시했다"는 안심시킴은 관련은 있지만 결정적이지 않다 — 노출된 구조적 사실이 지배한다.',
           '그 자료와 두려워하는 편향 사이의 논리적 연결을 풀어 준다(Ebner 2단계).',
           '편향은 always-JE — 인정되면 materiality 단계는 없다. 구제: certiorari + 다른 구성의 결정자에 의한 재심리.'
         ],
         issue:'IAA 위원이 편견적 구금 관련 자료를 받은 것 — 그가 무시했다고 한 자료 — 이 추정 편향을 일으키는가.',
         conclusion:'다수: 그렇다 — 추정 편향이 성립한다. 공정한 관찰자라면 IAA 위원이 그 편견적 자료를 마음에서 완전히 지우지 못할 수 있다고 합리적으로 의심할 수 있다.',
         keywords:['편견적 자료','합리적 관찰자','무시했다','IAA'],
         facts:'구금 당국이 CNY17의 난민 신청을 심사하는 IAA 결정자에게 그에 관한 편견적 자료를 전달했다. IAA 위원은 그 자료를 무시했다고 했지만, 결정 전에 그 자료는 기록에 있었다.'}},
  hotholdings:{
    id:'hotholdings', name:'Hot Holdings Pty Ltd v Creasy', cite:'[2002] HCA 51; (2002) 210 CLR 438', icon:'◐', color:'c-gray',
    topic:'W6', category:'Case',
    en:{ rule:'A subordinate or adviser\'s personal interest may be imputed to the decision-maker for apprehended-bias purposes only if the adviser played a role of significance in the decision — i.e. their input materially shaped the outcome. Where the adviser merely supplied information or made a recommendation that was independently considered by the decision-maker, the imputation does not run, and apprehended bias is not made out.',
         principle:'Hot Holdings governs the transmission of bias from advisers to independent decision-makers. The doctrine is a calibration: not every conflict held by a junior officer infects the Minister or Tribunal above. The test focuses on causal significance — did the conflicted adviser materially shape the decision, or were they one input among many that the independent decision-maker weighed for themselves? Hot Holdings is the more permissive end; Isbester is the structural-overlap end where a categorical prohibition applies regardless of significance. Together they map adviser-bias doctrine in Australian admin law.',
         when:'Use Hot Holdings as the framework whenever an adviser, departmental officer, or assistant has a personal interest, and the question is whether that interest taints the decision of an independent decision-maker above them. Distinguish Isbester (categorical structural overlap of prosecutor / decider).',
         howApply:[
           'Identify the adviser\'s personal interest with precision (financial, prior involvement, family connection).',
           'Map the adviser\'s actual role in the decision — were they a significant operational input, or one of many inputs filtered through an independent decision-maker?',
           'If the role was significant (i.e. materially shaped the outcome), the interest can be imputed and apprehended bias may follow.',
           'If the role was peripheral and the decision-maker independently weighed the inputs, Hot Holdings tolerates it.',
           'Distinguish Isbester — that case applies a categorical prohibition for prosecutor/decider overlap, regardless of where on the significance scale the role sits.'
         ],
         issue:'Whether the conflicted shareholdings of departmental officers who advised on a mining-tenement decision tainted the Minister\'s decision through apprehended bias.',
         conclusion:'No — the advisers\' input did not rise to the level of significance required to impute their interest to the independent Ministerial decision-maker.',
         keywords:['adviser bias','imputation','significance','independent decision-maker'],
         facts:'Departmental staff who held shareholdings in companies affected by a mining tenement decision provided advice to the Minister, who made the final decision. Hot Holdings argued that the staff conflicts tainted the decision through apprehended bias.'},
    kr:{ rule:'하위자나 자문자의 개인적 이해는, 그 자문자가 결정에서 의미 있는 역할을 했을 때에 한해 — 즉 그 의견이 결과를 실질적으로 형성했을 때에 한해 — 추정 편향 목적상 결정자에게 귀속된다. 자문자가 단지 정보를 제공하거나, 독립적인 결정자가 별도로 검토한 권고를 한 정도라면 귀속은 발생하지 않고 추정 편향도 성립하지 않는다.',
         principle:'Hot Holdings는 자문자에서 독립 결정자로의 편향 전이를 규율한다. 이 법리는 보정 — 하급 직원이 가진 모든 이해 충돌이 위에 있는 장관이나 tribunal까지 감염시키는 것은 아니다. 기준은 인과적 의미에 초점을 둔다 — 충돌이 있는 자문자가 결정을 실질적으로 형성했는가, 아니면 독립 결정자가 자기 비중으로 가중치를 매긴 여러 입력 중 하나였는가. Hot Holdings는 더 관대한 쪽이고, Isbester는 구조적 중첩 쪽으로 의미와 무관하게 범주적 금지가 적용되는 자리다. 둘이 함께 호주 행정법의 자문자 편향 교리를 짠다.',
         when:'자문자·부처 직원·보조자가 개인적 이해를 가지고 있고, 그 이해가 위에 있는 독립 결정자의 결정을 오염시키는지 묻는 자리에서 분석틀로 사용한다. Isbester(소추자/결정자 구조적 중첩의 범주적 금지)와 distinguishing.',
         howApply:[
           '자문자의 개인적 이해를 구체적으로 식별한다(재정적, 사전 관여, 가족 관계).',
           '자문자의 결정에서의 실제 역할을 지도화한다 — 의미 있는 운영적 입력이었는가, 아니면 독립 결정자가 걸러 낸 여러 입력 중 하나였는가.',
           '역할이 의미 있었다면(결과를 실질적으로 형성), 이해가 귀속될 수 있고 추정 편향이 따를 수 있다.',
           '역할이 주변적이었고 결정자가 독립적으로 입력을 가중치 매겼다면 Hot Holdings는 이를 허용한다.',
           'Isbester와 distinguishing — Isbester는 의미의 척도와 무관하게 소추자/결정자 중첩에 범주적 금지를 적용한다.'
         ],
         issue:'광업권 결정에 자문한 부처 직원들이 보유한 주식이 장관 결정을 추정 편향으로 오염시켰는가.',
         conclusion:'아니다 — 자문자들의 입력은 그 이해를 독립적인 장관 결정자에게 귀속시킬 만한 의미 수준에 이르지 않았다.',
         keywords:['자문자 bias','귀속','의미 있는 역할','독립 결정자'],
         facts:'광업권 결정의 영향을 받는 회사들의 주식을 보유한 부처 직원들이 장관에게 자문을 제공했고, 장관이 최종 결정을 내렸다. Hot Holdings는 직원의 이해 충돌이 결정을 추정 편향으로 오염시켰다고 주장했다.'}},
  graham:{
    id:'graham', name:'Graham v Minister for Immigration and Border Protection', cite:'[2017] HCA 33; (2017) 263 CLR 1', icon:'⛨', color:'c-blue',
    topic:'W10', category:'Case',
    en:{ rule:'The constitutionally entrenched minimum of judicial review under s 75(v) cannot be defeated — by privative clauses, no-invalidity clauses, secrecy provisions, or any other legislative device — where the legal OR practical operation of the law denies a court the ability to enforce the legal limits of an officer\'s power. The test is one of "substance, and therefore of degree" [48]: it requires examination not only of the legal operation of the impugned provision but also of its practical impact on the court\'s capacity, through judicial process, to discern and declare whether the legislated conditions on lawful power have been observed. The extension at [46] is critical — the principle is not confined to privative clauses; it reaches ANY provision (including secrecy provisions) whose legal or practical operation denies that supervisory capacity.',
         principle:'Graham generalises the S157 entrenched-jurisdiction logic beyond privative clauses to information-control / secrecy provisions, and frames the operative test as substance-and-degree focused on practical impact. The constitutional root is the Hickman impossibility principle (impossible for Parliament to set jurisdictional limits and at the same time deprive the High Court of authority to enforce them — restated three ways: prohibition, mandamus, injunction). Bodruddaza is the illustrative companion: a blanket inflexible time-limit was struck down because its practical effect was to deprive s 75(v) jurisdiction, even though it was not formally a privative clause. The case also draws a sharp line between s 503A(2)(c) (court deprived in limine, with no access to the material) and statutory secrecy regimes that survive constitutional scrutiny (Gypsy Jokers, K-Generation, Condon v Pompano, Totani) precisely because the reviewing court still had access to the information underpinning the decision. PII (Sankey v Whitlam) is also distinguishable because under PII the court balances the competing public interests; under s 503A(2)(c) the executive controls disclosure with the court "deprived in limine". Conscious maladministration / fraud / dishonesty / improper purpose remain reviewable as always-JE (Plaintiff S157). Edelman J dissented; the majority severed using s 15A AIA, reading "court" in s 503A(2)(c) to exclude HCA under s 75(v) and FCA under s 476A when reviewing s 501-series decisions.',
         when:'Reach for Graham whenever a Cth statutory provision restricts what information may be put before the court in JR proceedings, or otherwise operates (legally or practically) to deny meaningful supervisory review — secrecy clauses, evidence-restriction provisions, inflexible time bars (Bodruddaza pattern), no-disclosure-to-court rules. It is the case that converts those drafting devices into constitutional questions even where they are not framed as privative clauses.',
         howApply:[
           'Identify the impugned provision and characterise it (privative clause / no-invalidity clause / secrecy provision / time bar / other).',
           'Examine BOTH the legal operation (what the text formally does) AND the practical impact (what the court is, in fact, prevented from doing in supervisory review).',
           'Apply the substance-and-degree test [48], [63], [65] — the question is whether the court is in fact prevented from discerning and declaring whether legal limits on power were observed; the answer turns on substance.',
           'Distinguish secrecy regimes where the court itself can still see the material (Gypsy Jokers / K-Generation / Condon / Totani — valid) from regimes where the court is deprived in limine (s 503A(2)(c) — invalid).',
           'If invalidity is made out, prefer severance / reading down under s 15A AIA over total invalidation — read the impugned provision down so it does not apply to the entrenched s 75(v) (and s 476A-equivalent) jurisdiction.',
           'Confirm the always-JE floor — fraud, bribery, dishonesty, conscious maladministration or improper purpose remain reviewable under S157, no matter how the provision is drafted.'
         ],
         issue:'Whether s 503A(2)(c) of the Migration Act 1958 (Cth) — which prevented the Minister from being required to divulge to a court information communicated by a "gazetted agency" on confidentiality conditions and relevant to powers under ss 501, 501A, 501B or 501C — denied the entrenched minimum supervisory jurisdiction in s 75(v) of the Constitution (and the equivalent FCA jurisdiction under s 476A).',
         conclusion:'Yes, to that extent. s 503A(2)(c) "strikes at the very heart of the review for which s 75(v) provides" [65] because the protected information is, by definition, relevant to whether the legal limits on the s 501 power were observed — yet the court is deprived of access in limine, with no balancing or weighing function. The invalid application was severable: under s 15A AIA, "court" in s 503A(2)(c) is read down to exclude the HCA exercising s 75(v) jurisdiction and the FCA exercising s 476A(1)(c)/(2) jurisdiction when reviewing s 501-series decisions. s 501(3) and the balance of s 503A(2) remain valid. Edelman J dissented.',
         keywords:['substance and degree','practical impact','secrecy clause','s 75(v)','entrenched minimum','in limine','Bodruddaza pattern'],
         facts:'Mr Graham and Mr Te Puia (NZ citizens) had their visas cancelled by the Minister under s 501(3) on suspected association with the Rebels Outlaw Motorcycle Gang (failing the character test under s 501(6)(b)). The Minister relied on confidential information protected by s 503A from disclosure to any person or court; for Te Puia it appeared to be the sole consideration. They challenged s 503A(2)(c) as inconsistent with s 75(v) of the Constitution.'},
    kr:{ rule:'헌법 s 75(v)가 보장하는 사법심사의 최소선은 어떤 입법 도구로도 — 배제조항이든, no-invalidity 조항이든, 비밀조항이든 — 우회될 수 없다. 법이 법적으로든 실질적으로든 법원이 공무원의 권한 한계를 강제하지 못하게 만든다면 그 조항은 무효다. 기준은 "실질의 문제, 따라서 정도의 문제(substance, and therefore of degree)"[48] — 문언이 형식상 무엇을 하는가뿐 아니라, 그 결과 법원이 사법 절차로 권한 한계 준수 여부를 실제로 따져 볼 수 있는지까지 함께 본다. [46]의 확장이 결정적이다 — 이 원칙은 배제조항에만 묶이지 않고, 비밀조항을 포함한 어떤 조항이든 그 작동이 감독 능력을 빼앗는다면 거기까지 미친다.',
         principle:'Graham은 S157의 보호 관할 논리를 배제조항 너머 정보 통제·비밀조항으로까지 일반화하면서, 실제 작동을 보는 "실질-정도" 기준을 운영 기준으로 자리잡게 했다. 뿌리는 Hickman의 impossibility 원칙이다 — 의회가 권한에 한계를 두면서 동시에 그 한계를 강제할 High Court의 힘을 빼앗는 것은 불가능하다는 것(prohibition·mandamus·injunction 세 형태로 반복된다). Bodruddaza가 좋은 짝 — 형식상 배제조항이 아닌 일률적 기간 제한도 실질적으로 s 75(v) 관할을 빼앗으면 무효가 된다는 사례다. 한편 이 판결은 s 503A(2)(c)처럼 법원이 처음부터 자료에 접근조차 못 하는 경우와, 법원 자신은 자료를 볼 수 있어 살아남은 비밀 체계(Gypsy Jokers, K-Generation, Condon, Totani)를 분명히 갈라 둔다. 공익면책(Sankey)과도 구별된다 — PII에서는 법원이 경합 공익을 비교형량하지만, s 503A(2)(c)에서는 공개 여부를 행정부가 쥐고 법원은 처음부터 손이 묶인다. 사기·뇌물·부정직·의도적 행정부정·부적절한 목적은 항상 JE로 남아 S157에 따라 심사 가능. Edelman J 반대의견. 다수는 s 15A로 분리해 — s 503A(2)(c)의 "court"를 s 501계 결정 심사에서는 s 75(v) HCA와 s 476A FCA를 가리키지 않도록 좁게 읽었다.',
         when:'영연방 법이 JR 절차에서 법원 앞에 둘 수 있는 정보를 제한하거나, 그 밖에 (법적으로든 실질적으로든) 의미 있는 감독을 막는 식으로 작동할 때 — 비밀조항, 증거 제한, Bodruddaza식 경직된 기간 제한, 법원 비공개 규정 — 꺼낸다. 형식상 배제조항이 아닌 입법 도구까지 헌법 문제로 끌어올린 판례.',
         howApply:[
           '먼저 그 조항의 성격을 정한다 — 배제조항인가, no-invalidity인가, 비밀조항인가, 기간 제한인가, 그 외인가.',
           '법적 작동(문언이 형식상 무엇을 하는가)과 실질적 영향(법원이 실제로 감독에서 무엇을 못 하게 되는가)을 같이 본다.',
           '실질-정도 기준을 댄다[48], [63], [65] — 법원이 권한 한계 준수를 따져 볼 길이 실제로 막혔는가, 답은 실질에 있다.',
           '법원 자신은 자료를 볼 수 있는 비밀 체계(Gypsy Jokers/K-Generation/Condon/Totani — 합헌)와, 법원이 처음부터 접근조차 못 하는 체계(s 503A(2)(c) — 무효)를 구분한다.',
           '무효가 인정되면 전면 무효보다 s 15A의 축소해석으로 분리해 낸다 — 그 조항이 s 75(v)(및 s 476A 등가) 관할에는 적용되지 않도록 좁게 읽는다.',
           '바닥선 확인 — 사기·뇌물·부정직·의도적 행정부정·부적절한 목적은 조항을 어떻게 짰든 S157에 따라 여전히 다툴 수 있다.'
         ],
         issue:'Migration Act 1958 (Cth) s 503A(2)(c) — "관보 지정 기관"이 비밀 조건으로 전달한 정보, 그리고 s 501계 권한과 관련된 정보의 공개를 장관에게 요구할 수 없게 한 조항 — 가 헌법 s 75(v)의 보호된 감독관할(및 s 476A FCA 관할)을 부정했는가.',
         conclusion:'그 범위 안에서는 그렇다. s 503A(2)(c)는 "s 75(v)가 제공하는 심사의 핵심을 정면으로 친다"[65] — 보호된 정보는 본질적으로 s 501 권한이 한계 안에서 행사됐는지를 따질 자료인데, 법원은 비교형량이나 검토 기회도 없이 처음부터 접근을 막힌다. 무효 부분은 분리 가능 — s 15A에 따라, "court"를 s 501계 심사에서는 s 75(v) HCA와 s 476A(1)(c)/(2) FCA를 가리키지 않도록 좁게 읽는다. s 501(3)과 s 503A(2)의 나머지 적용은 그대로 유효. Edelman J 반대의견.',
         keywords:['substance and degree','실질적 영향','비밀조항','s 75(v)','보호된 최소','in limine','Bodruddaza 패턴'],
         facts:'NZ 시민 Graham씨와 Te Puia씨가 Rebels Outlaw Motorcycle Gang과의 관계 의혹으로 s 501(3)에 따라 비자가 취소된 사건(s 501(6)(b) 인격 테스트 미충족). 장관은 s 503A로 어떤 사람이나 법원에도 공개 금지된 기밀 정보에 의존했고, Te Puia에 대해서는 그것이 유일한 고려 자료로 보였다. 이들이 s 503A(2)(c)가 헌법 s 75(v)에 모순된다고 다툰 사건.'}},
  futuris:{
    id:'futuris', name:'Commissioner of Taxation v Futuris Corporation Ltd', cite:'[2008] HCA 32; (2008) 237 CLR 146', icon:'⊟', color:'c-ochre',
    topic:'W10', category:'Case',
    en:{ rule:'A "no-invalidity" clause — typified by s 175 ITAA 1936 — preserves the legal effect of an assessment despite non-compliance with statutory provisions, but DOES NOT oust s 75(v) / s 39B(1) review for jurisdictional error. Applying Project Blue Sky purposive construction, the question is whether the statute\'s purpose is that breach renders the assessment invalid; for ordinary process errors the answer is no (within the scheme of Pt IVC, which provides an alternative review pathway). However, s 175 does NOT reach (i) tentative or provisional purported assessments, or (ii) conscious maladministration of the assessment process — both of which "manifest jurisdictional error and attract the jurisdiction to issue the constitutional writs". s 177(1) (production = conclusive evidence) is "not a privative clause in the ordinary use of that term" and does not limit s 75(v) / s 39B(1).',
         principle:'Futuris draws three crucial lines in the no-invalidity / privative clause family.\n(1) Constitutional floor: a tax cannot be made incontestable (MacCormick; Richard Walter), but Pt IVC of the Taxation Administration Act provides the alternative contestability that satisfies that floor — which is why s 175 is constitutionally permissible despite shielding ordinary process errors.\n(2) Always-JE carve-out: conscious maladministration (deliberate failure), fraud, bribery, dishonesty and improper purpose remain reviewable as jurisdictional error under s 75(v) — supported by the tort of misfeasance in public office and s 13 Public Service Act\'s integrity obligations, which point decisively against reading s 175 to authorise deliberate failures.\n(3) Doctrinal mapping: s 175 (no-invalidity) is conceptually distinct from a true privative clause (S157) and from a secrecy/information-control clause (Graham); each is analysed differently but all are anchored in s 75(v) entrenchment. Note also that the principles of jurisdictional error control the CONSTITUTIONAL WRITS, but injunction and declaration (Enfield, PBS) operate on a different equitable basis; where s 175 applies and there is no affectation of validity, equitable remedies likewise have no foothold. F J Bloemen (Mason & Wilson JJ), to the extent inconsistent with this, should not be followed.',
         when:'Use Futuris\n(1) when defending a no-invalidity clause against a privative-clause-style constitutional challenge — distinguish the two and point to any alternative review path (Pt IVC analogue)\n(2) when arguing that an ordinary process error is shielded by a no-invalidity clause and so does not attract constitutional writs; OR conversely\n(3) when running a conscious-maladministration / fraud / dishonesty / improper-purpose argument that no no-invalidity clause can defeat.',
         howApply:[
           'Characterise the impugned provision: privative clause (S157), no-invalidity (Futuris), secrecy (Graham), or no-disclosure-of-evidence (Graham). Each runs on a different analysis.',
           'For a no-invalidity clause, apply Project Blue Sky purposive interpretation — is the statutory purpose that breach invalidates? If the broader scheme supplies an alternative contestability path (Pt IVC pattern), ordinary process errors will fall within the no-invalidity shield.',
           'Confirm the constitutional floor: the tax / decision must not be incontestable (MacCormick). Identify the alternative review pathway and explain why it preserves contestability.',
           'Carve out the always-JE categories — tentative/provisional decisions; conscious maladministration; fraud, bribery, dishonesty; improper purpose. These manifest JE and attract s 75(v) / s 39B(1) constitutional writs regardless of the no-invalidity clause.',
           'On equitable remedies (injunction, declaration), remember they operate on a different basis — but where the no-invalidity clause means there is no affectation of validity, the equitable foundation is also absent. s 21 FCA Act limits FCA declarations to matters within original jurisdiction.',
           'Where Pt IVC proceedings are pending or available, expect the court to exercise its discretion to refuse parallel s 75(v) / s 39B relief (Glennan; Re McBain).'
         ],
         issue:'(1) Whether s 175 of the Income Tax Assessment Act 1936 (Cth) prevented errors in the assessment process from amounting to jurisdictional error reviewable under s 39B(1) of the Judiciary Act (replicating s 75(v) of the Constitution)\n(2) whether, on the facts, the Commissioner had committed conscious maladministration by applying the Act to facts he knew to be untrue.',
         conclusion:'(1) Yes — applying Project Blue Sky to s 175 (read with ss 175A and 177(1)), ordinary process errors do not affect the validity of an "assessment" and so do not amount to jurisdictional error; the constitutional minimum is met by the alternative review path under Pt IVC.\n(2) On the facts, there was no conscious maladministration — the Commissioner did not apply the Act to facts known to be untrue; there was no absence of bona fides. Result: no jurisdictional error, no constitutional writ, no declaration. The Full Court was reversed. Tentative/provisional purported assessments and conscious maladministration would still attract constitutional writs as JE.',
         keywords:['no-invalidity clause','s 175 ITAA','conscious maladministration','Pt IVC alternative review','contestability','Project Blue Sky','misfeasance in public office'],
         facts:'Futuris objected to a tax assessment that applied anti-avoidance provisions on capital gains. It first filed under Pt IVC of the Taxation Administration Act (left in abeyance) and then sought s 39B(1) judicial review. The FCAFC found the Commissioner had applied the Act to facts he knew to be untrue (deliberate double-counting). The Commissioner appealed; the issue was whether s 175 shielded the assessment from constitutional writ review.'},
    kr:{ rule:'"No-invalidity" 조항 — 대표적으로 ITAA 1936 s 175 — 은 법령상 의무 위반이 있어도 과세의 법적 효력을 유지시키지만, 관할권적 오류에 대한 s 75(v) / s 39B(1) 심사를 봉쇄하지는 않는다. Project Blue Sky의 목적론적 해석을 적용하면 질문은 "법령의 취지가 위반을 무효로 만드는가"이고, 통상의 절차 오류에 대한 답은 — Pt IVC라는 대체 심사 경로가 있는 체계 안에서는 — 아니다. 다만 s 175는 (i) 잠정·임시 외관상 과세, (ii) 과세 절차의 의도적 행정부정(conscious maladministration)에는 미치지 않는다 — 둘 다 "관할권적 오류를 드러내고 헌법적 writ 관할을 발동시킨다". s 177(1)(통지 제시 = 확정적 증거)은 "통상적 의미의 배제조항이 아니"며 s 75(v) / s 39B(1) 관할을 제한하지 않는다.',
         principle:'Futuris는 no-invalidity·배제조항 가족에서 세 개의 결정적인 선을 긋는다.\n(1) 헌법적 바닥선 — 조세는 incontestable(다툴 수 없게)할 수 없다(MacCormick; Richard Walter). 다만 Taxation Administration Act의 Pt IVC가 대체적 다툴 수 있는 경로를 제공하므로 그 바닥선이 충족 — 그래서 s 175가 통상의 절차 오류를 차단해도 헌법적으로 허용된다.\n(2) Always-JE 예외 — 의도적 행정부정(conscious maladministration), 사기, 뇌물, 부정직, 부적절한 목적은 s 75(v)의 관할권적 오류로 여전히 심사 가능. 공무원의 misfeasance in public office 불법행위와 s 13 Public Service Act의 청렴 의무가 — s 175를 의도적 위반까지 보호하는 것으로 읽지 않을 — 결정적인 근거가 된다.\n(3) 교리적 지도 — s 175(no-invalidity)는 진정한 배제조항(S157)과도, 비밀·정보 통제 조항(Graham)과도 개념적으로 구별된다. 각각 다르게 분석되지만 모두 s 75(v)의 보호된 관할에 닻을 내린다. 또 관할권적 오류 법리는 헌법적 writ를 통제할 뿐, injunction과 declaration(Enfield, PBS)은 다른 형평법적 토대에서 작동한다 — 그러나 s 175가 적용되어 유효성에 영향이 없다면 형평법적 토대도 없다. F J Bloemen(Mason & Wilson JJ)은 이와 모순되는 한 따르지 않는다.',
         when:'Futuris는\n(1) no-invalidity 조항을 배제조항형 헌법 다툼에서 방어할 때 — 둘을 구별하고 대체 심사 경로(Pt IVC 패턴)를 짚는다\n(2) 통상의 절차 오류가 no-invalidity 조항으로 보호되어 헌법적 writ가 안 된다고 주장할 때; 또는 반대로\n(3) no-invalidity 조항이 무력화할 수 없는 의도적 행정부정·사기·부정직·부적절한 목적 주장을 펼칠 때 사용한다.',
         howApply:[
           '다투어진 조항의 성격을 정한다 — 배제조항(S157), no-invalidity(Futuris), 비밀(Graham), 법원 비공개(Graham). 각기 다른 분석이 돌아간다.',
           'No-invalidity 조항이라면 Project Blue Sky의 목적론적 해석을 적용한다 — 법령의 취지가 위반을 무효로 만드는가? 더 넓은 체계가 대체 다툴 수 있는 경로(Pt IVC 패턴)를 제공한다면 통상의 절차 오류는 no-invalidity 보호 안에 들어간다.',
           '헌법적 바닥선을 확인한다 — 그 조세·결정이 incontestable이어서는 안 된다(MacCormick). 대체 심사 경로를 식별하고 그것이 다툴 수 있는 가능성을 어떻게 보존하는지 설명한다.',
           'Always-JE 범주를 도려낸다 — 잠정·임시 결정; 의도적 행정부정; 사기·뇌물·부정직; 부적절한 목적. 이들은 JE를 드러내고 no-invalidity 조항과 무관하게 s 75(v) / s 39B(1) 헌법적 writ를 발동시킨다.',
           '형평법적 구제(injunction, declaration)는 다른 토대 위에서 작동하지만 — no-invalidity 조항으로 유효성에 영향이 없다면 그 형평법적 토대도 사라진다. s 21 FCA Act는 FCA declaration을 원시 관할 사안에만 한정한다.',
           'Pt IVC 절차가 진행 중이거나 가능하다면 법원이 재량으로 병행 s 75(v) / s 39B 구제를 거부할 것으로 예상한다(Glennan; Re McBain).'
         ],
         issue:'(1) Income Tax Assessment Act 1936 (Cth) s 175가 과세 절차의 오류를 관할권적 오류 — Judiciary Act s 39B(1)(헌법 s 75(v) 복제) 심사 대상 — 에서 배제하는가\n(2) 사실관계에서 Commissioner가 자신이 사실이 아님을 알고 있는 사실관계에 Act를 적용함으로써 의도적 행정부정을 범했는가.',
         conclusion:'(1) 그렇다 — Project Blue Sky를 s 175에 적용하면(s 175A 및 s 177(1)과 함께 읽어), 통상의 절차 오류는 "assessment"의 유효성에 영향을 주지 않으며 따라서 관할권적 오류가 아니다. 헌법적 최소는 Pt IVC라는 대체 심사 경로로 충족.\n(2) 사실관계에서 의도적 행정부정은 없었다 — Commissioner가 거짓임을 안 사실에 Act를 적용하지 않았고, 선의(bona fides)의 결여도 없었다. 결과: 관할권적 오류 없음, 헌법적 writ 없음, declaration 없음. Full Court 파기. 잠정·임시 외관상 과세와 의도적 행정부정이라면 여전히 JE로 헌법적 writ를 발동시킨다.',
         keywords:['no-invalidity 조항','s 175 ITAA','conscious maladministration','Pt IVC 대체 심사','contestability','Project Blue Sky','misfeasance in public office'],
         facts:'Futuris가 양도소득 anti-avoidance 조항을 적용한 과세에 이의를 제기. Taxation Administration Act Pt IVC로 먼저 제기했다가 유보하고, s 39B(1) 사법심사를 청구. FCAFC가 Commissioner가 거짓임을 안 사실에 Act를 적용했다고(의도적 이중 계상) 인정. Commissioner가 항소했고, s 175가 그 과세를 헌법적 writ 심사에서 보호하는지가 쟁점이었다.'}},
  rtl:{
    id:'rtl', name:'Right to Life Association (NSW) Inc v Department of Human Services and Health', cite:'(1995) 56 FCR 50', icon:'⊥', color:'c-violet',
    topic:'W9', category:'Case',
    en:{ rule:'Pure ideological, philosophical or moral concern — however strongly held and however well-organised the body holding it — does not establish special-interest standing under ACF. Standing requires an interest beyond intellectual or emotional engagement; ACF\'s baseline draws the line here.',
         principle:'RTL sits at the negative end of the standing spectrum. It demonstrates that organisational form and intensity of conviction do not substitute for a substantive distinctive interest. Argos later resisted reading RTL through a "statutory context" lens that would have unduly constrained future standing arguments.',
         when:'RTL is the case to confront when the applicant\'s interest looks ideological. Either distinguish (show a distinctive substantive interest beyond conviction) or argue Argos has narrowed RTL\'s reach.',
         howApply:[
           'Identify whether the applicant\'s interest is fundamentally ideological/moral, or has a substantive distinctive component.',
           'If ideological-only, RTL bars standing — pure conviction is not enough.',
           'If distinguishing, foreground the distinctive substantive component (economic, custodial, professional, regulatory) and rely on Argos\'s narrowing of RTL.'
         ],
         issue:'Whether the Right to Life Association had standing to challenge TGA evaluations of mifepristone (RU-486).',
         conclusion:'No standing — the Association\'s interest was ideological/philosophical, not the kind of distinctive special interest ACF requires.',
         keywords:['ideological','intellectual concern','denied','RTL'],
         facts:'The Right to Life Association sought review of TGA-related decisions concerning the abortion drug RU-486 (mifepristone).'},
    kr:{ rule:'순수한 이념적·철학적·도덕적 관심은 — 아무리 강하게 가지고 있고, 그 단체가 잘 조직돼 있다 하더라도 — ACF의 special-interest standing을 형성하지 않는다. Standing은 지적·감정적 관여 이상의 이해를 요구한다 — ACF의 기본선이 여기 선을 긋는다.',
         principle:'RTL은 standing 스펙트럼의 부정적 끝에 선다. 조직적 형태나 신념의 강도가 실체적·구별되는 이해를 대체할 수 없음을 보여 준다. Argos는 이후 RTL을 "법령상 맥락"의 렌즈로 읽어 미래 standing 주장을 부당히 제약하려는 시도에 저항했다.',
         when:'신청인의 이해가 이념적으로 보일 때 마주해야 하는 판례. distinguishing(신념을 넘는 실체적·구별되는 이해를 보임) 또는 Argos가 RTL의 도달을 좁혔다고 주장한다.',
         howApply:[
           '신청인의 이해가 본질적으로 이념적·도덕적인지, 아니면 실체적·구별되는 요소가 있는지 식별한다.',
           '이념적인 것뿐이라면 RTL이 standing을 막는다 — 순수한 신념으로는 부족.',
           'distinguishing이라면 실체적·구별되는 요소(경제적·수호적·직업적·규제상)를 전면에 두고, Argos의 RTL 좁히기를 활용한다.'
         ],
         issue:'Right to Life Association이 낙태약 RU-486(mifepristone)에 대한 TGA 결정을 다툴 standing을 갖는가.',
         conclusion:'Standing 없음 — 협회의 이해는 이념적·철학적이며, ACF가 요구하는 종류의 구별되는 special interest가 아니다.',
         keywords:['이념적','지적 관심','거부','RTL'],
         facts:'Right to Life Association이 낙태약 RU-486(mifepristone) 관련 TGA 결정의 심사를 구한 사건.'}},
  batemans:{
    id:'batemans', name:"Bateman's Bay Local Aboriginal Land Council v Aboriginal Community Benefit Fund Pty Ltd", cite:'[1998] HCA 49; (1998) 194 CLR 247', icon:'⊠', color:'c-teal',
    topic:'W9', category:'Case',
    en:{ rule:'Economic detriment from being forced to compete with a public body operating beyond power can ground special-interest standing. The court rejected earlier authority suggesting standing rules should be applied "narrowly"; a more open, functional approach is now preferred.',
         principle:'Bateman\'s Bay liberalised standing for commercial competitors. It pairs with Argos (commercial competitor in planning context) and sits beyond ACF\'s baseline — established competitors disadvantaged by ultra vires public-sector trading have substantive economic standing.',
         when:'Use Bateman\'s Bay when a commercial entity wants to challenge a public body\'s ultra vires expansion into a competing market. Pair with Argos for general commercial-competitor standing arguments.',
         howApply:[
           'Identify the public body\'s impugned activity and the statutory power on which it relies.',
           'Show the applicant suffers economic detriment as a competitor in the affected market.',
           'Argue this competitive economic detriment is special interest under ACF — Bateman\'s Bay confirms the door is open and rejects narrow standing rules.'
         ],
         issue:'Whether the Aboriginal Community Benefit Fund — a private funeral fund — had standing to enjoin Bateman\'s Bay Local Aboriginal Land Council\'s expansion into competing funeral services beyond its statutory power.',
         conclusion:'Yes — economic detriment from competition with an ultra vires public body grounded special-interest standing.',
         keywords:['economic detriment','competitive','liberal approach','batemans'],
         facts:'The Aboriginal Community Benefit Fund (a private funeral-benefit organisation) challenged Bateman\'s Bay LSC\'s expansion into funeral services, alleging the LSC was acting beyond its statutory power.'},
    kr:{ rule:'권한을 넘어 운영하는 공기관과 경쟁하게 되는 경제적 불이익은 special-interest standing의 근거가 될 수 있다. 법원은 standing 규칙을 "협소하게" 적용해야 한다는 과거 권위를 거부했다 — 이제는 더 열린, 기능적 접근을 선호한다.',
         principle:'Bateman\'s Bay는 상업적 경쟁자에게 standing을 자유화했다. Argos(계획 맥락의 상업적 경쟁자)와 짝짓고, ACF의 기본선 너머에 자리한다 — 권한 외 공공 부문 거래로 불리해진 기성 경쟁자는 실체적 경제적 standing이 있다.',
         when:'상업적 주체가 공기관의 권한 외 경쟁시장 확장을 다투려 할 때 인용한다. 일반 상업적 경쟁자 standing 주장에서 Argos와 짝짓는다.',
         howApply:[
           '공기관의 다투어진 활동과 그것이 의존하는 법령상 권한을 식별한다.',
           '신청인이 영향받는 시장의 경쟁자로서 경제적 불이익을 입는다는 것을 보인다.',
           '이 경쟁적 경제적 불이익이 ACF의 special interest임을 주장한다 — Bateman\'s Bay가 문이 열려 있음을 확인하고 협소한 standing 규칙을 거부했다.'
         ],
         issue:'민간 장례 기금 Aboriginal Community Benefit Fund가 Bateman\'s Bay LSC의 권한 외 장례 서비스 확장을 금지할 standing을 갖는가.',
         conclusion:'그렇다 — 권한 외 공기관과의 경쟁으로 인한 경제적 불이익이 special-interest standing을 정초했다.',
         keywords:['경제적 불이익','경쟁','자유주의적 접근','batemans'],
         facts:'민간 장례 보장 단체 Aboriginal Community Benefit Fund가 Bateman\'s Bay LSC가 법령상 권한을 넘어 장례 서비스로 확장하고 있다며 다툰 사건.'}},
  bodruddaza:{
    id:'bodruddaza', name:'Bodruddaza v Minister for Immigration and Multicultural Affairs', cite:'[2007] HCA 14; (2007) 228 CLR 651', icon:'⌛', color:'c-coral',
    topic:'W10', category:'Case',
    en:{ rule:'A statutory time limit on bringing s 75(v) applications is constitutionally invalid where it operates as a blanket inflexible bar that fails to allow for the range of vitiating circumstances which may affect administrative decision-making. The vice is practical rather than formal: even a provision not framed as a privative clause is invalid if its practical effect is to deprive the High Court of its constitutional s 75(v) jurisdiction.',
         principle:'Bodruddaza is the leading illustration of the Graham-type principle: legislative devices that are not formally privative clauses can still be unconstitutional if their practical operation defeats s 75(v). The case is regularly invoked alongside Graham for the proposition that the substance-and-degree test reaches beyond privative-clause drafting. Section 486A of the Migration Act 1958 (Cth) — which imposed a strict 84-day time limit on s 75(v) applications in migration matters, with limited extension — was held invalid because it failed to accommodate genuinely vitiating circumstances (e.g. fraud only discoverable late). The fix later adopted by Parliament was a more flexible time-limit regime that allows extensions where the interests of justice require.',
         when:'Cite Bodruddaza whenever a statutory provision imposes a hard procedural bar (especially a time limit, but also evidentiary or other procedural restrictions) on s 75(v) review that does not allow for genuinely vitiating circumstances. Pair with Graham for the broader substance-and-degree framework.',
         howApply:[
           'Identify the procedural restriction and its operation — is there genuine flexibility to accommodate vitiating circumstances, or is the bar blanket and inflexible?',
           'Apply the Graham-style substance-and-degree test: would the restriction, in practical operation, deprive the court of meaningful s 75(v) supervision in cases where vitiating circumstances arise?',
           'If yes, the restriction is constitutionally invalid to that extent — typically severed or read down rather than struck down entirely.'
         ],
         issue:'Whether s 486A of the Migration Act 1958 (Cth), imposing a strict time limit on s 75(v) applications in migration matters, was constitutionally valid.',
         conclusion:'Invalid — the inflexible time limit failed to allow for vitiating circumstances and thereby deprived the High Court of its s 75(v) jurisdiction in cases where such circumstances arose.',
         keywords:['time limit','practical impact','s 75(v)','Bodruddaza pattern','inflexibility'],
         facts:'A migration applicant sought s 75(v) relief in the High Court outside the strict time window prescribed by s 486A of the Migration Act, and challenged the validity of that time-limit provision.'},
    kr:{ rule:'s 75(v) 신청에 부여된 법령상 기간 제한은, 행정 의사결정에 영향을 줄 수 있는 다양한 무효 사유(vitiating circumstances)를 수용하지 못하는 경직된 일률적 차단으로 작동한다면 헌법적으로 무효이다. 그 위헌성은 형식이 아니라 실질 — 형식상 배제조항으로 짜이지 않은 조항도 그 실질적 효과가 High Court의 헌법적 s 75(v) 관할을 박탈한다면 무효다.',
         principle:'Bodruddaza는 Graham형 원칙의 가장 또렷한 illustration이다 — 형식상 배제조항이 아닌 입법 도구도 그 실질적 작동이 s 75(v)를 무력화한다면 위헌일 수 있다. substance-and-degree 테스트가 배제조항 작성 너머로 미친다는 명제를 위해 Graham과 함께 자주 인용된다. Migration Act 1958 (Cth) s 486A — 이민 사안의 s 75(v) 신청에 엄격한 84일 기간 제한과 제한적 연장만 허용한 조항 — 가, 진정한 무효 사유(예: 뒤늦게 발견되는 사기)를 수용하지 못한다는 이유로 무효 판정. 이후 의회는 더 유연한 — 정의 이익이 요구할 때 연장 가능한 — 기간 제한 체제로 대체했다.',
         when:'법령상 절차 차단(특히 기간 제한이지만, 증거나 기타 절차적 제한도 포함)이 s 75(v) 심사에 부과되면서 진정한 무효 사유를 수용하지 않을 때 인용. Graham의 더 넓은 substance-and-degree framework와 짝짓는다.',
         howApply:[
           '절차적 제한과 그 작동을 식별한다 — 무효 사유를 수용할 진정한 유연성이 있는가, 아니면 일률적·경직된 차단인가.',
           'Graham 식 substance-and-degree 테스트를 적용한다 — 그 제한이 실질적 작동에서, 무효 사유가 발생한 사건들에 대한 의미 있는 s 75(v) 감독을 법원에서 박탈하는가.',
           '그렇다면 그 범위 내에서 헌법적으로 무효 — 통상 전면 무효화가 아니라 분리·축소해석으로 처리된다.'
         ],
         issue:'이민 사안의 s 75(v) 신청에 엄격한 기간 제한을 부과한 Migration Act 1958 (Cth) s 486A가 헌법적으로 유효한가.',
         conclusion:'무효 — 경직된 기간 제한이 무효 사유를 수용하지 못해, 그러한 사유가 발생한 사건들에서 High Court의 s 75(v) 관할을 박탈했다.',
         keywords:['기간 제한','실질적 영향','s 75(v)','Bodruddaza 패턴','경직성'],
         facts:'한 이민 신청인이 Migration Act s 486A의 엄격한 기간을 넘어 High Court에 s 75(v) 구제를 청구하면서 그 기간 제한 조항의 유효성을 다툰 사건.'}},
  shi:{
    id:'shi', name:'Shi v Migration Agents Registration Authority', cite:'[2008] HCA 31; (2008) 235 CLR 286', icon:'⏱', color:'c-blue',
    topic:'W11', category:'Case',
    en:{ rule:'On merits review, the tribunal "stands in the shoes" of the original decision-maker and decides on the material before it at the time of the tribunal\'s decision — not at the time of the original decision. The tribunal can therefore consider events and evidence that post-date the original decision, subject to any contrary statutory direction. This carries forward to the ART under the 2024 reforms.',
         principle:'Shi sets the temporal rule for merits review. The reason is structural: a merits-review tribunal\'s job is to reach the correct or preferable decision on the materials available now, not to reproduce a snapshot of the original decision-maker\'s state of knowledge. The result has practical bite — applicants can put new evidence, supervening events, or reformed circumstances before the ART; the original decision-maker\'s factual base does not bind. Read with Frugtniet (the tribunal stands in the shoes but is bound by the same legal constraints as the original decision-maker) and Drake No 2 (policy-application framework). Together these three cases define the operating rules of merits review.',
         when:'Use Shi whenever the issue on merits review is what evidence the tribunal can consider — particularly when there is supervening evidence, changed circumstances, or new material that did not exist at the time of the original decision.',
         howApply:[
           'Confirm the proceeding is merits review (ART), not JR — Shi is a merits-review timing rule.',
           'Identify the temporal frame: the tribunal decides on the material before it at the time of its own decision, not the original decision date.',
           'Marshal supervening evidence — events post-dating the original decision are admissible (subject to statute).',
           'Watch for any contrary statutory direction — a specific Act may freeze the temporal frame at the original decision (rare).',
           'Pair with Frugtniet: Shi expands the evidentiary base, Frugtniet still constrains it by the original decision-maker\'s legal limits.'
         ],
         issue:'Whether the AAT, on review of MARA\'s cancellation of a migration agent\'s registration, could decide on evidence about Mr Shi\'s conduct that post-dated MARA\'s original decision.',
         conclusion:'Yes — the AAT was entitled to decide on the material before it at the time of its own decision, including supervening evidence about reform of conduct.',
         keywords:['stand in the shoes','contemporaneous','new evidence','merits review timing'],
         facts:'A migration agent had his registration cancelled by MARA. On AAT review he put forward evidence of post-decision conduct showing reform. The question was whether the AAT could consider that supervening material.'},
    kr:{ rule:'실체심사에서 tribunal은 원 결정자의 "신발을 신고", 원 결정 시점이 아니라 tribunal 결정 시점의 자료로 판단한다. 따라서 원 결정 이후의 사건이나 증거도 고려할 수 있다 — 다른 법령상 지시가 없는 한. 2024년 개편 이후 ART에도 그대로 이어진다.',
         principle:'Shi는 실체심사의 시간 규칙을 정한 판결이다. 구조적 이유 — 실체심사 tribunal의 임무는 지금 입수 가능한 자료로 정확 또는 선호되는 결정에 이르는 것이지, 원 결정자의 지식 상태를 스냅샷으로 재현하는 것이 아니다. 실무적 효과가 크다 — 신청인이 새 증거, 후속 사건, 개선된 상황을 ART 앞에 내놓을 수 있고, 원 결정자의 사실 기반에 묶이지 않는다. Frugtniet(tribunal이 신발을 신지만 원 결정자와 같은 법적 제약에 묶임)과 Drake No 2(정책 적용 framework)와 함께 읽는다. 이 셋이 실체심사의 운영 규칙을 정의한다.',
         when:'실체심사의 쟁점이 tribunal이 어떤 증거를 고려할 수 있는가일 때 — 특히 원 결정 시점에 존재하지 않던 후속 증거, 변경된 상황, 새 자료가 있을 때 — 인용한다.',
         howApply:[
           '절차가 실체심사(ART)이지 JR이 아닌지 확인한다 — Shi는 실체심사 시간 규칙이다.',
           '시간 틀을 식별한다: tribunal은 자기 결정 시점의 자료로 판단하지, 원 결정 일자에 묶이지 않는다.',
           '후속 증거를 모은다 — 원 결정 이후의 사건도 증거로 가능(법령 한도 내).',
           '반대되는 법령상 지시를 확인한다 — 특정 법이 시간 틀을 원 결정으로 고정할 수 있다(드물다).',
           'Frugtniet과 짝짓는다 — Shi가 증거 기반을 확장하지만, Frugtniet은 원 결정자의 법적 한계로 여전히 제약한다.'
         ],
         issue:'AAT가 MARA의 이민 대리인 등록 취소를 재심사하면서, MARA 원 결정 이후의 Shi씨 행위에 관한 증거로 판단할 수 있는가.',
         conclusion:'그렇다 — AAT는 자기 결정 시점의 자료로 판단할 수 있고, 행위 개선에 관한 후속 증거도 포함된다.',
         keywords:['신발을 신음','동시점','새 증거','실체심사 시점'],
         facts:'한 이민 대리인이 MARA에 의해 등록이 취소됐다. AAT 재심사에서 그는 행위 개선을 보여 주는 후속 증거를 제출했다. AAT가 그 후속 자료를 고려할 수 있는지가 쟁점이었다.'}},
  frugtniet:{
    id:'frugtniet', name:'Frugtniet v Australian Securities and Investments Commission', cite:'[2019] HCA 16; (2019) 266 CLR 250', icon:'⊝', color:'c-coral',
    topic:'W11', category:'Case',
    en:{ rule:'A merits-review tribunal stands in the shoes of the original decision-maker but is bound by the same legal constraints — it cannot lawfully consider material that the original decision-maker was prohibited from considering. So if the empowering Act (or another statute like the Crimes Act\'s spent-convictions regime) excludes a category of material from the original decision-maker, that exclusion carries through to the tribunal on review.',
         principle:'Frugtniet is the legal-constraint counterpart to Shi\'s evidentiary-expansion rule. Shi expanded what the tribunal can look at temporally; Frugtniet contains it by the legal limits that bound the original decision-maker. The point is that "stand in the shoes" cuts both ways — the tribunal acquires the same powers and the same restrictions. The decision protects regimes like spent convictions, statutory privileges, and statutorily-excluded material from being smuggled back in by route of merits review. Read with Shi (temporal) and Drake No 2 (policy) for the full operating rules of merits review.',
         when:'Use Frugtniet whenever a merits-review applicant or respondent wants to rely on material that the original decision-maker was not permitted to consider. It is the case that says "no — the tribunal stands in the shoes of the original decision-maker, including their legal constraints".',
         howApply:[
           'Identify the material in question and the legal constraint that excluded it from the original decision-maker (e.g. spent-convictions regime, statutory privilege, specific evidentiary exclusion).',
           'Apply Frugtniet: the tribunal is bound by the same constraints as the original decision-maker.',
           'Distinguish from Shi: Shi expands the temporal frame for material that was lawfully available; Frugtniet limits the legal universe.',
           'Together: the tribunal can consider current, supervening, lawful material (Shi) — but not material that was statutorily off-limits to the original decision-maker (Frugtniet).',
           'Carry the same logic forward to ART under the 2024 reforms.'
         ],
         issue:'Whether the AAT, on review of an ASIC banning order, could rely on the applicant\'s spent criminal convictions — material the Crimes Act spent-convictions regime had excluded from ASIC\'s consideration.',
         conclusion:'No — the AAT was bound by the same legal constraints as ASIC. The spent convictions remained excluded on review.',
         keywords:['same constraints','spent convictions','stand in shoes','legal limits'],
         facts:'ASIC made a banning order against Mr Frugtniet. On AAT review the AAT relied on his spent criminal convictions — material that, under the spent-convictions regime in the Crimes Act, ASIC itself could not lawfully consider.'},
    kr:{ rule:'실체심사 tribunal은 원 결정자의 신발을 신지만 같은 법적 제약에도 묶인다 — 원 결정자가 고려할 수 없었던 자료를 tribunal도 적법하게 고려할 수 없다. 즉 수권법(또는 Crimes Act의 만료 유죄 체계 같은 다른 법)이 원 결정자에게 어떤 범주의 자료를 배제했다면, 그 배제는 재심사에서도 그대로 이어진다.',
         principle:'Frugtniet은 Shi의 증거 확장 규칙에 대응하는 법적 제약 짝이다. Shi가 tribunal이 시간적으로 볼 수 있는 범위를 넓혔다면, Frugtniet은 원 결정자를 묶었던 법적 한계로 그것을 다시 가둔다. 요점은 "신발을 신는다"가 양방향이라는 점 — tribunal은 같은 권한과 같은 제약을 함께 얻는다. 만료 유죄, 법령상 특권, 법령으로 배제된 자료 같은 체계가 실체심사를 통해 우회되어 다시 들어오는 것을 막는다. Shi(시간), Drake No 2(정책)와 함께 실체심사의 완전한 운영 규칙을 이룬다.',
         when:'실체심사 신청인이나 피고가 원 결정자가 고려할 수 없었던 자료에 의존하고 싶어할 때 인용한다. "tribunal은 원 결정자의 법적 제약까지 함께 신는다"는 답이 되는 판례.',
         howApply:[
           '문제된 자료와 그것을 원 결정자에게 배제했던 법적 제약을 식별한다(예: 만료 유죄 체계, 법령상 특권, 특정 증거 배제).',
           'Frugtniet을 적용한다: tribunal은 원 결정자와 같은 제약에 묶인다.',
           'Shi와 distinguishing: Shi는 적법하게 입수 가능한 자료의 시간 틀을 넓힌다; Frugtniet은 법적 우주를 제한한다.',
           '둘을 합치면: tribunal은 현재의, 후속의, 적법한 자료를 고려할 수 있다(Shi) — 다만 원 결정자에게 법령으로 닫혀 있던 자료는 안 된다(Frugtniet).',
           '2024년 개편 이후 ART에도 같은 논리를 그대로 가져간다.'
         ],
         issue:'AAT가 ASIC의 금지명령을 재심사하면서, Crimes Act의 만료 유죄 체계가 ASIC에게 배제했던 신청인의 만료 유죄에 의존할 수 있는가.',
         conclusion:'아니다 — AAT는 ASIC와 같은 법적 제약에 묶인다. 만료 유죄는 재심사에서도 배제된 채로 남는다.',
         keywords:['같은 제약','만료 유죄','신발을 신음','법적 한계'],
         facts:'ASIC가 Frugtniet에게 금지명령을 했다. AAT 재심사에서 AAT가 그의 만료 유죄에 의존했지만 — Crimes Act의 만료 유죄 체계 아래 ASIC 자체가 적법하게 고려할 수 없었던 자료였다.'}},
  drake:{
    id:'drake', name:'Drake v Minister for Immigration and Ethnic Affairs (No 2)', cite:'(1979) 2 ALD 634', icon:'☷', color:'c-ochre',
    topic:'W11', category:'Case',
    en:{ rule:'A merits-review tribunal should generally apply lawful Ministerial policy in the interests of consistency and predictability — but it must not abdicate its independent function. Policy is a relevant consideration to be weighed, not a binding rule that displaces the tribunal\'s own judgment. The tribunal can depart from policy where there are cogent reasons to do so on the facts of the particular case. Brennan J\'s framework continues to govern ART decision-making after the 2024 reforms.',
         principle:'Drake No 2 calibrates the relationship between merits-review tribunals and executive policy. The structural problem: applying policy uniformly promotes equal treatment but risks turning the tribunal into a rubber stamp; departing freely from policy promotes individual justice but risks inconsistency and political tension. Brennan J\'s solution — apply policy as a presumption, but reserve room for departure on cogent reasons — has held up for forty-plus years and crosses into the ART era. Read with Shi (temporal) and Frugtniet (legal limits) for the operating rules of merits review.',
         when:'Use Drake No 2 whenever the issue is how a merits-review tribunal should treat published Ministerial policy — particularly where the applicant\'s case looks unusual or sympathetic compared to the policy default.',
         howApply:[
           'Identify the relevant Ministerial policy and confirm it is lawful (within power, no inconsistency with statute).',
           'The tribunal\'s starting point is to apply the policy — promotes consistency and predictability across like cases.',
           'Test for cogent reasons to depart on the particular facts — is there something genuinely distinctive about this case that puts it outside the policy\'s rationale?',
           'If yes, depart with reasons that explain why this case warrants a different result.',
           'If no, apply the policy and reach the result it indicates.',
           'Carry the same logic forward to the ART under the 2024 reforms — the doctrine survives the institutional rebadging.'
         ],
         issue:'Whether the AAT, on re-hearing Drake\'s deportation case, should apply the published Ministerial policy on deportation unless cogent reasons existed not to.',
         conclusion:'Yes — apply lawful policy as a presumption in the interests of consistency, but preserve the tribunal\'s independent judgment to depart on cogent reasons in the particular case.',
         keywords:['Brennan policy framework','consistency','independence','ART'],
         facts:'Mr Drake\'s deportation was re-heard before the AAT (President Brennan J presiding) after an earlier appeal. The question was how the tribunal should treat the published Ministerial deportation policy.'},
    kr:{ rule:'실체심사 tribunal은 일관성과 예측 가능성 차원에서 일반적으로 적법한 장관 정책을 적용해야 하지만, 독립 기능을 포기해선 안 된다. 정책은 가중치 매겨야 할 고려사항이지, tribunal의 자체 판단을 대체하는 구속 규칙이 아니다. 개별 사실관계에 비추어 정책에서 벗어날 설득력 있는 사유가 있다면 그렇게 할 수 있다. Brennan J의 framework는 2024년 개편 이후 ART 의사결정에도 계속 적용된다.',
         principle:'Drake No 2는 실체심사 tribunal과 행정 정책의 관계를 보정한다. 구조적 문제 — 정책을 일률 적용하면 평등 대우는 촉진되지만 tribunal이 도장 찍는 기관이 될 위험; 정책에서 자유롭게 벗어나면 개별 정의는 살지만 일관성·정치적 긴장을 잃는다. Brennan J의 해법 — 정책을 추정으로 적용하되 설득력 있는 사유에 대한 예외 여지를 둠 — 은 40년 넘게 살아남아 ART 시대로 넘어왔다. Shi(시간), Frugtniet(법적 한계)와 함께 실체심사의 운영 규칙을 이룬다.',
         when:'실체심사 tribunal이 공개된 장관 정책을 어떻게 다루어야 하는가 — 특히 신청인의 사건이 정책 기본값에 비해 특이하거나 동정적으로 보일 때 — 인용한다.',
         howApply:[
           '관련 장관 정책을 식별하고 그것이 적법한지(권한 내, 법령과 모순 없음) 확인한다.',
           'Tribunal의 출발점은 정책 적용 — 유사 사건들 사이의 일관성과 예측 가능성을 촉진한다.',
           '개별 사실에서 정책에서 벗어날 설득력 있는 사유를 검토한다 — 이 사건에 정책의 합리적 근거 밖에 놓는 진정한 특이점이 있는가.',
           '있다면 — 왜 이 사건이 다른 결과를 받을 자격이 있는지 설명하는 이유와 함께 — 벗어난다.',
           '없다면 — 정책을 적용하고 그것이 가리키는 결과에 도달한다.',
           '2024년 개편 이후 ART에도 같은 논리를 그대로 가져간다 — 이 법리는 제도적 이름 바꾸기에서 살아남았다.'
         ],
         issue:'AAT가 Drake의 추방 사건을 재심리하면서 공개된 장관 추방 정책을 설득력 있는 사유 없는 한 적용해야 하는가.',
         conclusion:'그렇다 — 일관성 차원에서 적법한 정책을 추정으로 적용하되, 개별 사건에서 설득력 있는 사유에 따라 벗어날 tribunal의 독립적 판단을 보존한다.',
         keywords:['Brennan 정책 framework','일관성','독립성','ART'],
         facts:'Drake의 추방이 항소 이후 AAT(Brennan J 주재)에서 재심리됐다. tribunal이 공개된 장관 추방 정책을 어떻게 다뤄야 하는지가 쟁점이었다.'}},
  m70:{
    id:'m70', name:'Plaintiff M70/2011 v Minister for Immigration and Citizenship', cite:'[2011] HCA 32; (2011) 244 CLR 144', icon:'⊕', color:'c-blue',
    topic:'W8', category:'Case',
    en:{ rule:'Where a statute conditions a Ministerial declaration on an objective state of affairs in the world — for example, that a country provides specified legal protections to refugees — the existence of those protections is a jurisdictional fact. The High Court determines whether the criteria are met for itself, on the evidence; the Minister\'s view does not receive deference even when the question is large in scale and politically charged.',
         principle:'M70 applied Enfield\'s jurisdictional-fact doctrine to a major Commonwealth policy decision (the "Malaysia Solution"). The case stands for two propositions:\n(1) jurisdictional-fact doctrine has bite even at the highest political stakes — courts will independently assess complex factual conditions on power\n(2) statutory protections framed as preconditions are read substantively, not as mere matters of opinion. The case is the leading example of jurisdictional-fact analysis applied at scale, and pairs with Enfield (the doctrinal source) and SZMDS (the subjective state-of-mind variant).',
         when:'Use M70 when a Cth Ministerial decision turns on whether a complex objective state of affairs exists — country conditions, levels of protection, structural facts about a regulated industry. It is the case that confirms court independence on objective JFs even at scale.',
         howApply:[
           'Identify the empowering provision and the objective fact it conditions the power on (e.g. country must provide certain refugee protections).',
           'Argue that the precondition is a jurisdictional fact under Enfield — its truth is essential for the power to arise.',
           'Court determines the question for itself on the evidence; the Minister\'s political assessment receives no deference.',
           'Marshal the evidence carefully — for objective JFs at scale (country conditions, structural facts) you need to put primary evidence before the court.',
           'JF errors are always-JE — no materiality limb. Remedy: invalidity of the declaration / decision, with consequential relief.'
         ],
         issue:'Whether Malaysia satisfied the statutory preconditions in s 198A of the Migration Act for declaration as a third country to which asylum seekers could be transferred for processing.',
         conclusion:'No — the statutory criteria (including provision of specified legal protections) were jurisdictional facts and were not met on the evidence. The declaration was invalid.',
         keywords:['objective JF','Ministerial declaration','court determines','Malaysia Solution'],
         facts:'The Commonwealth proposed to transfer asylum seekers to Malaysia for processing under the so-called "Malaysia Solution". The transfer required a Ministerial declaration under s 198A of the Migration Act 1958 (Cth), which was conditioned on Malaysia providing certain specified legal protections.'},
    kr:{ rule:'법령이 장관 선언을 세상의 객관적 사실 상태에 — 예컨대 어떤 국가가 난민에게 특정 법적 보호를 제공한다는 사실에 — 조건 지운 경우, 그 보호의 존재 여부는 관할권적 사실이다. High Court가 증거로 그 기준 충족 여부를 직접 판단하며, 그 질문이 큰 규모이거나 정치적으로 민감하더라도 장관의 견해는 deference 받지 않는다.',
         principle:'M70은 Enfield의 관할권적 사실 법리를 영연방의 주요 정책 결정("Malaysia Solution")에 적용한 판결이다. 두 명제를 세웠다:\n(1) 관할권적 사실 법리는 정치적 부담이 가장 큰 자리에서도 무게가 있다 — 법원이 권한에 붙은 복잡한 사실 조건을 독립적으로 평가한다\n(2) 전제로 짜인 법령상 보호는 단순한 의견의 문제가 아니라 실체적으로 해석된다. 이 판결은 대규모로 적용된 관할권적 사실 분석의 선도 예시이며, Enfield(교리적 원천), SZMDS(주관적 state-of-mind 변형)와 짝짓는다.',
         when:'영연방 장관 결정이 복잡한 객관적 사실 상태의 존재 여부에 달려 있을 때 — 국가 상황, 보호 수준, 규제 산업의 구조적 사실 — 인용한다. 큰 규모의 객관적 JF에서도 법원의 독립성을 확인한 판례.',
         howApply:[
           '수권조항과 그것이 권한을 조건 지운 객관적 사실을 식별한다(예: 국가가 특정 난민 보호를 제공해야 함).',
           '그 전제가 Enfield하의 관할권적 사실임을 주장한다 — 그 사실이 진실이어야 권한이 발생한다.',
           '법원이 증거로 직접 판단한다; 장관의 정치적 평가는 deference 받지 않는다.',
           '증거를 면밀히 준비한다 — 큰 규모의 객관적 JF(국가 상황, 구조적 사실)에는 일차 증거를 법원 앞에 내놓아야 한다.',
           'JF 오류는 always-JE — materiality 단계 없음. 구제: 선언·결정 무효, 부수적 구제 동반.'
         ],
         issue:'말레이시아가 망명 신청자들을 처리 목적으로 이송할 제3국으로 선언되기 위한 Migration Act s 198A의 법정 전제를 충족했는가.',
         conclusion:'아니다 — 법정 기준(특정 법적 보호 제공 포함)은 관할권적 사실이었고, 증거에서 충족되지 않았다. 선언은 무효.',
         keywords:['객관적 JF','장관 선언','법원 직접 판단','Malaysia Solution'],
         facts:'영연방이 이른바 "Malaysia Solution" 아래에서 망명 신청자들을 처리 목적으로 말레이시아로 이송하려 했다. 이송에는 Migration Act 1958 (Cth) s 198A의 장관 선언이 필요했고, 그 선언은 말레이시아가 특정 법적 보호를 제공한다는 점을 조건으로 했다.'}},
  wednesbury:{
    id:'wednesbury', name:'Associated Provincial Picture Houses Ltd v Wednesbury Corporation', cite:'[1947] EWCA Civ 1; [1948] 1 KB 223', icon:'☼', color:'c-gray',
    topic:'W8', category:'Case',
    en:{ rule:'(UK, 1948) A decision is unreasonable only where it is "so unreasonable that no reasonable authority could ever come to it" — the original, very high threshold for unreasonableness review. The test was meant to be a final-resort safety net, not a workable mainstream ground. Reformulated in Australia by Li, which lowered the bar to "lacks evident and intelligible justification".',
         principle:'Wednesbury is the historical origin of unreasonableness review. In Australia the substantive test now runs through Li/Stretton/DUA16, which explicitly softened the Wednesbury formulation. Wednesbury still appears as the citation point for the doctrine\'s origin and as the contrast against which Li is read.',
         when:'Cite Wednesbury as the historical anchor for unreasonableness review, or as the threshold to contrast with Li\'s modern reformulation. For substantive unreasonableness arguments today, run Li (not Wednesbury) as the operative test.',
         howApply:[
           'Cite Wednesbury for the proposition\'s origin and historical formulation.',
           'For modern substantive review, switch to Li (evident and intelligible justification) — Wednesbury\'s "no reasonable authority" formulation is too narrow.',
           'For delegated legislation, Kruse + Wednesbury baseline can still apply; for substantive merits decisions, use Li/Stretton.'
         ],
         issue:'Whether a local council\'s licensing condition prohibiting under-15s from cinema on Sundays was unreasonable.',
         conclusion:'No — the condition was within power and not so unreasonable that no reasonable authority could have made it.',
         keywords:['original threshold','very high','reformulated','origin'],
         facts:'A cinema sought a licence and the council imposed a condition prohibiting attendance by under-15s on Sundays. The cinema challenged the condition as unreasonable.'},
    kr:{ rule:'(영국, 1948) 결정은 "어떤 합리적 행정청도 도달할 수 없을 정도로 비합리적"인 경우에만 unreasonable이다 — 비합리성 심사의 원조, 매우 높은 문턱. 일상적 사유가 아니라 마지막 안전망으로 의도된 기준. 호주는 Li에서 이를 재정식화해 "명확하고 이해 가능한 정당화의 결여"로 문턱을 낮췄다.',
         principle:'Wednesbury는 비합리성 심사의 역사적 기원이다. 호주에서 실체적 기준은 이제 Li/Stretton/DUA16을 거치며, 이들이 Wednesbury 정식을 명시적으로 완화했다. Wednesbury는 여전히 그 법리의 기원 인용점, Li를 읽기 위한 대조점으로 등장한다.',
         when:'비합리성 심사의 역사적 닻으로, 또는 Li의 현대적 재정식화와 대조하는 문턱으로 인용한다. 오늘날 실체적 비합리성 주장에는 Wednesbury가 아니라 Li를 운영적 기준으로 돌린다.',
         howApply:[
           '명제의 기원과 역사적 정식으로 Wednesbury를 인용한다.',
           '현대 실체적 심사에서는 Li("명확하고 이해 가능한 정당화")로 갈아탄다 — Wednesbury의 "어떤 합리적 행정청도" 정식은 너무 좁다.',
           '위임입법에는 Kruse + Wednesbury 기본선이 여전히 적용 가능; 실체적 본안 결정에는 Li/Stretton.'
         ],
         issue:'지방 카운슬이 영화관 면허에 부과한 일요일 15세 미만 입장 금지 조건이 unreasonable한가.',
         conclusion:'아니다 — 그 조건은 권한 내였고, 어떤 합리적 행정청도 만들 수 없을 정도로 비합리적이지는 않았다.',
         keywords:['원조 문턱','매우 높음','재정식화','기원'],
         facts:'한 영화관이 면허를 신청했고, 카운슬이 일요일 15세 미만의 입장을 금지하는 조건을 부과했다. 영화관이 그 조건을 unreasonable로 다툰 사건.'}},
  northcoast:{
    id:'northcoast', name:'North Coast Environment Council Inc v Minister for Resources', cite:'(1994) 55 FCR 492', icon:'⌘', color:'c-forest',
    topic:'W9', category:'Case',
    en:{ rule:'For an established environmental advocacy organisation, special-interest standing can be inferred from a combination of practical indicators: long-standing involvement in the subject area, government recognition (e.g. statutory consultation status), prior consultation by the relevant agency, and dedicated advocacy work. The standing inquiry is functional — these indicators show the group is more than a member of the public.',
         principle:'NCEC extended ACF\'s "special interest" baseline to recognised environmental NGOs. The case is the leading authority for organisational standing where the body is well-established and government-recognised.',
         when:'Use NCEC for standing arguments by established environmental or advocacy NGOs. Compare ACF (where the same body had earlier failed) — NCEC turned on the practical indicators of recognition and engagement.',
         howApply:[
           'Establish the body\'s status: long-standing involvement, prior consultations, statutory recognition.',
           'Argue these practical indicators add up to "special interest" beyond the general public.',
           'Distinguish ACF on the facts — by 1994 the same kind of body had a stronger basis for special interest than the 1980 Foundation did.'
         ],
         issue:'Whether the North Coast Environment Council had standing to challenge the Minister\'s grant of a wood-chip export licence to Boral.',
         conclusion:'Yes — NCEC was an established environmental group with government recognition and prior consultation; standing was made out.',
         keywords:['prior involvement','recognition','environmental','organisational'],
         facts:'NCEC, an established environmental advocacy group, sought to challenge the Minister\'s wood-chip export licence granted to Boral. NCEC pointed to its long history of engagement with environmental issues and prior consultation by relevant agencies.'},
    kr:{ rule:'기성 환경 옹호 단체의 경우, special interest standing은 실무적 지표의 조합에서 추론할 수 있다 — 그 분야에서의 장기 활동, 정부의 인정(예: 법령상 협의 지위), 관련 기관의 사전 협의, 전담 옹호 활동. Standing 분석은 기능적이다 — 이 지표들이 그 단체가 일반 시민 이상임을 보여 준다.',
         principle:'NCEC는 ACF의 "special interest" 기본선을 인정받은 환경 NGO로 확장했다. 잘 자리잡고 정부에서 인정받은 단체의 조직적 standing에 관한 선도 판례.',
         when:'기성 환경·옹호 NGO의 standing 주장에 인용한다. ACF와 비교 — 같은 종류의 단체가 거기서는 실패했지만, NCEC는 인정과 관여의 실무적 지표에서 갈렸다.',
         howApply:[
           '단체의 지위를 입증한다 — 장기 활동, 사전 협의, 법령상 인정.',
           '이 실무적 지표들이 일반 시민을 넘는 "special interest"로 합쳐짐을 주장한다.',
           '사실관계로 ACF와 distinguishing — 1994년에는 같은 종류의 단체가 1980년 Foundation보다 special interest의 더 강한 근거를 가졌다.'
         ],
         issue:'North Coast Environment Council이 장관의 Boral wood-chip 수출 면허 부여를 다툴 standing을 갖는가.',
         conclusion:'그렇다 — NCEC는 정부 인정과 사전 협의가 있는 기성 환경단체였다. Standing 인정.',
         keywords:['사전 관여','인정','환경','조직적'],
         facts:'기성 환경 옹호 단체 NCEC가 장관이 Boral에 부여한 wood-chip 수출 면허를 다투려 했다. NCEC는 환경 문제 관여의 오랜 역사와 관련 기관의 사전 협의를 근거로 들었다.'}},

  /* ─── 2026 추가: 자료에서 인용된 핵심 보조 판례들 ──── */

  mceldowney: {
    id:'mceldowney', name:'McEldowney v Forde', cite:'[1969] 2 All ER 1039 (NI HL)', icon:'⚖', color:'c-blue',
    topic:'W1', category:'Case',
    en:{ rule:'The three-step "straitjacket test" for validity of subordinate legislation:\n(1) construe the empowering Act\n(2) construe the subordinate legislation\n(3) determine whether the subordinate legislation falls within the authorising scope.',
         principle:'McEldowney supplies the methodological backbone for delegated-legislation challenges. It tells you HOW to check validity but not what substantive grounds (proportionality, legality principle, unreasonableness) apply — those come from later Australian authorities. Always cite McEldowney to set up the framework, then layer Vanstone (proportionality) and Evans (legality) onto it.',
         when:'Frame any delegated-legislation challenge: lay out the McEldowney three steps, then apply the substantive grounds.',
         howApply:[
           'Step 1 — interpret the empowering Act (purpose, scheme, text).',
           'Step 2 — interpret the regulation/determination itself (what does it actually do, in what practical reach?).',
           'Step 3 — compare and decide whether the instrument fits within the authorising scope; if not, identify the substantive ground (proportionality / legality / unreasonableness / improper purpose).'
         ],
         issue:'How should a court assess whether a piece of subordinate legislation is within the authorising power.',
         conclusion:'Three-step analytical framework — empowering Act → instrument → fit. Universally adopted in Australian delegated-legislation review.',
         keywords:['straitjacket test','three-step framework','delegated legislation'],
         facts:'House of Lords decision concerning the validity of Northern Ireland subordinate legislation; Diplock LJ articulated the framework now standard in Australia.'},
    kr:{ rule:'위임입법 유효성의 3단계 "straitjacket test":\n(1) 수권법을 해석한다 →\n(2) 위임입법을 해석한다 →\n(3) 위임입법이 수권 범위 안에 들어가는지 본다.',
         principle:'McEldowney는 위임입법 다툼의 방법론적 뼈대를 제공한다. 어떻게 유효성을 검증할지를 알려주지만, 어떤 실체적 사유(비례성·합법성·비합리성)를 적용할지는 후속 호주 판례에서 가져와야 한다. 항상 McEldowney로 분석틀을 깔고, 그 위에 Vanstone(비례성), Evans(합법성) 같은 사유를 얹는다.',
         when:'위임입법 다툼의 framing 도구로 인용. 3단계를 깐 다음 실체적 사유를 적용한다.',
         howApply:[
           '1단계 — 수권법을 해석한다(목적·체계·문언).',
           '2단계 — 다투어진 규정/결정 자체를 해석한다(실제로 무엇을 하는가, 어디까지 미치는가).',
           '3단계 — 비교해서 그 도구가 수권 범위 안에 들어가는지 본다. 안 들어가면 어떤 실체적 사유(비례성·합법성·비합리성·부적절한 목적)인지 짚는다.'
         ],
         issue:'위임입법이 수권 범위 안에 있는지를 법원이 어떻게 평가해야 하는가.',
         conclusion:'3단계 분석틀 — 수권법 → 규정 → 적합 여부. 호주 위임입법 심사에서 보편적으로 채택됨.',
         keywords:['straitjacket test','3단계 분석틀','위임입법'],
         facts:'영국 상원이 북아일랜드 위임입법의 유효성을 다룬 사건. Diplock LJ가 호주에서 표준이 된 분석틀을 정식화했다.'}},

  hickman: {
    id:'hickman', name:'R v Hickman; Ex parte Fox and Clinton', cite:'(1945) 70 CLR 598', icon:'⚒', color:'c-ochre',
    topic:'W10', category:'Case',
    en:{ rule:'Dixon J\'s impossibility principle, restated three ways: it is impossible for Parliament (i) to impose jurisdictional limits + deprive the HCA of prohibition to enforce them; (ii) to impose a public duty + deprive the HCA of mandamus; (iii) to constrain power + deprive the HCA of injunction. Privative clauses are read as conditions ("Hickman provisos") under which the clause protects — not as power-conferring mechanisms.',
         principle:'Hickman is the constitutional root of s 75(v) entrenchment. Plaintiff S157 confirmed that Hickman is a rule of construction (the three provisos are conditions before any protection applies), NOT a vehicle for expanding decision-maker authority. After S157 the impossibility principle directly underpins Graham\'s substance-and-degree test [46]: any provision that practically defeats s 75(v) enforcement is invalid, not just literal privative clauses.',
         when:'Cite Hickman as the foundational impossibility principle when defending or challenging a privative-type clause; pair with Plaintiff S157 / Kirk / Graham as the modern doctrinal evolution.',
         howApply:[
           'Frame the impossibility principle in the relevant form (prohibition / mandamus / injunction).',
           'Confirm the three Hickman provisos as conditions (bona fide attempt, relating to subject matter, reasonably capable of reference).',
           'Move to the modern framework — S157 (read down), Graham (substance-and-degree practical-impact test).'
         ],
         issue:'Whether a privative clause can effectively oust the HCA\'s s 75(v) supervisory jurisdiction.',
         conclusion:'No — impossibility principle. The clause is read as setting conditions for protection; cannot exclude review for jurisdictional error.',
         keywords:['impossibility principle','privative clause','Hickman provisos','s 75(v) foundation'],
         facts:'War-time industrial regulations contained a privative clause; Dixon J articulated the impossibility principle now central to Australian privative-clause analysis.'},
    kr:{ rule:'Dixon J의 impossibility 원칙, 세 형태로 진술된다 — 의회는 (i) 관할권에 한계를 두면서 동시에 HCA로부터 그 한계를 강제할 prohibition을 빼앗을 수 없다; (ii) 공적 의무를 부과하면서 HCA로부터 mandamus를 빼앗을 수 없다; (iii) 권한 행사를 제약하면서 HCA로부터 injunction을 빼앗을 수 없다. 배제조항은 "Hickman 단서"라는 조건 아래에서 보호가 작동한다는 해석 규칙이지, 권한을 부여하는 도구가 아니다.',
         principle:'Hickman은 s 75(v) 보호의 헌법적 뿌리다. Plaintiff S157이 확인했듯 Hickman은 해석 규칙(보호 적용 전 충족해야 할 세 단서)일 뿐, 결정자 권한 확장 수단이 아니다. S157 이후로 impossibility 원칙은 Graham의 substance-and-degree 기준[46]을 직접 떠받친다 — 형식상 배제조항이 아닌 조항이라도 실질적으로 s 75(v) 강제를 무력화하면 무효.',
         when:'배제 성격의 조항을 방어하거나 다툴 때 impossibility 원칙의 토대로 인용. S157 / Kirk / Graham과 현대 doctrinal evolution으로 함께 묶는다.',
         howApply:[
           'Impossibility 원칙을 해당 형태(prohibition / mandamus / injunction)로 정리한다.',
           'Hickman 세 단서를 보호 적용의 조건으로 확인한다(bona fide 행사 / subject matter / 권한과의 reasonable reference).',
           '현대 분석틀로 넘어간다 — S157(좁게 읽기), Graham(substance-and-degree 실질적 영향 테스트).'
         ],
         issue:'배제조항이 HCA의 s 75(v) 감독관할을 실효적으로 봉쇄할 수 있는가.',
         conclusion:'없다 — impossibility 원칙. 그 조항은 보호 조건으로 읽힐 뿐이며, 관할권적 오류에 대한 심사를 막을 수 없다.',
         keywords:['impossibility 원칙','배제조항','Hickman 단서','s 75(v) 토대'],
         facts:'전시 산업 규정에 들어 있던 배제조항을 다루며, Dixon J가 호주 배제조항 분석의 중심이 된 impossibility 원칙을 정식화했다.'}},

  carltona: {
    id:'carltona', name:'Carltona Ltd v Commissioners of Works', cite:'[1943] 2 All ER 560 (CA)', icon:'⚙', color:'c-gray',
    topic:'W6', category:'Case',
    en:{ rule:'Where a statutory function is multifarious and administrative in character, a Minister may lawfully act through duly authorised departmental officers. This "Carltona principle" rests on administrative necessity and is implied unless the statute requires personal exercise.',
         principle:'Carltona supplies the default rule for ministerial agency. It does NOT apply where (i) the statute expressly requires personal exercise; (ii) the function is a central feature of the statutory scheme (Peko-Wallsend on s 11); or (iii) the statute is structured to require active intellectual engagement (Tickner on s 31(1)).',
         when:'Defend the use of departmental officers in ministerial decision-making; rebut "Minister must have done X personally" arguments.',
         howApply:[
           'Characterise the function — multifarious/administrative or central/judgment-laden?',
           'Check the statute for express personal-exercise requirements or delegation exclusions.',
           'If statute is silent and function is administrative, Carltona supplies implied agency. If statute makes the function central or excludes delegation, Carltona is displaced.'
         ],
         issue:'Whether a Minister can lawfully act through departmental officers in performing statutory functions.',
         conclusion:'Yes, for multifarious administrative functions — implied by administrative necessity.',
         keywords:['Carltona principle','ministerial agency','administrative necessity','delegation'],
         facts:'Wartime requisition decision made by a departmental officer rather than the Minister personally; held lawful given the volume and character of decisions involved.'},
    kr:{ rule:'법령이 부여한 기능이 다양·반복적이고 행정적 성격이라면, 장관은 정당하게 권한받은 부처 공무원을 통해 그 기능을 적법하게 수행할 수 있다. 이 "Carltona 원칙"은 행정적 필요성에 토대를 두며, 법령이 인적 행사(personal exercise)를 요구하지 않는 한 묵시된다.',
         principle:'Carltona는 장관의 대리 행사에 대한 기본 규칙이다. 다만 (i) 법령이 명시적으로 인적 행사를 요구하거나, (ii) 그 기능이 법령 체계의 핵심 특징이거나(Peko-Wallsend의 s 11 분석), (iii) 법령이 적극적 지적 관여를 요구하도록 짜여 있으면(Tickner의 s 31(1)) Carltona는 적용되지 않는다.',
         when:'장관 결정에서 부처 공무원의 활용을 방어하거나 "장관이 직접 했어야 한다"는 주장을 반박할 때 인용.',
         howApply:[
           '기능의 성격을 짚는다 — 다양·반복적 행정 기능인가, 아니면 핵심적·판단 부담이 큰 기능인가.',
           '법령에 인적 행사 요구나 위임 배제가 있는지 확인한다.',
           '법령이 침묵하고 기능이 행정적이라면 Carltona의 묵시적 대리가 작동. 핵심 기능이거나 위임이 배제되어 있다면 Carltona는 밀려난다.'
         ],
         issue:'장관이 법령상 기능 수행을 위해 부처 공무원을 통해 적법하게 행위할 수 있는가.',
         conclusion:'다양한 행정 기능에 대해서는 그렇다 — 행정적 필요성에 의해 묵시됨.',
         keywords:['Carltona 원칙','장관 대리','행정적 필요성','위임'],
         facts:'전시 징발 결정을 장관이 직접이 아닌 부처 공무원이 내린 사건. 결정의 양과 성격을 고려해 적법으로 인정.'}},

  sean: {
    id:'sean', name:'Sean Investments Pty Ltd v MacKellar', cite:'(1981) 38 ALR 363 (FCA)', icon:'⚖', color:'c-gray',
    topic:'W6', category:'Case',
    en:{ rule:'A decision-maker is not required to look behind a statutory report unless the statute so requires. Whether a factor is "bound to be considered" is a matter of statutory construction; weight given to relevant factors is for the decision-maker, not the court.',
         principle:'Sean Investments is the source of Mason J\'s proposition (d) in Peko-Wallsend — the weight-allocation rule. It blocks attempts to dress up disagreements about weight as failure-to-consider grounds. When the real complaint is "the decision-maker should have given X more weight", the proper analytical route is Wednesbury / Li unreasonableness, not relevant considerations.',
         when:'Rebut "failure to consider" arguments that are actually disguised weight challenges; defend administrative reliance on intermediate reports.',
         howApply:[
           'Ask whether the complaint is about whether the factor was considered at all (relevance) or how much weight was given (weight).',
           'If weight: redirect to unreasonableness (Wednesbury / Li).',
           'If consideration: ask whether the statute made the factor mandatory (Peko (b)).'
         ],
         issue:'Whether a decision-maker must independently investigate matters behind a statutory report, and whether weight given to factors is reviewable.',
         conclusion:'Weight is for the decision-maker; court does not look behind the report unless the statute so requires.',
         keywords:['weight allocation','statutory reports','relevance vs weight'],
         facts:'Nursing home fee determination; challenge to weight given to various financial factors. Federal Court rejected the challenge as a disguised merits review.'},
    kr:{ rule:'결정자는 법령이 그렇게 요구하지 않는 한, 법령상 보고서의 배경 자료까지 독자적으로 조사할 의무는 없다. 어떤 요소가 "반드시 고려할 사항"인지는 법령 해석의 문제이며, 관련 요소에 대한 가중치는 법원의 영역이 아니라 결정자의 몫이다.',
         principle:'Sean Investments는 Peko-Wallsend에서 Mason J가 제시한 명제 (d) — 가중치 배분 규칙 — 의 원천이다. 가중치에 대한 이견을 "고려하지 않았다"는 사유로 위장하려는 시도를 막아 준다. "결정자가 X에 더 큰 가중치를 줬어야 한다"가 진짜 불만이라면, 올바른 분석 경로는 관련 고려사항이 아니라 Wednesbury / Li의 비합리성이다.',
         when:'"고려하지 않았다"는 주장이 사실은 가중치 불만일 때 반박; 행정청이 중간 보고서에 의존한 것을 방어할 때 인용.',
         howApply:[
           '불만이 그 요소를 아예 고려하지 않았다는 것(관련성)인지, 가중치(weight)인지를 가른다.',
           '가중치 문제라면 Wednesbury / Li의 비합리성으로 돌린다.',
           '고려 문제라면 그 요소를 법령이 강행으로 만들었는지 본다(Peko 명제 (b)).'
         ],
         issue:'결정자가 법령상 보고서의 배경까지 독자 조사해야 하는지, 그리고 요소에 대한 가중치가 사법심사 대상인지.',
         conclusion:'가중치는 결정자의 몫. 법령이 그렇게 요구하지 않는 한 법원은 보고서 뒤를 들춰보지 않는다.',
         keywords:['가중치 배분','법령상 보고서','관련성 vs 가중치'],
         facts:'요양원 수가 결정에서 여러 재정적 요소에 대한 가중치 부여가 다투어졌고, 연방법원이 그 다툼을 위장된 본안 심사로 보고 기각.'}},

  wushan: {
    id:'wushan', name:'Minister for Immigration and Ethnic Affairs v Wu Shan Liang', cite:'(1996) 185 CLR 259', icon:'☆', color:'c-gray',
    topic:'W6', category:'Case',
    en:{ rule:'Reasons of administrative decision-makers are to be read fairly as a whole, not parsed minutely for error. The court is "not astute to discern error" in such reasons. The proper inquiry is whether the reasons disclose error of substance, not deficiencies of expression.',
         principle:'Wu Shan Liang is the standard defensive citation against minute parsing of administrative reasons. It does not insulate reasons from scrutiny — Tickner/M1 still demand active intellectual engagement — but it prevents technical attacks on phrasing where the substance is sound. Combine with M1/2021 plurality\'s deferential framing.',
         when:'Defend administrative reasons against pedantic scrutiny; rebut "the reasons didn\'t use the right words" arguments.',
         howApply:[
           'Read the reasons as a whole, not as isolated phrases.',
           'Ask whether the reasons disclose substantive error (wrong principle, irrelevant consideration, no logical connection) — not whether better wording was possible.',
           'Limit: where reasons are template / generic / fail to engage with central claims, Wu Shan Liang does not save them (M1/2021 dissents).'
         ],
         issue:'How closely should courts parse administrative reasons for error.',
         conclusion:'Read fairly as a whole; not astute to discern error from infelicities of expression.',
         keywords:['reasons','fair reading','not astute','administrative review'],
         facts:'Refugee Review Tribunal reasons challenged for various phrasings; High Court rejected close parsing and articulated the "not astute" formulation.'},
    kr:{ rule:'행정 결정자의 이유서는 전체로 공정하게 읽어야 하지, 오류를 찾기 위해 미세하게 쪼개 보아서는 안 된다. 법원은 그런 이유에서 "오류를 찾으려고 안달하지 않는다(not astute to discern error)". 진짜 질문은 실질적 오류(잘못된 원칙, 무관한 고려, 논리적 연결 결여)인지이지, 표현의 부족이 아니다.',
         principle:'Wu Shan Liang은 행정 이유서에 대한 미세 분석을 막을 때 인용하는 표준 방어 판례다. 이유서를 심사에서 면제시키는 건 아니다 — Tickner / M1은 여전히 적극적 지적 관여를 요구한다 — 다만 실질이 멀쩡한데 표현에 대한 기술적 공격을 막는다. M1/2021 다수의견의 deferential framing과 같이 쓰면 좋다.',
         when:'행정 이유서를 미세 분석에서 방어할 때; "정확한 표현을 안 썼다"는 공격을 반박할 때 인용.',
         howApply:[
           '이유서를 부분이 아니라 전체로 읽는다.',
           '실질적 오류가 드러나는지 묻는다(잘못된 원칙, 무관 고려, 논리 결여) — 더 나은 표현이 가능했는지가 아니다.',
           '한계 — 이유서가 template / 일반론 / 핵심 청구에 미관여로 흐른다면 Wu Shan Liang이 구해 주지 않는다(M1/2021 반대의견).'
         ],
         issue:'행정 이유서에서 법원이 얼마나 엄격하게 오류를 찾아야 하는가.',
         conclusion:'전체로 공정하게 읽고, 표현의 미숙으로부터 오류를 찾으려 안달하지 않는다.',
         keywords:['이유서','공정한 읽기','not astute','행정심사'],
         facts:'난민심사심판소 이유서의 여러 표현이 다투어졌으나, High Court가 미세 분석을 거부하고 "not astute" 정식을 정립했다.'}},

  sankey: {
    id:'sankey', name:'Sankey v Whitlam', cite:'(1978) 142 CLR 1', icon:'⚖', color:'c-violet',
    topic:'W10', category:'Case',
    en:{ rule:'Under public interest immunity (PII), the court itself weighs the competing public interests in disclosure vs confidentiality; relevant evidence is withheld "only if, and to the extent, that the public interest renders it necessary". The court retains the reserve power to inquire into the nature of the document and require some indication of the injury that disclosure would cause.',
         principle:'Sankey is the PII baseline that Graham distinguishes. PII preserves the court\'s weighing role; s 503A(2)(c) in Graham removed it ("in limine" deprivation). When a Crown counsel argues secrecy by analogy to PII, the answer is: under PII the court still controls disclosure; under the impugned secrecy clause the executive does. That structural difference is what made s 503A(2)(c) invalid.',
         when:'Distinguish a secrecy clause from PII — when the Crown invokes PII as an analogy, identify which side controls the weighing function.',
         howApply:[
           'Under the impugned scheme, who weighs the competing public interests — the court or the executive?',
           'If the court → likely valid (Sankey / Gypsy Jokers pattern).',
           'If the executive → likely invalid as applied to s 75(v) review (Graham pattern).'
         ],
         issue:'The nature and scope of public interest immunity in Australian law.',
         conclusion:'The court — not the executive — balances the competing interests; PII protection is not absolute and admits judicial inquiry into the document.',
         keywords:['public interest immunity','PII','court weighing','disclosure'],
         facts:'Conspiracy proceedings against former Cth Ministers; PII claim over Cabinet documents. High Court emphasised judicial control over the PII determination.'},
    kr:{ rule:'공익면책(PII) 아래에서, 경합하는 공적 이해의 비교형량은 법원 자신이 한다. 관련 증거는 "공익이 그것을 요구하는 한도에서만" 보류된다. 법원은 그 문서의 성격을 조사하고, 공개가 가져올 손해의 성격에 대한 어느 정도의 표시를 요구할 수 있는 reserve power가 있다.',
         principle:'Sankey는 Graham이 구별하는 PII 기본선이다. PII는 법원의 비교형량 역할을 보존한다. Graham에서 s 503A(2)(c)는 이를 제거했다(처음부터 박탈, "in limine"). Crown 측이 PII와의 유사성을 들어 비밀조항을 방어하려 하면, 답은 — PII에서는 법원이 여전히 공개를 통제하고, 다투어진 비밀조항에서는 행정부가 통제한다는 것. 이 구조적 차이가 s 503A(2)(c)를 무효로 만든 핵심이다.',
         when:'비밀조항을 PII와 구별할 때 — Crown이 PII를 유사성으로 들먹이면, 비교형량 기능을 누가 통제하는지 짚는다.',
         howApply:[
           '다투어진 체계에서 경합 공익을 누가 비교형량하는가 — 법원인가, 행정부인가.',
           '법원이면 합헌일 가능성이 높다(Sankey / Gypsy Jokers 패턴).',
           '행정부면 s 75(v) 심사 적용 범위에서 무효일 가능성이 높다(Graham 패턴).'
         ],
         issue:'호주법상 공익면책의 성격과 범위.',
         conclusion:'경합 이해를 비교형량하는 주체는 행정부가 아니라 법원이다. PII 보호는 절대적이지 않으며, 법원의 문서 조사를 허용한다.',
         keywords:['공익면책','PII','법원 비교형량','공개'],
         facts:'전직 영연방 장관들에 대한 공모 소송에서 내각 문서에 대한 PII 청구가 다투어졌고, High Court가 PII 판단에 대한 사법적 통제를 강조했다.'}},

  murphyores: {
    id:'murphyores', name:'Murphyores Incorporated Pty Ltd v Commonwealth', cite:'(1976) 136 CLR 1', icon:'⊕', color:'c-forest',
    topic:'W7', category:'Case',
    en:{ rule:'Ministerial discretions, where their scope and purpose so permit, may take into account broader policy considerations beyond narrow factual or technical criteria. The breadth of admissible considerations is determined by statutory construction.',
         principle:'Murphyores feeds Mason J\'s proposition (e) in Peko-Wallsend: Ministers operate with wider scope for policy considerations than ordinary administrative decision-makers. The case marks the policy-tolerant end of the relevance-norms spectrum, complementing Sean Investments (weight is for the DM). Where a Minister considers macro-policy factors plausibly within statutory purpose, courts will not strike that down as "irrelevant".',
         when:'Defend Ministerial reliance on broad policy considerations; counter "irrelevant consideration" arguments where the Minister has weighed wider policy effects.',
         howApply:[
           'Identify the Ministerial power and the breadth of its discretion (Stretton-type statutory indicators).',
           'Identify the policy considerations in play and link them to the Act\'s purpose.',
           'If the considerations are plausibly within statutory purpose, Murphyores defeats the "irrelevant" challenge.'
         ],
         issue:'Whether broader policy considerations can lawfully inform a Ministerial discretion.',
         conclusion:'Yes — where statutory scope and purpose so permit, policy considerations are admissible.',
         keywords:['Ministerial discretion','policy considerations','broad scope','statutory purpose'],
         facts:'Export-control decision under sand-mining regulations; the Minister took environmental policy considerations into account; held lawful given the discretion\'s breadth.'},
    kr:{ rule:'장관의 재량은, 그 범위와 목적이 허용하는 한, 좁은 사실·기술적 기준을 넘는 더 넓은 정책적 고려사항을 반영할 수 있다. 어떤 고려사항이 허용되는가의 폭은 법령 해석으로 정해진다.',
         principle:'Murphyores는 Peko-Wallsend에서 Mason J 명제 (e)에 양분을 공급한다 — 장관은 일반 행정 결정자보다 정책 고려의 폭이 넓다. 이 판례는 관련 고려사항 스펙트럼의 정책-관용 쪽 끝을 표시하며, Sean Investments(가중치는 결정자 몫)와 짝을 이룬다. 장관이 법령 목적 범위 안의 거시 정책 요소를 형량할 때, 법원은 그것을 "무관한 고려"로 무효화하지 않는다.',
         when:'장관이 광범한 정책 고려에 의존한 것을 방어할 때; 더 넓은 정책 효과를 고려했다는 이유로 "무관한 고려" 주장이 제기될 때 반박.',
         howApply:[
           '장관 권한과 그 재량의 폭을 짚는다(Stretton 식 법령상 지표).',
           '실제로 고려된 정책 사항을 식별하고 법령 목적에 연결한다.',
           '그 고려가 법령 목적 안에 있을 개연성이 있으면 Murphyores가 "무관한 고려" 주장을 물리친다.'
         ],
         issue:'더 넓은 정책 고려가 장관 재량을 적법하게 안내할 수 있는가.',
         conclusion:'그렇다 — 법령 범위와 목적이 허용하는 한 정책 고려는 허용된다.',
         keywords:['장관 재량','정책 고려','넓은 범위','법령 목적'],
         facts:'모래 채광 규정 아래의 수출 통제 결정에서 장관이 환경 정책 고려를 반영한 사건. 재량의 폭에 비추어 적법으로 인정.'}},

  marbury: {
    id:'marbury', name:'Marbury v Madison', cite:'5 US (1 Cranch) 137 (1803)', icon:'★', color:'c-blue',
    topic:'W2', category:'Case',
    en:{ rule:'It is "emphatically the province and duty of the judicial department to say what the law is" (Marshall CJ). Where two laws conflict, courts must decide which controls; this principle ties judicial review to legality and not merits.',
         principle:'Marbury is the constitutional ancestor of s 75(v). Australian framers accepted the Marbury principle (Fullagar J in the Communist Party Case: "axiomatic") but wanted to avoid the actual outcome (where the US Supreme Court held it lacked statutory mandamus power). The drafting answer was s 75(v) — direct constitutional conferral of writ jurisdiction. Cite Marbury for the rule-of-law foundation in any s 75(v) / Graham / Plaintiff S157 argument.',
         when:'Constitutional / rule-of-law arguments; foundational grounding for the legality-merits distinction; conceptual ancestor of s 75(v).',
         howApply:[
           'Establish the Marbury principle — courts say what the law is.',
           'Link to Australian acceptance (Communist Party Case — Dixon J on rule of law; Fullagar J on Marbury as axiomatic).',
           'Apply to the specific entrenchment argument (S157 / Kirk / Graham).'
         ],
         issue:'Whether US courts had power to issue mandamus against an executive officer absent constitutional authority.',
         conclusion:'Courts can declare an Act unconstitutional but cannot exceed their own constitutional grants. Foundational statement of judicial review and the legality / merits divide.',
         keywords:['judicial review','rule of law','legality vs merits','constitutional foundation'],
         facts:'US Supreme Court refused to issue mandamus to enforce a judicial commission, holding that Congress had purported to expand the Court\'s original jurisdiction beyond what the Constitution permitted.'},
    kr:{ rule:'법이 무엇인지 말하는 것은 "단연 사법부의 영역이자 의무"이다(Marshall CJ). 두 법이 충돌할 때 어느 것이 지배하는지를 정하는 것은 법원의 일이다. 이 원칙이 사법심사를 적법성에 묶고, 본안과 분리시킨다.',
         principle:'Marbury는 s 75(v)의 헌법적 조상이다. 호주 헌법 기초자들은 Marbury 원칙을 받아들였지만(Communist Party Case의 Fullagar J: "axiomatic"), 실제 결말(미국 대법원이 법정 mandamus 권한이 없다고 판시한 결과)을 피하고 싶었다. 그 입법적 해결책이 s 75(v) — writ 관할의 헌법적 직접 부여다. 어떤 s 75(v) / Graham / Plaintiff S157 주장에서도 법치 토대로 Marbury를 인용한다.',
         when:'헌법적·법치적 논증에서; 적법성·본안 구분의 토대; s 75(v)의 개념적 조상.',
         howApply:[
           'Marbury 원칙을 정리한다 — 법이 무엇인지 말하는 것은 법원이다.',
           '호주의 수용을 연결한다(Communist Party Case — Dixon J의 법치, Fullagar J의 Marbury axiomatic).',
           '구체적 보호 논증(S157 / Kirk / Graham)에 적용한다.'
         ],
         issue:'미국 법원이 헌법적 권한 없이 행정 공무원에게 mandamus를 발부할 권한이 있는가.',
         conclusion:'법원은 법률을 위헌으로 선언할 수 있지만, 헌법이 부여한 자기 권한을 넘을 수는 없다. 사법심사와 적법성·본안 구분의 토대적 진술.',
         keywords:['사법심사','법치','적법성 vs 본안','헌법적 토대'],
         facts:'미국 대법원이 사법위원 임명 강제 mandamus 발부를 거부하면서, 의회가 헌법이 허용한 원시 관할을 넘어 확장하려 했다고 판시한 사건.'}},

  chk16: {
    id:'chk16', name:'CHK16 and DUA16 v Minister for Immigration and Border Protection', cite:'[2019] FCAFC 192', icon:'⚠', color:'c-coral',
    topic:'W8', category:'Case',
    en:{ rule:'The IAA is generally NOT obliged to seek further information from an applicant. BUT in "extreme circumstances", failure to exercise that procedural power may be legally unreasonable. The four factors are: (i) the IAA was aware of the problem; (ii) correction was a simple matter; (iii) consequences for the applicant were grave; (iv) the information was readily ascertainable and of critical significance (SZIAI).',
         principle:'CHK16 is the operative case for the extreme-circumstances exception to "no duty to inquire". Pair it with DUA16 — same court, same agent, same statute, opposite results. CHK16 (entire submission was another person\'s circumstances) → unreasonable. DUA16 (partial mistake, IAA reasonably disregarded) → not unreasonable. The discriminator is the four-factor extreme-circumstances test.',
         when:'Procedural non-exercise arguments — failure to invite, failure to inquire, failure to correct an obvious problem.',
         howApply:[
           'Start from the default (DUA16 [27] — IAA not generally obliged to inquire).',
           'Apply the four extreme-circumstances factors — was the IAA aware, was correction simple, was the result grave, was the info readily ascertainable + critical?',
           'If all four met → extreme → unreasonable (CHK16 outcome). If some missing → not extreme (DUA16 outcome).'
         ],
         issue:'When does failure to exercise the IAA\'s procedural power to obtain new information amount to legal unreasonableness.',
         conclusion:'CHK16: extreme circumstances met (entire submission about a different person) → unreasonable. DUA16: partial mistake → not unreasonable.',
         keywords:['extreme circumstances','procedural non-exercise','SZIAI','IAA','migration agent fraud'],
         facts:'Both applicants had submissions affected by migration agent misconduct: CHK16\'s entire submission was a different person\'s circumstances; DUA16\'s contained some irrelevant paragraphs. The Full Federal Court reached opposite conclusions on the same legal standard.'},
    kr:{ rule:'IAA는 일반적으로 신청인에게 추가 정보를 구할 의무가 없다. 그러나 "extreme circumstances"에서는 그 절차적 권한을 행사하지 않은 것이 법적으로 비합리적일 수 있다. 4가지 요소는 — (i) IAA가 문제를 알고 있었나, (ii) 시정이 simple matter였나, (iii) 신청인에게 결과가 grave했나, (iv) 정보가 readily ascertainable이고 critical significance였나(SZIAI).',
         principle:'CHK16은 "조회 의무 없음"의 extreme-circumstances 예외를 운영하는 핵심 판례다. DUA16과 짝지어 본다 — 같은 법원, 같은 이민 대리인, 같은 법령, 정반대 결과. CHK16(제출 전체가 다른 사람의 사정) → 비합리. DUA16(부분적 실수, IAA가 합리적으로 무시) → 비합리 아님. 4-factor 테스트가 가르는 선.',
         when:'절차적 권한 미행사 주장 — 초청 거부, 조사 거부, 명백한 문제 미시정 등.',
         howApply:[
           '기본값에서 출발한다(DUA16 [27] — IAA는 일반적으로 조회 의무 없음).',
           '4가지 extreme-circumstances 요소를 적용한다 — IAA가 알고 있었나, 시정이 단순했나, 결과가 중대했나, 정보가 손쉽게 확인 가능하고 결정적이었나.',
           '4개 모두 충족이면 → extreme → 비합리(CHK16). 일부 결여이면 → extreme 아님(DUA16).'
         ],
         issue:'IAA가 새 정보를 얻을 절차적 권한을 행사하지 않은 것이 언제 법적 비합리에 해당하는가.',
         conclusion:'CHK16: extreme 충족(제출 전체가 다른 사람의 사정) → 비합리. DUA16: 부분적 실수 → 비합리 아님.',
         keywords:['extreme circumstances','절차적 미행사','SZIAI','IAA','이민 대리인 부정'],
         facts:'두 신청인 모두 이민 대리인 부정으로 제출이 영향받은 사건 — CHK16은 제출 전체가 다른 사람의 사정, DUA16은 무관한 단락 몇 개. 연방항소법원이 같은 기준에서 반대 결론에 도달.'}},

  szai: {
    id:'szai', name:'Minister for Immigration and Citizenship v SZIAI', cite:'(2009) 83 ALJR 1123', icon:'?', color:'c-coral',
    topic:'W8', category:'Case',
    en:{ rule:'A tribunal\'s failure to make an inquiry on a critical fact that is readily ascertainable may, in narrow circumstances, be so unreasonable as to constitute jurisdictional error. There is no general duty to inquire — the failure must be tied to the particular case\'s extreme features.',
         principle:'SZIAI is the precursor to the CHK16 extreme-circumstances test. It establishes that failure to inquire CAN be unreasonable, but tightly bounded by (a) the fact being readily ascertainable and (b) of critical significance to the decision. CHK16 reformulated this as the fourth factor of the extreme-circumstances test.',
         when:'Build a failure-to-inquire argument in conjunction with CHK16 — SZIAI is the foundational authority; CHK16 the operative framework.',
         howApply:[
           'Identify the fact the tribunal failed to inquire about.',
           'Apply the two SZIAI conditions — readily ascertainable + critical significance.',
           'Embed within CHK16 four-factor framework to make out extreme circumstances.'
         ],
         issue:'Whether failure to inquire on a critical fact can amount to legal unreasonableness.',
         conclusion:'Yes — in narrow circumstances where the fact is readily ascertainable and of critical significance to the decision.',
         keywords:['failure to inquire','readily ascertainable','critical significance','no general duty'],
         facts:'Refugee Review Tribunal failed to verify country information available through ordinary means; held that in narrow circumstances such failure could be jurisdictional error.'},
    kr:{ rule:'심판소가 critical fact에 대해 — 그것이 readily ascertainable한데도 — 조회를 안 한 것이 좁은 상황에서는 법적 비합리로서 관할권적 오류에 해당할 수 있다. 일반적 조회 의무는 없다 — 사실 그 사건의 extreme한 특징에 묶여 있어야 한다.',
         principle:'SZIAI는 CHK16의 extreme-circumstances 테스트의 선구다. 조회 미실시가 비합리일 "수 있다"는 점은 인정하지만, (a) readily ascertainable, (b) decision에 critical significance라는 두 조건으로 좁게 묶는다. CHK16은 이를 extreme-circumstances 테스트의 네 번째 요소로 재정식화했다.',
         when:'조회 미실시 논증을 CHK16과 함께 구성할 때 — SZIAI는 토대 권위, CHK16은 운영 분석틀.',
         howApply:[
           '심판소가 조회를 안 한 사실을 식별한다.',
           'SZIAI의 두 조건을 적용한다 — readily ascertainable + critical significance.',
           'CHK16의 4-factor 분석틀 안에 끼워 넣어 extreme circumstances를 입증한다.'
         ],
         issue:'critical fact에 대한 조회 미실시가 법적 비합리에 해당할 수 있는가.',
         conclusion:'그렇다 — 사실이 readily ascertainable이고 결정에 critical significance라는 좁은 상황에서.',
         keywords:['조회 미실시','readily ascertainable','critical significance','일반적 의무 없음'],
         facts:'난민심사심판소가 통상 수단으로 확인 가능했던 출신국 정보를 검증하지 않은 사건. 좁은 상황에서 그 미실시가 관할권적 오류일 수 있다고 인정.'}},

  singh: {
    id:'singh', name:'Singh v Minister for Immigration and Border Protection', cite:'(2014) 231 FCR 437 (FCAFC)', icon:'∥', color:'c-coral',
    topic:'W8', category:'Case',
    en:{ rule:'Legal unreasonableness has two species: (i) process-focused (wrong principle applied, irrelevant consideration, disproportionate weight) — independent of outcome agreement; (ii) outcome-focused (absence of evident and intelligible justification — Li [76]). Both species attract the same high threshold.',
         principle:'Singh provides the clearest taxonomy of post-Li unreasonableness. The process-focused species is critical: it lets the court identify a specific reasoning defect without engaging in merits disagreement. This is the proper analytical route when the complaint is "the decision-maker used the wrong framework / weighed the wrong factor". Outcome-focused unreasonableness is reserved for cases where the result itself bespeaks error (Li [85]).',
         when:'Frame any post-Li unreasonableness argument — choose process-focused or outcome-focused species and stick with it.',
         howApply:[
           'Identify whether the alleged defect is process or outcome.',
           'Process-focused: point to wrong principle / irrelevant consideration / disproportionate weight — independent of outcome.',
           'Outcome-focused: argue absence of evident and intelligible justification — the result itself bespeaks error.'
         ],
         issue:'How should post-Li legal unreasonableness be analytically structured.',
         conclusion:'Two species — process-focused and outcome-focused — both attracting the high Li/SZVFW threshold.',
         keywords:['process-focused','outcome-focused','evident and intelligible justification','two species'],
         facts:'Tribunal review of visa cancellation; Full Federal Court used the case to articulate the two-species taxonomy of legal unreasonableness.'},
    kr:{ rule:'법적 비합리성은 두 갈래다 — (i) process-focused(잘못된 원칙 적용, 무관 고려, 비례성 잃은 가중치) — 결과 동의 여부와 독립; (ii) outcome-focused("명확하고 이해 가능한 정당화" 부재, Li [76]). 둘 다 같은 높은 문턱.',
         principle:'Singh는 post-Li 비합리성에 대한 가장 또렷한 분류표다. process-focused 종이 결정적이다 — 법원이 본안 동의에 빠지지 않고도 구체적 추론 결함을 짚을 수 있게 해 준다. "결정자가 잘못된 분석틀을 썼다 / 잘못된 요소를 형량했다"가 진짜 불만일 때 올바른 분석 경로. outcome-focused는 결과 자체가 오류를 드러내는 경우(Li [85])에 한정.',
         when:'post-Li 비합리성 논증을 짤 때 — process-focused / outcome-focused 중 하나를 골라 일관되게 간다.',
         howApply:[
           '주장하는 결함이 process인지 outcome인지 가른다.',
           'process-focused — 잘못된 원칙 / 무관 고려 / 비례성 잃은 가중치를 짚는다(결과와 독립).',
           'outcome-focused — "evident and intelligible justification"의 부재를 주장한다(결과 자체가 오류를 드러냄).'
         ],
         issue:'post-Li 법적 비합리성을 어떻게 분석적으로 구조화할 것인가.',
         conclusion:'두 갈래 — process-focused와 outcome-focused — 모두 Li/SZVFW의 높은 문턱을 적용.',
         keywords:['process-focused','outcome-focused','명확하고 이해 가능한 정당화','두 갈래'],
         facts:'비자 취소에 대한 심판소 심사 사건. 연방항소법원이 이 사건에서 법적 비합리성의 두 갈래 분류표를 정식화했다.'}},

  szvfw: {
    id:'szvfw', name:'Minister for Immigration and Border Protection v SZVFW', cite:'(2018) 264 CLR 541', icon:'△', color:'c-gray',
    topic:'W8', category:'Case',
    en:{ rule:'The threshold for legal unreasonableness remains very high post-Li. Mere disagreement with the outcome is not enough — the decision must be unreasonable in the strict legal sense. Appellate courts reviewing primary judges\' unreasonableness findings must give appropriate weight to the primary judge\'s evaluation, but reasonableness is an objective standard, not requiring House v The King-style appellate deference.',
         principle:'SZVFW is the post-Li reaffirmation that Li did NOT lower the threshold for unreasonableness — it changed the language more than the substance. Standard caution against merits review remains. Combine SZVFW with Stretton (substantive ministerial deference) when defending a decision against unreasonableness challenge.',
         when:'Defensive citation — rebut over-extension of Li; emphasise stringency of the test.',
         howApply:[
           'Concede Li reformulated unreasonableness in positive terms.',
           'Argue SZVFW: threshold remains very high; mere disagreement is insufficient.',
           'Combine with Stretton substantive-power deference where applicable.'
         ],
         issue:'Whether Li lowered the unreasonableness threshold; the role of appellate review of unreasonableness findings.',
         conclusion:'No lowering — threshold remains stringent. Reasonableness is an objective standard.',
         keywords:['high threshold','post-Li','appellate review','objective standard'],
         facts:'Tribunal dismissed an application after the applicant did not attend a hearing; primary judge found unreasonableness, appellate court reversed. HCA confirmed high threshold.'},
    kr:{ rule:'법적 비합리성의 문턱은 post-Li에서도 매우 높게 유지된다. 결과에 단순히 동의하지 않는 것으로는 부족 — 결정이 엄격한 법적 의미에서 비합리적이어야 한다. 항소심이 1심의 비합리성 판단을 검토할 때 1심 평가에 적절한 비중을 두어야 하지만, 합리성은 객관적 기준이지 House v The King 식 항소 deference를 요구하지 않는다.',
         principle:'SZVFW는 Li가 비합리성 문턱을 낮추지 않았다는 post-Li 재확인이다 — Li는 실질보다 표현을 바꾼 셈. 본안 심사에 대한 일반적 경계는 그대로다. SZVFW를 Stretton(실체적 장관 deference)과 결합해, 비합리성 공격에서 결정을 방어한다.',
         when:'방어적 인용 — Li의 과도한 확장을 반박할 때, 테스트의 엄격함을 강조할 때.',
         howApply:[
           'Li가 비합리성을 긍정적 정식으로 재구성했다는 점은 인정한다.',
           'SZVFW를 들어 문턱이 여전히 매우 높고 단순한 이견으로는 부족하다고 주장한다.',
           '필요하면 Stretton의 실체적 권한 deference와 결합한다.'
         ],
         issue:'Li가 비합리성 문턱을 낮췄는지, 그리고 비합리성 판단에 대한 항소 심사의 역할.',
         conclusion:'낮추지 않았다 — 문턱은 여전히 엄격. 합리성은 객관적 기준.',
         keywords:['높은 문턱','post-Li','항소 심사','객관적 기준'],
         facts:'심판소가 신청인 불출석 후 심사를 기각했고, 1심이 비합리성을 인정했으나 항소심이 뒤집은 사건. HCA가 높은 문턱을 재확인했다.'}},

  gypsy_jokers: {
    id:'gypsy_jokers', name:'Gypsy Jokers Motorcycle Club Inc v Commissioner of Police (WA)', cite:'(2008) 234 CLR 532', icon:'⛨', color:'c-blue',
    topic:'W10', category:'Case',
    en:{ rule:'A law that handicaps a party by limiting access to evidence does not, by that fact alone, deprive the court of jurisdiction — it merely means the court will arrive at its decision on less than the whole of the relevant materials. Where the reviewing court ITSELF can use the information underpinning the decision, the statutory scheme is constitutionally valid.',
         principle:'Gypsy Jokers is the foil case for Graham. Both involve secrecy / evidence-restriction; in Gypsy Jokers the court retained access (valid), in Graham the court was deprived in limine (invalid). The discriminator is who weighs and who sees: if the court → valid; if the executive → invalid as applied to s 75(v) review. Cite Gypsy Jokers when defending a secrecy scheme; distinguish it (Graham) when attacking.',
         when:'Defend a secrecy / evidence-control scheme — show the reviewing court can still see and weigh the protected material.',
         howApply:[
           'Identify the secrecy provision and ask: can the reviewing court itself use the protected information?',
           'If yes — Gypsy Jokers / K-Generation / Condon v Pompano / Totani pattern → valid.',
           'If no — court deprived in limine → Graham pattern → likely invalid as applied to s 75(v) HCA / s 476A FCA review.'
         ],
         issue:'Whether a WA fortification-removal regime that restricted disclosure was constitutionally valid.',
         conclusion:'Valid — the reviewing court itself could use the protected information, even though parties\' access was limited.',
         keywords:['handicap','court access','valid secrecy','contrast with Graham'],
         facts:'WA legislation allowed the Commissioner of Police to declare premises for fortification removal based on confidential information; review court itself could use the information.'},
    kr:{ rule:'증거 접근 제한으로 당사자에게 handicap을 주는 법이라고 해서 그 자체로 법원의 관할을 박탈하지는 않는다 — 그냥 법원이 모든 관련 자료보다 적은 것으로 결정에 이른다는 뜻일 뿐이다. 심사 법원 자신이 결정 기초 정보를 사용할 수 있다면 그 법정 체계는 헌법적으로 유효하다.',
         principle:'Gypsy Jokers는 Graham의 거울 케이스다. 둘 다 비밀·증거 제한을 다루는데, Gypsy Jokers는 법원이 접근을 유지(합헌), Graham은 법원이 처음부터 박탈(무효). 가르는 선은 — 누가 보는가, 누가 비교형량하는가. 법원이면 합헌, 행정부면 s 75(v) 심사 적용 범위에서 무효. 비밀 체계를 방어할 땐 Gypsy Jokers, 공격할 땐 Graham으로 구별.',
         when:'비밀·증거 통제 체계를 방어할 때 — 심사 법원이 여전히 보호된 자료를 보고 비교형량할 수 있음을 보인다.',
         howApply:[
           '비밀조항을 식별하고 묻는다 — 심사 법원 자신이 보호된 정보를 사용할 수 있는가.',
           '있다면 — Gypsy Jokers / K-Generation / Condon / Totani 패턴 → 합헌.',
           '없다면 — 법원이 처음부터 박탈 → Graham 패턴 → s 75(v) HCA / s 476A FCA 심사 적용에서 무효 가능성 높음.'
         ],
         issue:'증거 공개를 제한한 WA의 fortification removal 체계가 헌법적으로 유효한가.',
         conclusion:'유효 — 심사 법원 자신이 보호된 정보를 사용할 수 있었기 때문(당사자 접근은 제한됐어도).',
         keywords:['handicap','법원 접근','합헌 비밀','Graham과의 대비'],
         facts:'WA 법령이 경찰청장에게 비밀 정보에 근거해 시설 제거를 위한 건물 선언을 허용했고, 심사 법원 자체는 그 정보를 사용할 수 있었던 사건.'}},

  maccormick: {
    id:'maccormick', name:'MacCormick v Federal Commissioner of Taxation', cite:'(1984) 158 CLR 622', icon:'⊕', color:'c-ochre',
    topic:'W10', category:'Case',
    en:{ rule:'A Commonwealth tax cannot be made "incontestable" — Parliament cannot place the limits of the federal taxation power beyond judicial examination. Some contestability is constitutionally required; for the ITAA, Pt IVC of the Taxation Administration Act 1953 (Cth) supplies the necessary alternative review pathway.',
         principle:'MacCormick is the constitutional foundation for the validity of s 175 ITAA in Futuris. Because Pt IVC provides taxpayers with objection rights and review, the no-invalidity clause does not render the tax incontestable — contestability is preserved through the alternative mechanism. Confirmed by Richard Walter (1995). Cite when defending no-invalidity clauses; the alternative review pathway is the constitutional saving feature.',
         when:'Defend a no-invalidity clause against constitutional challenge — point to the alternative review pathway as the contestability mechanism.',
         howApply:[
           'Identify the no-invalidity clause (e.g., s 175 ITAA).',
           'Locate the alternative review pathway (e.g., Pt IVC TAA).',
           'Argue that contestability is preserved → no constitutional vice → clause valid (Futuris).'
         ],
         issue:'Whether a Commonwealth tax statute can validly preclude judicial examination of the tax\'s validity.',
         conclusion:'No — a tax cannot be made incontestable. Some review must remain to test the limits of the taxation power.',
         keywords:['incontestability','constitutional review','alternative pathway','Pt IVC'],
         facts:'Challenge to ITAA provisions; High Court confirmed that tax legislation must remain open to judicial examination of validity.'},
    kr:{ rule:'영연방 조세는 "incontestable"하게(다툴 수 없게) 만들 수 없다 — 의회는 연방 과세권의 한계를 사법 심사 너머로 옮길 수 없다. 어느 정도의 contestability가 헌법적으로 요구되며, ITAA에 대해서는 Taxation Administration Act 1953 (Cth) Pt IVC가 필요한 대체 심사 경로를 제공한다.',
         principle:'MacCormick은 Futuris에서 s 175 ITAA가 유효한 이유의 헌법적 토대다. Pt IVC가 납세자에게 이의 제기·심사 권리를 주기 때문에 no-invalidity 조항이 조세를 incontestable로 만들지 않는다 — contestability가 대체 메커니즘으로 보존된다. Richard Walter(1995)가 재확인. no-invalidity 조항을 방어할 때 인용 — 대체 심사 경로가 헌법적 saving feature.',
         when:'no-invalidity 조항을 헌법적 다툼에서 방어할 때 — 대체 심사 경로를 contestability 메커니즘으로 짚는다.',
         howApply:[
           'no-invalidity 조항을 식별한다(예: s 175 ITAA).',
           '대체 심사 경로를 찾는다(예: Pt IVC TAA).',
           'contestability가 보존됐다고 주장 → 헌법적 결함 없음 → 조항 유효(Futuris).'
         ],
         issue:'영연방 조세 법령이 그 조세의 유효성에 대한 사법심사를 적법하게 차단할 수 있는가.',
         conclusion:'없다 — 조세는 incontestable로 만들 수 없다. 과세권의 한계를 검증할 어떤 심사는 남아야 한다.',
         keywords:['incontestability','헌법적 심사','대체 경로','Pt IVC'],
         facts:'ITAA 조항에 대한 다툼. High Court가 조세 법령이 유효성 사법심사에 열려 있어야 한다고 확인했다.'}},

  animals_angels: {
    id:'animals_angels', name:"Animals' Angels e V v Secretary, Department of Agriculture", cite:'(2014) 228 FCR 35 (FCAFC)', icon:'⌘', color:'c-forest',
    topic:'W9', category:'Case',
    en:{ rule:'Standing as "person aggrieved" under the ADJR Act does not require a unique or strongest interest. A foreign organisation with prior involvement in the regulatory area, government recognition as a stakeholder, and demonstrated expertise can have a sufficient interest, even without Australian membership.',
         principle:'Animals\' Angels demonstrates the modern shift from a pure interest model toward an enforcement model of standing. The case extends recognised-advocacy-body standing (NCEC pattern) to foreign organisations, provided substantive involvement and government recognition are established. It supports the broader proposition (Bateman\'s Bay; Argos) that the special-interest test is "enabling, not restrictive".',
         when:'Argue standing for an advocacy body without traditional Australian membership; build the "enforcement model" angle.',
         howApply:[
           'Establish the body\'s long-standing involvement in the regulatory area.',
           'Identify government recognition (consultation, formal stakeholder status).',
           'Show expertise / specialist engagement; rebut "no Australian membership" objection — substantive interest is sufficient.'
         ],
         issue:'Whether a foreign animal-welfare organisation could have standing to challenge a live-animal export decision.',
         conclusion:'Yes — prior involvement, government recognition, and expertise were sufficient even without Australian membership.',
         keywords:['enforcement model','foreign organisation','recognised advocacy','person aggrieved'],
         facts:'A German animal-welfare organisation challenged decisions affecting a live-animal exporter; the Full Federal Court recognised its standing under the ADJR Act.'},
    kr:{ rule:'ADJR Act상 "person aggrieved" 자격은 unique한 이해나 가장 강한 이해를 요구하지 않는다. 규제 분야의 사전 관여, 정부의 이해관계자 인정, 전문성을 갖춘 외국 단체도 — 호주 회원이 없어도 — 충분한 이해를 가질 수 있다.',
         principle:'Animals\' Angels는 standing이 순수한 이해 모델에서 enforcement 모델로 옮겨 가는 현대적 흐름을 보여 준다. 인정받은 옹호 단체 standing(NCEC 패턴)을 외국 단체로 확장 — 실질적 관여와 정부 인정이 있다면. Bateman\'s Bay / Argos가 말한 "special interest 테스트는 enabling이지 restrictive가 아니다"라는 명제를 뒷받침한다.',
         when:'전통적 호주 회원 기반이 없는 옹호 단체의 standing을 주장할 때; "enforcement 모델" 각도를 세울 때.',
         howApply:[
           '그 단체의 규제 분야 장기 관여를 입증한다.',
           '정부의 인정(협의·공식 이해관계자 지위)을 짚는다.',
           '전문성·전문 관여를 보이고, "호주 회원이 없다"는 반박을 막는다 — 실질적 이해로 충분.'
         ],
         issue:'외국 동물복지 단체가 산 동물 수출 결정을 다툴 standing을 가질 수 있는가.',
         conclusion:'있다 — 호주 회원이 없어도 사전 관여, 정부 인정, 전문성으로 충분.',
         keywords:['enforcement 모델','외국 단체','인정받은 옹호','person aggrieved'],
         facts:'독일의 동물복지 단체가 산 동물 수출자에 영향을 미치는 결정을 다툰 사건. 연방항소법원이 ADJR Act상 standing을 인정.'}},

  oshea: {
    id:'oshea', name:"South Australia v O'Shea", cite:'(1987) 163 CLR 378', icon:'⏱', color:'c-coral',
    topic:'W5', category:'Case',
    en:{ rule:'A denial of procedural fairness at one stage of a process can only be cured WITHIN the same single procedure leading to one ultimate decision. Separate and distinct functions performed by different bodies cannot cure each other\'s PF breaches.',
         principle:'O\'Shea sets the boundary on the "PF can be cured" defence. The Crown often argues "a hearing will be available later — at parliamentary review / executive consideration / appeal". O\'Shea limits that argument: cure is possible only within one continuous procedure by the same decision-maker (or a body integrated into the same statutory function). Separate processes — even subsequent ones — do not cure earlier breaches.',
         when:'Rebut Crown\'s "another hearing will be available later" defence to a PF claim.',
         howApply:[
           'Identify the PF breach and the stage at which it occurred.',
           'Identify the "curing" process the Crown points to — is it the same procedure or a separate function?',
           'If separate — no cure (O\'Shea). If same continuous procedure under the same statutory power — cure may be available.'
         ],
         issue:'Can a procedural fairness breach by one body be cured by a subsequent hearing before a different body.',
         conclusion:'No — separate and distinct functions cannot cure each other. Cure requires the same single procedure.',
         keywords:['PF cure','same procedure','separate functions','denial cannot be cured'],
         facts:'Parole decision under SA legislation; question whether earlier denial of PF could be cured by later executive review. High Court held cure available only within the same procedure.'},
    kr:{ rule:'한 단계에서의 PF 거부는, 하나의 종국 결정으로 이어지는 같은 단일 절차 안에서만 치유될 수 있다. 다른 기관이 수행하는 별개·분리된 기능은 서로의 PF 위반을 치유하지 못한다.',
         principle:'O\'Shea는 "PF는 치유될 수 있다"는 방어의 경계선을 긋는다. Crown은 자주 "나중에 의회 심사 / 행정 재고 / 항소에서 청문이 있을 것"이라 주장한다. O\'Shea는 그 주장을 한정한다 — 치유는 같은 결정자(또는 같은 법령 기능에 통합된 기관)가 수행하는 하나의 연속 절차 안에서만 가능. 별개 절차는, 후속이라도, 이전 위반을 치유하지 못한다.',
         when:'PF 위반에 대한 "나중에 다른 청문이 있을 것"이라는 Crown 방어를 반박할 때 인용.',
         howApply:[
           'PF 위반과 발생 단계를 식별한다.',
           'Crown이 가리키는 "치유" 절차를 짚는다 — 같은 절차인가, 별개 기능인가.',
           '별개라면 치유 없음(O\'Shea). 같은 법령 권한 아래의 연속 절차라면 치유 가능성 있음.'
         ],
         issue:'한 기관의 PF 위반을 그 후 다른 기관의 청문이 치유할 수 있는가.',
         conclusion:'없다 — 별개·분리된 기능은 서로를 치유하지 못한다. 치유에는 같은 단일 절차가 필요.',
         keywords:['PF 치유','같은 절차','별개 기능','거부는 치유 불가'],
         facts:'SA 법령상 가석방 결정에서, 이전의 PF 거부를 후속 행정 재고가 치유할 수 있는지가 쟁점이었다. High Court가 치유는 같은 절차 안에서만 가능하다고 판시.'}},

  /* ─── 2026 B안 추가: 시험 인용 빈도 높은 보조 판례들 ─── */

  stead: {
    id:'stead', name:'Stead v State Government Insurance Commission', cite:'[1986] HCA 54; (1986) 161 CLR 141', icon:'⊝', color:'c-coral',
    topic:'W5', category:'Case',
    en:{ rule:'Where a denial of procedural fairness has occurred, it is "no easy task" for the respondent to demonstrate that the breach could have made no difference to the outcome. The court will readily infer that a fair hearing could have produced different submissions or evidence.',
         principle:'Stead supplies the operative inferential default for PF materiality. It was decided long before Hossain but its reasoning was absorbed into the modern materiality framework — most directly in WZARH and Nathanson. Together with LPDT (no reconstruction), Stead\'s "no easy task" formulation is the practical reason PF materiality is rarely defeated.',
         when:'Cite Stead in any PF case where the respondent argues the breach was immaterial — the burden of showing "could not possibly have made a difference" rests heavily on the respondent.',
         howApply:[
           'Establish the PF breach first (Kioa default + Saeed clear-words).',
           'Cite Stead — respondent bears practical onus and "no easy task" to negate the realistic possibility.',
           'Pair with Nathanson (low PF bar) and LPDT (no reconstruction) for the modern framework.'
         ],
         issue:'How heavy a burden lies on the respondent to negate the materiality of a procedural fairness breach.',
         conclusion:'Very heavy — "no easy task". The court readily infers that fair process could have made a difference.',
         keywords:['no easy task','PF materiality inference','onus shift in practice'],
         facts:'Insurance commissioner\'s decision was challenged for procedural fairness breach; the High Court articulated the practical onus principle.'},
    kr:{ rule:'PF 거부가 있었던 경우, 그 위반이 결과에 아무런 차이를 만들 수 없었음을 입증하는 것은 피고에게 "쉽지 않은 일(no easy task)"이다. 법원은 공정한 청문이라면 다른 의견·증거가 제출될 수 있었음을 손쉽게 추론한다.',
         principle:'Stead는 PF materiality에 대한 운영적·추론적 기본값을 깐 판례다. Hossain보다 한참 앞서지만, 그 추론이 현대 materiality 분석틀에 흡수됐다 — 특히 WZARH와 Nathanson에서. LPDT(재구성 금지)와 함께, Stead의 "no easy task" 정식이 PF materiality가 좀처럼 깨지지 않는 실무적 이유다.',
         when:'PF 사건에서 피고가 "위반이 결과를 바꾸지 않았다"고 주장할 때 — "could not possibly have made a difference"를 보이는 부담이 피고에게 무겁게 있다고 반박.',
         howApply:[
           '먼저 PF 위반을 입증한다(Kioa 기본 + Saeed 명시 문언).',
           'Stead를 인용한다 — 피고에게 실무적 입증 부담이 있고 "쉽지 않다".',
           'Nathanson(낮은 PF 문턱), LPDT(재구성 금지)와 함께 현대 분석틀로 짠다.'
         ],
         issue:'PF 위반의 materiality를 부정하기 위해 피고에게 얼마나 무거운 입증 부담이 있는가.',
         conclusion:'매우 무겁다 — "쉽지 않은 일". 법원은 공정 절차가 차이를 만들 수 있었음을 손쉽게 추론.',
         keywords:['no easy task','PF materiality 추론','실무적 입증 책임'],
         facts:'보험위원회의 결정이 PF 위반으로 다투어진 사건. High Court가 실무적 입증 부담 원칙을 정식화했다.'}},

  yusuf: {
    id:'yusuf', name:'Re Minister for Immigration and Multicultural Affairs; Ex parte Yusuf', cite:'[2001] HCA 30; (2001) 206 CLR 323', icon:'☷', color:'c-blue',
    topic:'W7', category:'Case',
    en:{ rule:'A failure to take into account a mandatory consideration is a jurisdictional error. The error is characterised as going to the lawful constitution of the decision-making power itself, not merely to its exercise. This jurisdictional characterisation matters for both the availability of constitutional writs and for the relationship between the relevant-considerations ground and Hossain materiality.',
         principle:'Yusuf confirms the jurisdictional character of the relevant-considerations ground, completing the doctrinal pairing with Peko-Wallsend (substantive framework). Cite Yusuf to anchor the jurisdictional nature of a Peko-Wallsend breach when arguing for s 75(v) constitutional writ relief.',
         when:'Once a Peko-Wallsend breach is established, cite Yusuf to characterise it as jurisdictional error attracting the s 75(v) / s 39B writ jurisdiction.',
         howApply:[
           'Run the Peko-Wallsend analysis to establish a relevant-considerations breach.',
           'Cite Yusuf to confirm the breach is jurisdictional error (not merely error of law on the face of the record).',
           'Move to remedies — certiorari + mandamus available; privative clauses cannot oust under S157.'
         ],
         issue:'Whether a failure to take into account a mandatory relevant consideration constitutes jurisdictional error.',
         conclusion:'Yes — the error goes to the lawful exercise of power and is reviewable by constitutional writ.',
         keywords:['jurisdictional character','mandatory consideration','constitutional writs','Peko complement'],
         facts:'Tribunal review of refugee determination; characterisation of the relevant-considerations error was at issue. High Court confirmed jurisdictional character.'},
    kr:{ rule:'반드시 고려해야 할 사항을 누락한 것은 관할권적 오류이다. 그 오류는 결정 권한의 적법한 구성 자체에 가는 것으로 성격이 정해지지, 단순히 권한 행사 방식에 가는 것이 아니다. 이 관할권적 성격은 헌법적 writ 가용성과 Peko-Wallsend / Hossain materiality의 관계 양쪽에서 중요하다.',
         principle:'Yusuf는 관련 고려사항 사유의 관할권적 성격을 확인해, Peko-Wallsend(실체적 분석틀)와 교리적 짝을 완성한다. Peko-Wallsend 위반을 s 75(v) 헌법적 writ 구제로 가져갈 때, Yusuf를 들어 그 위반의 관할권적 성격을 정초한다.',
         when:'Peko-Wallsend 위반을 입증한 다음, 그 위반이 관할권적 오류임을 Yusuf로 확인하고 s 75(v) / s 39B writ로 간다.',
         howApply:[
           'Peko-Wallsend 분석으로 관련 고려사항 위반을 입증.',
           'Yusuf로 그 위반이 관할권적 오류(단순한 face of record 법적 오류가 아니라)임을 확인.',
           '구제로 — certiorari + mandamus 가능. S157에 따라 배제조항도 봉쇄 불가.'
         ],
         issue:'반드시 고려해야 할 사항의 누락이 관할권적 오류에 해당하는가.',
         conclusion:'그렇다 — 그 오류는 권한의 적법한 행사에 가며 헌법적 writ로 심사 가능.',
         keywords:['관할권적 성격','강행 고려사항','헌법적 writ','Peko 보완'],
         facts:'난민 결정에 대한 심판소 심사 사건. 관련 고려사항 오류의 성격이 다투어졌고, High Court가 관할권적 성격을 확인.'}},

  boilermakers: {
    id:'boilermakers', name:'R v Kirby; Ex parte Boilermakers\' Society of Australia', cite:'[1956] HCA 10; (1956) 94 CLR 254', icon:'⛓', color:'c-blue',
    topic:'W2', category:'Case',
    en:{ rule:'Under Ch III of the Constitution, federal courts can exercise only judicial power; non-judicial functions cannot be vested in federal courts. The strict separation of powers in the Australian federal system is stricter than the UK/NZ approach and explains why merits review is institutionally located in tribunals (now ART), not courts.',
         principle:'Boilermakers anchors the legality/merits divide in constitutional separation of powers, not just doctrinal preference. Quin (Brennan J) translates the constitutional principle into administrative-law doctrine — courts review legality only, not merits, because merits review = non-judicial power and federal courts cannot exercise it. This is why Australian admin law rejects substantive doctrines (e.g. UK substantive legitimate expectations) that other jurisdictions accept.',
         when:'Cite Boilermakers as the constitutional basis for the legality/merits divide, particularly in argument-style essays asking why Australian admin law is stricter than UK/NZ.',
         howApply:[
           'Frame the legality/merits divide as a question of constitutional separation of powers under Ch III.',
           'Cite Quin to translate the principle into the administrative-law form.',
           'Use to defeat substantive merits arguments dressed up as legality grounds.'
         ],
         issue:'Whether federal courts can validly exercise non-judicial functions under the Constitution.',
         conclusion:'No — Ch III restricts federal courts to judicial power only. Non-judicial functions (including merits review) must be located in non-court bodies.',
         keywords:['separation of powers','Ch III','federal courts','judicial power only','legality/merits constitutional basis'],
         facts:'Industrial arbitration commission challenged for exercising mixed judicial/non-judicial functions; High Court held federal courts cannot validly exercise non-judicial powers.'},
    kr:{ rule:'헌법 Ch III 아래에서 연방법원은 사법권만 행사할 수 있다. 비-사법 기능은 연방법원에 부여될 수 없다. 호주 연방 체계의 엄격한 권력분립은 영국·뉴질랜드보다 더 엄격하며, 이것이 실체심사가 법원이 아닌 심판소(현 ART)에 제도적으로 위치하는 이유다.',
         principle:'Boilermakers는 적법성·본안 구분을 단순한 교리적 선호가 아니라 헌법적 권력분립에 닻을 내린다. Quin(Brennan J)이 이 헌법 원칙을 행정법 교리 형태로 옮긴다 — 법원은 적법성만 심사하고 본안은 보지 않는다, 왜냐하면 본안 심사 = 비-사법권이고 연방법원은 그것을 행사할 수 없기 때문이다. 호주 행정법이 영국·뉴질랜드가 받아들이는 실체적 법리들(예: substantive legitimate expectations)을 거부하는 이유.',
         when:'적법성·본안 구분의 헌법적 토대로 인용 — 특히 "왜 호주 행정법이 영국·뉴질랜드보다 엄격한가"를 묻는 논술 형 문제에서.',
         howApply:[
           '적법성·본안 구분을 Ch III의 권력분립 문제로 framing.',
           'Quin을 들어 그 원칙을 행정법 형태로 번역.',
           '적법성 사유로 위장한 실체적 본안 주장을 깨는 데 사용.'
         ],
         issue:'연방법원이 헌법 아래에서 비-사법 기능을 적법하게 행사할 수 있는가.',
         conclusion:'없다 — Ch III가 연방법원을 사법권에 한정. 비-사법 기능(실체심사 포함)은 비-법원 기관에 위치해야 한다.',
         keywords:['권력분립','Ch III','연방법원','사법권만','적법성/본안 헌법적 토대'],
         facts:'산업 중재위원회가 사법·비-사법 혼합 기능 행사로 다투어진 사건. High Court가 연방법원이 비-사법권을 적법하게 행사할 수 없다고 판시.'}},

  fjbloemen: {
    id:'fjbloemen', name:'F J Bloemen Pty Ltd v Federal Commissioner of Taxation', cite:'[1981] HCA 27; (1981) 147 CLR 360', icon:'⊘', color:'c-gray',
    topic:'W10', category:'Case',
    en:{ rule:'(Mason and Wilson JJ — overruled in part by Futuris.) An assessment under s 175 ITAA was protected from review even where the Commissioner had not acted bona fide, leaving open whether deliberate failures were within s 175\'s protection. This proposition was expressly disapproved by Futuris (2008): deliberate failures (conscious maladministration) "manifest jurisdictional error" and are NOT shielded.',
         principle:'FJ Bloemen is the case Futuris partially overrules. Cite it to mark the historical position before the conscious-maladministration carve-out was established. The doctrinal lesson is that no-invalidity clauses never authorise deliberate wrongdoing — even where the language is sweeping, statutory purpose interpreted in light of integrity duties (s 13 Public Service Act) and the rule of law cuts back protection.',
         when:'Comparative / historical citation to show the evolution from FJ Bloemen → Futuris. Useful in essay questions about how no-invalidity doctrine has tightened.',
         howApply:[
           'Acknowledge the FJ Bloemen position as the older reading of s 175.',
           'Cite Futuris\'s express disapproval — "should not be followed" insofar as it suggests s 175 reaches deliberate failures.',
           'Apply the modern position: conscious maladministration always remains JE and attracts s 75(v) / s 39B writs.'
         ],
         issue:'Whether s 175 ITAA protects assessments tainted by lack of bona fides.',
         conclusion:'(Per Futuris) — No. Conscious maladministration is always reviewable. FJ Bloemen\'s broader reading is no longer good law.',
         keywords:['overruled in part','no-invalidity scope','conscious maladministration','Futuris evolution'],
         facts:'Tax assessment challenged for lack of bona fides; Mason and Wilson JJ\'s broader protective reading of s 175 was later trimmed by Futuris.'},
    kr:{ rule:'(Mason과 Wilson JJ — Futuris에서 부분 overrule.) Commissioner가 bona fide하지 않게 행위했더라도 s 175 ITAA의 과세가 심사로부터 보호된다고 보고, 의도적 위반이 s 175 보호 안에 들어가는지를 열어 두었다. 이 명제는 Futuris(2008)가 명시적으로 거부했다 — 의도적 위반(conscious maladministration)은 "관할권적 오류를 드러내고" 보호받지 못한다.',
         principle:'FJ Bloemen은 Futuris가 부분적으로 overrule한 판례다. 의도적 위반 carve-out이 확립되기 전의 역사적 입장을 표시할 때 인용. 교리적 교훈은 — no-invalidity 조항은 결코 의도적 위법을 수권하지 않는다는 것. 문언이 폭넓더라도 청렴 의무(s 13 Public Service Act)와 법치의 빛에서 해석된 법령 목적이 보호를 좁힌다.',
         when:'비교법·역사적 인용 — FJ Bloemen에서 Futuris로의 진화를 보일 때. no-invalidity 법리가 어떻게 좁혀졌는지를 묻는 논술에서 유용.',
         howApply:[
           'FJ Bloemen의 입장을 s 175의 옛 해석으로 인정한다.',
           'Futuris의 명시적 거부를 인용 — "should not be followed" (의도적 위반에까지 미친다는 시사에 한해).',
           '현대 입장을 적용 — 의도적 행정부정은 늘 JE로 남으며 s 75(v) / s 39B writ를 발동시킨다.'
         ],
         issue:'s 175 ITAA가 bona fides 결여로 흠 있는 과세를 보호하는가.',
         conclusion:'(Futuris에 따라) — 보호하지 않는다. 의도적 행정부정은 늘 심사 대상. FJ Bloemen의 넓은 해석은 더 이상 유효한 법이 아니다.',
         keywords:['부분 overrule','no-invalidity 범위','의도적 행정부정','Futuris 진화'],
         facts:'bona fides 결여로 과세가 다투어진 사건. Mason과 Wilson JJ의 넓은 보호적 해석이 Futuris에서 좁혀졌다.'}},

  glennan: {
    id:'glennan', name:'Glennan v Federal Commissioner of Taxation', cite:'[2003] HCA 31; (2003) 198 ALR 250', icon:'⏳', color:'c-gray',
    topic:'W10', category:'Case',
    en:{ rule:'Relief under s 75(v) / s 39B(1) may be — and often will be — withheld in the exercise of discretion where an alternative statutory remedy (such as Pt IVC of the Taxation Administration Act) is available to the applicant.',
         principle:'Glennan articulates the discretionary withholding principle. The s 75(v) jurisdiction is constitutionally entrenched and cannot be removed, but the *exercise* of that jurisdiction is discretionary. Where Parliament has provided an alternative review mechanism that adequately addresses the applicant\'s grievance, the constitutional writs are typically refused. Pair with Re McBain.',
         when:'Defending against a constitutional-writ application where an alternative review path (Pt IVC, ART, statutory appeal) exists.',
         howApply:[
           'Establish that the applicant has access to an alternative statutory remedy.',
           'Argue Glennan / Re McBain — the court should withhold s 75(v) / s 39B relief in favour of the dedicated pathway.',
           'Distinguish where the alternative remedy is illusory or inadequate (e.g. character-test bar in protection-visa context).'
         ],
         issue:'Whether s 75(v) / s 39B relief can be withheld where an alternative Pt IVC pathway is available.',
         conclusion:'Yes — discretionary withholding is appropriate where the alternative remedy is genuinely available.',
         keywords:['discretionary withholding','alternative remedy','Pt IVC','constitutional writs not automatic'],
         facts:'Tax assessment challenged via s 75(v); High Court emphasised the discretionary character of constitutional writ relief where Pt IVC was available.'},
    kr:{ rule:'s 75(v) / s 39B(1)의 구제는 — 종종 — 신청인에게 대체 법정 구제(예: Taxation Administration Act Pt IVC)가 가능한 경우 재량으로 거부될 수 있다.',
         principle:'Glennan은 재량적 거부 원칙을 정식화한다. s 75(v) 관할은 헌법적으로 보호되어 제거될 수 없지만, 그 관할의 *행사*는 재량이다. 의회가 신청인의 불만을 적절히 다룰 대체 심사 메커니즘을 제공한 경우, 헌법적 writ는 통상 거부된다. Re McBain과 짝짓는다.',
         when:'대체 심사 경로(Pt IVC, ART, 법정 항소 등)가 있는 상황에서 헌법적 writ 신청을 방어할 때.',
         howApply:[
           '신청인이 대체 법정 구제에 접근할 수 있음을 입증.',
           'Glennan / Re McBain을 들어, 법원이 전담 경로를 우선해 s 75(v) / s 39B 구제를 거부해야 한다고 주장.',
           '대체 구제가 환상적이거나 부적절한 경우(예: 보호비자 맥락의 character-test 차단)는 구별.'
         ],
         issue:'대체 Pt IVC 경로가 있을 때 s 75(v) / s 39B 구제가 재량으로 거부될 수 있는가.',
         conclusion:'그렇다 — 대체 구제가 실질적으로 가능하다면 재량적 거부가 적절.',
         keywords:['재량적 거부','대체 구제','Pt IVC','헌법적 writ 자동 아님'],
         facts:'s 75(v)를 통한 과세 다툼. Pt IVC가 가능한 상황에서 헌법적 writ 구제의 재량적 성격을 High Court가 강조.'}},

  rembcbain: {
    id:'rembcbain', name:'Re McBain; Ex parte Australian Catholic Bishops Conference', cite:'[2002] HCA 16; (2002) 209 CLR 372', icon:'⊝', color:'c-gray',
    topic:'W10', category:'Case',
    en:{ rule:'The High Court will withhold s 75(v) relief in the exercise of discretion where the applicant lacks a sufficient interest in the matter, or where the application is, in effect, an advisory opinion sought outside the ordinary adversarial framework. Discretionary considerations also extend to availability of alternative remedies.',
         principle:'Re McBain complements Glennan as the foundational discretionary-withholding authority. Where Glennan focuses on alternative-remedy availability, Re McBain focuses on the broader discretionary considerations — standing, justiciability, and the integrity of the adversarial process. Together they establish that s 75(v) jurisdiction is mandatory but its exercise is governed by discretion.',
         when:'Argue discretionary refusal where the application has standing or justiciability problems beyond mere availability of alternatives.',
         howApply:[
           'Identify the discretionary concern — standing, justiciability, alternative remedy, advisory-opinion character.',
           'Cite Re McBain (with Glennan) — exercise of s 75(v) jurisdiction is discretionary.',
           'Apply to the facts to argue for / against discretionary refusal.'
         ],
         issue:'Whether the High Court should exercise s 75(v) jurisdiction at the instance of an applicant whose interest in the matter is questioned.',
         conclusion:'Discretionary considerations may warrant refusal where standing / justiciability / alternative remedy considerations weigh against intervention.',
         keywords:['discretionary refusal','standing','justiciability','adversarial integrity'],
         facts:'Bishops Conference sought s 75(v) relief on a matter where their direct interest was questioned; HCA refused on discretionary grounds.'},
    kr:{ rule:'High Court는 신청인이 사안에 충분한 이해를 갖지 않거나, 신청이 사실상 통상의 대립당사자 구조 밖에서 구하는 advisory opinion일 때 재량으로 s 75(v) 구제를 거부할 수 있다. 재량적 고려는 대체 구제의 가용성으로도 확장된다.',
         principle:'Re McBain은 재량적 거부 권위로서 Glennan을 보완한다. Glennan이 대체 구제 가용성에 초점을 둔다면, Re McBain은 더 넓은 재량적 고려 — standing, 사법심사 적합성, 대립당사자 절차의 무결성 — 에 초점을 둔다. 두 판례가 함께 "s 75(v) 관할은 의무지만, 그 행사는 재량이다"를 정초.',
         when:'단순한 대체 구제 가용성을 넘어, standing이나 사법심사 적합성에 문제가 있는 신청에 재량 거부를 주장할 때.',
         howApply:[
           '재량적 우려를 식별 — standing, 사법심사 적합성, 대체 구제, advisory-opinion 성격.',
           'Re McBain (Glennan과 함께)을 인용 — s 75(v) 관할의 행사는 재량.',
           '사실관계에 적용해 재량 거부 찬반을 주장.'
         ],
         issue:'신청인의 사안에 대한 이해가 의문시될 때 High Court가 s 75(v) 관할을 행사해야 하는가.',
         conclusion:'standing / 사법심사 적합성 / 대체 구제 고려가 개입에 반할 때 재량적 거부가 정당화될 수 있다.',
         keywords:['재량적 거부','standing','사법심사 적합성','대립당사자 무결성'],
         facts:'Bishops Conference가 직접 이해가 의문시되는 사안에 s 75(v) 구제를 구한 사건. HCA가 재량적 사유로 거부.'}},

  forge: {
    id:'forge', name:'Forge v Australian Securities and Investments Commission', cite:'[2006] HCA 44; (2006) 228 CLR 45', icon:'⛨', color:'c-blue',
    topic:'W9', category:'Case',
    en:{ rule:'The defining characteristics of State Supreme Courts under Ch III of the Constitution — particularly their position at the apex of State judicial hierarchies and their supervisory jurisdiction — are constitutionally entrenched. State Parliaments cannot legislate to remove or substantially impair those defining characteristics.',
         principle:'Forge supplies the doctrinal foundation that Kirk later builds on. Both rest on the constitutional implication from Ch III + s 73(ii) that State Supreme Courts must retain their essential characteristics — the "Supreme Court of any State" the Constitution refers to must remain recognisable as such. Forge predates Kirk and provides the conceptual scaffolding; Kirk applies the principle specifically to supervisory jurisdiction over jurisdictional error.',
         when:'When defending the entrenched supervisory jurisdiction at State level, cite Forge alongside Kirk to show the constitutional foundation. Particularly useful in essays about why State privative clauses cannot oust JE review.',
         howApply:[
           'Establish the constitutional implication — Ch III + s 73(ii) presupposes the State Supreme Court as an institution with certain defining characteristics.',
           'Cite Forge for the general principle (defining characteristics entrenched).',
           'Cite Kirk for the specific application to supervisory jurisdiction over JE.'
         ],
         issue:'Whether State legislation can alter the defining characteristics of a State Supreme Court.',
         conclusion:'No — the defining characteristics are constitutionally entrenched under Ch III.',
         keywords:['defining characteristics','State Supreme Court','Ch III entrenchment','Kirk foundation'],
         facts:'Acting judges appointed to NSW Supreme Court; challenge to whether this impaired the court\'s defining characteristics. High Court articulated the entrenchment principle.'},
    kr:{ rule:'헌법 Ch III 아래에서 주(州) 대법원의 defining characteristics — 특히 주 사법 위계의 정점에 있다는 점과 감독관할 — 은 헌법적으로 보호된다. 주 의회는 그 defining characteristics를 제거하거나 실질적으로 손상시키도록 입법할 수 없다.',
         principle:'Forge는 Kirk가 이후에 세운 교리적 토대를 공급한다. 둘 다 Ch III + s 73(ii)에서 — 헌법이 가리키는 "주 대법원"이 그 본질을 유지해 인식 가능해야 한다는 — 헌법적 함의에 기반한다. Forge는 Kirk보다 앞서며 개념적 뼈대를 제공하고, Kirk는 그 원칙을 관할권적 오류에 대한 감독관할에 구체적으로 적용한다.',
         when:'주(州) 차원 보호된 감독관할을 방어할 때 Forge를 Kirk와 함께 인용해 헌법적 토대를 보인다. 주 배제조항이 왜 JE 심사를 봉쇄할 수 없는지를 묻는 논술에서 특히 유용.',
         howApply:[
           '헌법적 함의를 정초 — Ch III + s 73(ii)가 정의 가능한 특징을 갖춘 기관으로서 주 대법원을 전제.',
           'Forge를 일반 원칙(defining characteristics 보호)으로 인용.',
           'Kirk를 JE 감독관할에 대한 구체적 적용으로 인용.'
         ],
         issue:'주 입법이 주 대법원의 defining characteristics를 변경할 수 있는가.',
         conclusion:'없다 — defining characteristics는 Ch III 아래에서 헌법적으로 보호된다.',
         keywords:['defining characteristics','주 대법원','Ch III 보호','Kirk 토대'],
         facts:'NSW 대법원의 acting judge 임명이 다투어진 사건. 그것이 법원의 defining characteristics를 손상하는지에 관해 High Court가 보호 원칙을 정식화했다.'}},

  australian_communist: {
    id:'australian_communist', name:'Australian Communist Party v Commonwealth', cite:'[1951] HCA 5; (1951) 83 CLR 1', icon:'★', color:'c-ochre',
    topic:'W9', category:'Case',
    en:{ rule:'The rule of law is a constitutional assumption underpinning the entire structure of Australian government. Dixon J: "[a]mong these I think that it may fairly be said that the rule of law forms an assumption" on which the Constitution rests. Fullagar J: "in our system the principle of Marbury v Madison is accepted as axiomatic."',
         principle:'The Communist Party Case is the textual high-water mark for the rule of law in Australian constitutional jurisprudence. Modern decisions on s 75(v) entrenchment (Plaintiff S157, Graham), State supervisory jurisdiction (Kirk, Forge), and the legality / merits divide (Quin) all draw on this foundation. For any HD-level argument-style answer, citing Communist Party Case + Marbury together signals you understand the constitutional architecture.',
         when:'Foundational citation for rule-of-law and entrenchment arguments — pair with Marbury v Madison. Especially valuable in argument questions and conclusion sections.',
         howApply:[
           'Establish the rule of law as a constitutional assumption (Dixon J).',
           'Trace to Marbury v Madison as the foundational judicial-review principle (Fullagar J).',
           'Apply to the specific entrenchment / supervisory-jurisdiction / legality-merits argument.'
         ],
         issue:'Whether the Commonwealth Parliament could enact legislation declaring the Communist Party unlawful and dissolving it.',
         conclusion:'Invalid — Parliament could not "recite itself" into power under the defence power; the rule of law operates as a constitutional constraint on legislative competence.',
         keywords:['rule of law','constitutional assumption','Marbury axiomatic','foundation for S157/Kirk/Graham'],
         facts:'Cold-war legislation banning the Communist Party; HCA invalidated the Act and articulated the rule of law as a constitutional assumption.'},
    kr:{ rule:'법치는 호주 정부 구조 전체를 떠받치는 헌법적 전제다. Dixon J: "이 중에서 법치는 헌법이 의지하는 전제 중 하나라고 공정히 말할 수 있다." Fullagar J: "우리 체계에서 Marbury v Madison 원칙은 axiomatic하게 받아들여진다."',
         principle:'Communist Party Case는 호주 헌법 법리에서 법치의 텍스트적 최고점이다. s 75(v) 보호(Plaintiff S157, Graham), 주 감독관할(Kirk, Forge), 적법성·본안 구분(Quin)에 관한 현대 판결들이 모두 이 토대에 기댄다. HD급 논술 답안에서는 Communist Party Case와 Marbury를 함께 인용하면 헌법 구조에 대한 이해를 보여 줄 수 있다.',
         when:'법치·보호 주장의 토대 인용 — Marbury v Madison과 짝짓는다. 논술 문제와 결론 부분에서 특히 가치 있다.',
         howApply:[
           '법치를 헌법적 전제로 정초(Dixon J).',
           'Marbury v Madison을 사법심사의 토대 원칙으로 연결(Fullagar J).',
           '구체적 보호·감독관할·적법성-본안 주장에 적용.'
         ],
         issue:'영연방 의회가 공산당을 불법화하고 해산시키는 법령을 제정할 수 있는가.',
         conclusion:'무효 — 의회가 방위권 아래에서 "스스로 권한을 reciting"할 수 없다. 법치가 입법 권능에 대한 헌법적 제약으로 작동한다.',
         keywords:['법치','헌법적 전제','Marbury axiomatic','S157/Kirk/Graham 토대'],
         facts:'냉전기 공산당 금지 법령에 대한 사건. HCA가 그 법을 무효화하고 법치를 헌법적 전제로 정식화했다.'}},

};
